function newSession(queue,mode){return {id:uid('s'),childId:activeChild().id,queue,index:0,mode,startedAt:new Date().toISOString(),answer:'',selected:null,feedback:null,scored:0,played:false,audioStatus:'idle'};}
function storeCurrentSession(){db.savedSessions=db.savedSessions||{};if(db.session)db.savedSessions[db.session.childId]=db.session;}
function weakTypes(w){const latest=new Map();attemptsFor(w.id).filter(a=>!a.technical&&a.correct!==null&&(!a.assisted||a.correct===false)).forEach(a=>latest.set(a.type,a));return ['listenSpell','spell','sentence','cloze','missing','listenChoice','meaning'].filter(t=>latest.get(t)?.correct===false);}
