function awardAnswer(w,it){const ledger=dailyLedger(),key=norm(w.en)+'|'+it.type;if(ledger.rewardKeys.includes(key))return;ledger.rewardKeys.push(key);activeChild().stars++;}
function activateRange(id){const r=childRanges().find(x=>x.id===id);if(!r)return;const old=structuredClone(db);if(v24Policy().rangeLocks[activeChild().id]&&v23ParentAllowed())v24Policy().rangeLocks[activeChild().id]=id;activeChild().activeRangeId=id;db.session=null;if(!save()){db=old;return;}toast('已設為今次默書。');render();}
function captureImportDraft(){if(skipImportCapture){skipImportCapture=false;return;}if(!$('#range-title'))return;syncDraftInputs();importDraft.title=$('#range-title').value;importDraft.date=$('#range-date').value;importDraft.raw=$('#raw-words').value;importDraft.confirmed=$('#confirm-import')?.checked||false;}
