function legacyStopSpeech(){speechEpoch++;clearTimeout(speechTimeout);voiceBusy=false;try{window.speechSynthesis?.cancel();}catch(_){}if(typeof db!=='undefined'&&db.session&&['playing','loading'].includes(db.session.audioStatus)){db.session.audioStatus='idle';db.session.played=false;}renderAudioState();syncSubmit();}
