function gameValid(id){return !!(miniGame&&miniGame.id===id&&!miniGame.ended&&lastRoute==='gameplay');}
function gameLater(fn,ms){const id=miniGame?.id;const timer=setTimeout(()=>{miniTimers.delete(timer);if(!gameValid(id))return;if(Date.now()>=miniGame.deadline){finishMini('小休完了，回去學習吧。');return;}fn();},ms);miniTimers.add(timer);return timer;}
