function teacherMetaFor(text){const key=norm(text);const info=TEACHER_PATCH.entryMeta?.[key]||{};if(TEACHER_PATCH.memoryMap?.[key]&&!info.memoryAid)info.memoryAid=TEACHER_PATCH.memoryMap[key];return Object.keys(info).length?info:null;}
function memoryPanel(w){if(currentItem()?.type!=='study')return '';const info=teacherMetaFor(w?.en||'');if(!info)return '';const mem=info.memoryAid;return `<details class="memory-panel"><summary>記字小提示</summary>${mem?`<div class="parts">${mem.parts.map(p=>`<span class="part"><strong>${esc(p[0])}</strong><span class="small">${esc(p[1]||'')}</span></span>`).join('')}</div><p>${esc(mem.tip||'')}</p>`:''}${info.teacherNote?`<p class="teacher-tip">${esc(info.teacherNote)}</p>`:''}</details>`;}
/* Shared editorial dictionary adapter: fills suggestions only, never saves user data. */
const sharedEntries=window.WQ_SHARED_REFERENCE||[];
const sharedByKey=new Map(sharedEntries.map(e=>[norm(e.key),e]));
function sharedSuggestion(text){
 const entry=sharedByKey.get(norm(text));if(!entry)return null;
 const exactCase=entry.senses.filter(s=>s.headword===String(text).trim());
 const candidates=exactCase.length?exactCase:entry.senses;
 const meanings=[...new Set(candidates.map(s=>s.zhHK))];
 return {entry,meaning:meanings.length===1?meanings[0]:'',choices:meanings};
}
for(const e of sharedEntries){const unique=e.senses.length===1;dictionary[e.key]={zh:unique?e.senses[0].zhHK:'',ex:unique&&!e.requiresContextReview?(e.examples[0]?.en||''):'',emoji:MEDIA_CATALOG[e.key]?.emoji||''};}
const parseBeforeShared=parseRawWords;
parseRawWords=function(text){const rows=parseBeforeShared(text);for(const row of rows){const s=sharedSuggestion(row.en);if(!s)continue;const rawLine=String(text).split(/\r?\n/).find(l=>norm(l.replace(/^\s*\d+[.)、:]\s*/,'').split('|')[0])===norm(row.en));const supplied=rawLine?.includes('|')&&rawLine.slice(rawLine.indexOf('|')+1).trim();if(!supplied)row.zh=s.meaning;}return rows;};
const editorBeforeShared=renderWordEditor;
renderWordEditor=function(){editorBeforeShared();const box=$('#word-editor');if(!box||!draftWords.length)return;const missing=draftWords.filter(w=>!sharedByKey.has(norm(w.en))).length;const multi=draftWords.filter(w=>sharedByKey.has(norm(w.en))&&!w.zh).length;const note=document.createElement('p');note.className='notice';note.textContent=`已接入 ${sharedEntries.length.toLocaleString('en')} 個共用詞（教材草稿）。${multi?'有 '+multi+' 個詞可能有多個意思，請自己填寫今次要教的中文。':''}${missing?'有 '+missing+' 個詞未收錄，請補上意思。':''}原稿和你填寫的中文不會被改動。圖片要按意思核對。英式錄音還未全部內置。`;box.prepend(note);};
const imageBeforeShared=imageFor;
imageFor=function(w){const im=imageBeforeShared(w);if(!im||im.custom)return im;const s=w&&sharedByKey.get(norm(w.en));if(!s||s.senses.length===1)return im;const shownMeaning=String(w.zh||'').trim();return shownMeaning===String(im.meta.zh||'').trim()?im:null;};


// Hoisted validator also runs during startup load. It uses only the preloaded catalogue.
function validateFamilyLearning(raw,children){
 const out={version:1,children:{}};if(raw==null)return out;
 if(raw.version!==1||!raw.children||typeof raw.children!=='object'||Array.isArray(raw.children))throw Error('family schema');
 const ids=new Set(children.map(c=>c.id)),ls=[...window.WQ_FAMILY_DATA.lessons,...window.WQ_FAMILY_DATA.mixed],byId=new Map(ls.map(l=>[l.id,l]));
 const str=(v,max)=>{if(typeof v!=='string'||v.length>max||/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(v))throw Error('family text');return v;};
 const id=v=>{if(typeof v!=='string'||!/^[A-Za-z0-9_-]{1,100}$/.test(v)||['__proto__','constructor','prototype'].includes(v))throw Error('family ID');return v;};
 const dt=v=>{str(v,40);if(!Number.isFinite(Date.parse(v)))throw Error('family date');return v;};
 const entries=Object.entries(raw.children);if(entries.length>50)throw Error('family children');
 for(const [cid,data] of entries){
  if(!ids.has(cid))throw Error('family owner');
  if(!data||!data.seen||typeof data.seen!=='object'||Array.isArray(data.seen)||!Array.isArray(data.attempts)||data.attempts.length>3000)throw Error('family shape');
  const seen={};for(const [lid,t]of Object.entries(data.seen)){if(!byId.has(lid))throw Error('family term');seen[lid]=dt(t);}
  const used=new Set();const attempts=data.attempts.map(a=>{
   const l=byId.get(a.lessonId);if(!l||a.word!==l.word||!['build','fill','recall'].includes(a.stage)||typeof a.correct!=='boolean'||typeof a.hinted!=='boolean')throw Error('family attempt');
   if(a.stage!=='recall'&&a.hinted!==true)throw Error('family hint status');
   const aid=id(a.id);if(used.has(aid))throw Error('family duplicate');used.add(aid);
   return {id:aid,lessonId:l.id,word:l.word,stage:a.stage,correct:a.correct,hinted:a.hinted,answer:str(a.answer,60),time:dt(a.time),sessionId:id(a.sessionId),mixed:a.mixed===true};
  });
  let session=null;
  if(data.session){
   const s=data.session,l=byId.get(s.lessonId);
   if(!l||!['base','notice','build','fill','recall','done'].includes(s.stage))throw Error('family session');
   if(!Array.isArray(s.bank)||s.bank.length>5||!Array.isArray(s.picks)||s.picks.length>3)throw Error('family pieces');
   const bank=s.bank.map(b=>({id:id(b.id),text:str(b.text,20)}));if(new Set(bank.map(b=>b.id)).size!==bank.length)throw Error('family pieces duplicate');
   const picks=s.picks.map(id);if(new Set(picks).size!==picks.length||picks.some(p=>!bank.some(b=>b.id===p)))throw Error('family picks');
   let mixed=null;
   if(s.mixedIds!=null){if(!Array.isArray(s.mixedIds)||!s.mixedIds.length||s.mixedIds.length>5||s.mixedIds.some(x=>!byId.has(x))||new Set(s.mixedIds).size!==s.mixedIds.length)throw Error('family mixed');mixed=[...s.mixedIds];}
   const index=s.mixedIndex??0;if(!Number.isInteger(index)||index<0||index>(mixed?.length||0))throw Error('family index');
   if(mixed&&s.stage!=='done'&&(s.stage!=='recall'||mixed[index]!==s.lessonId))throw Error('family mixed target');
   if(!mixed){if(!l.parts)throw Error('family base');const required=l.parts.map((p,i)=>({id:String(i),text:p}));if(required.some(b=>!bank.some(x=>x.id===b.id&&x.text===b.text))||bank.some(b=>!required.some(x=>x.id===b.id&&x.text===b.text)&&!(b.id==='d'&&['b','t','sh','d'].includes(b.text))))throw Error('family bank content');}
   let feedback=null;if(s.feedback){if(typeof s.feedback.correct!=='boolean')throw Error('family feedback');feedback={correct:s.feedback.correct,awarded:s.feedback.awarded===true};}
   const ret=['learn','kid','spelling-family'].includes(s.returnRoute)?s.returnRoute:'spelling-family';
   session={id:id(s.id),lessonId:l.id,stage:s.stage,bank,picks,answer:str(s.answer||'',40),feedback,hinted:s.hinted===true,returnRoute:ret,mixedIds:mixed,mixedIndex:index,startedAt:dt(s.startedAt)};
  }
  out.children[cid]={seen,attempts,session};
 }
 return out;
}

/* WordQuest V17: reviewed spelling-family lessons. No automatic substring-to-morpheme inference.
   This module runs in the existing app closure, reusing auth, storage, images, audio and stars. */
const FG = window.WQ_FAMILY_DATA;
const fgById = new Map([...FG.lessons,...FG.mixed].map(x=>[x.id,x]));
let fgAudioToken=0, fgAudioCancel=null, fgAudioObject=null, fgSpeechObject=null;
let fgAudioStatus='', fgAudioError=false, fgAudioWord='', fgPlaying=false;
let fgRouteContext='';
const fgStages=['base','notice','build','fill','recall','done'];
function fgStore(){
 db.familyLearning=db.familyLearning||{version:1,children:{}};
 const cid=activeChild()?.id;
 if(!cid)return null;
 return db.familyLearning.children[cid]||(db.familyLearning.children[cid]={seen:{},attempts:[],session:null});
}
function fgSession(){return fgStore()?.session||null;}
function fgLesson(){return fgById.get(fgSession()?.lessonId)||null;}
function fgWrite(){return save();} // Existing save never persists guest data.
function fgFindLesson(word,meaning=''){
 const found=FG.lessons.filter(x=>norm(x.word)===norm(word));
 if(found.length<=1){const l=found[0];if(!l)return null;const allowed={air:/空氣/,hair:/頭髮|毛髮/,pair:/一雙|一對|兩個/,chair:/椅/,stairs:/樓梯/,repair:/修理|修補|維修/};return !meaning||allowed[l.id]?.test(meaning)?l:null;}
 if(/公平|公正/.test(meaning))return fgById.get('fair-equal');
 if(/展覽|展销|展銷|書展/.test(meaning))return fgById.get('fair-event');
 return null; // Never guess a meaning for fair.
}
function fgBtn(text,act,extra='',cls='secondary'){
 return `<button type="button" class="btn ${cls}" data-fg="${act}" ${extra}>${text}</button>`;
}
function fgWord(l,small=false){
 return `<span data-wq-exposure="${esc(l.word)}" class="fg-word ${small?'fg-word-small':''}" lang="en-GB">${l.parts.map((p,i)=>`<span class="fg-part ${p==='air'?'fg-shared':i===l.parts.length-1&&p==='s'?'fg-ending':'fg-added'}">${esc(p)}</span>`).join('')}</span>`;
}
function fgCue(l,compact=false){
 const img=l.image&&BUILTIN_IMAGES[l.image];
 const symbol=l.id==='stairs'?'<span class="fg-stair-icon" aria-hidden="true"><i></i><i></i><i></i><i></i></span>':`<span class="fg-symbol" aria-hidden="true">${esc(l.symbol||'Aa')}</span>`;
 return `<div class="fg-cue ${compact?'fg-cue-compact':''}">${img?`<img src="${img}" alt="" class="fg-cue-image">`:symbol}<strong>${esc(l.meaning)}</strong></div>`;
}
function fgLast(lid,stage='recall'){
 return fgStore()?.attempts.filter(a=>a.lessonId===lid&&a.stage===stage).at(-1)||null;
}
function fgStatus(lid){const a=fgLast(lid);return !a?'未試過自己拼字':a.hinted?'用了提示':a.correct?'最近自己拼對':'要再練';}
function fgStopAudio(){
 fgAudioToken++;if(fgAudioCancel){const cancel=fgAudioCancel;fgAudioCancel=null;cancel();}
 if(fgAudioObject){try{fgAudioObject.pause();fgAudioObject.removeAttribute('src');fgAudioObject.load();}catch(_){}fgAudioObject=null;}
 if(fgSpeechObject){try{speechSynthesis.cancel();}catch(_){}fgSpeechObject=null;}
 fgPlaying=false;voiceBusy=false;fgAudioWord='';
}
function fgResetAudio(){fgStopAudio();fgAudioStatus='';fgAudioError=false;}
function fgAudioUI(){
 const s=fgSession(),l=fgLesson();if(!s||!l)return;
 const allowCompare=['notice','build','fill'].includes(s.stage)&&l.word!=='air'&&!s.feedback;
 const text=s.stage==='base'?'air':l.word;
 const stored=!!usableAudio(text);
 return `<div class="fg-audio"><div class="fg-audio-buttons">${fgBtn('聽讀音','speak','','soft')}${allowCompare?fgBtn('聽一聽，比一比','compare','','secondary'):''}${fgPlaying?fgBtn('停止','stop-audio','','quiet'):''}</div><p class="fg-audio-status ${fgAudioError?'fg-error':''}" role="status">${esc(fgAudioStatus|| (stored?'使用已下載音檔':'備用：裝置英式聲音'))}</p></div>`;
}
function fgUpdateAudioUI(){
 const box=$('#fg-audio-box');if(box)box.innerHTML=fgAudioUI()||'';
 // Highlight only a word already shown in a teaching step. Never insert the answer into recall.
 $$('.fg-comparison-unit').forEach(el=>el.classList.toggle('fg-speaking',el.dataset.word===fgAudioWord));
}
async function fgPlay(compare=false){
 fgResetAudio();stopSpeech();stopSfx();
 const session=fgSession(),l=fgLesson(),ctx=accountId()+'|'+activeChild()?.id,sid=session?.id;
 if(!session||!l||!['family-lesson'].includes(lastRoute))return;
 const stage=session.stage,word=stage==='base'?'air':l.word;
 if(compare&&stage==='recall')return;
 const words=compare&&word!=='air'?['air',word]:[word];
 const token=fgAudioToken;
 const valid=()=>token===fgAudioToken&&ctx===accountId()+'|'+activeChild()?.id&&fgSession()?.id===sid&&fgSession()?.stage===stage&&lastRoute==='family-lesson';
 fgPlaying=true;voiceBusy=true;fgAudioStatus='準備讀音…';fgUpdateAudioUI();
 try{
  for(const word of words){
   if(!valid())return;
   fgAudioWord=word;fgAudioStatus='正在播放…';fgUpdateAudioUI();
   await fgPlayOne(word,valid);
  }
  if(valid()){fgAudioStatus='已播完。';fgAudioError=false;}
 }catch(e){if(valid()){fgAudioStatus='暫時播不到英式讀音。可重試，或先按中文意思練習。';fgAudioError=true;}}
 finally{if(valid()){fgPlaying=false;voiceBusy=false;fgAudioWord='';fgUpdateAudioUI();}}
}
function fgPlayOne(text,valid){
 return new Promise(async(resolve,reject)=>{
  let timer=null,ended=false,started=false,voiceWait=null;
  const done=error=>{if(ended)return;ended=true;clearTimeout(timer);clearTimeout(voiceWait);fgAudioCancel=null;if(error){try{fgAudioObject?.pause();if(fgSpeechObject)window.speechSynthesis?.cancel();}catch(_){}reject(error);}else resolve();};
  fgAudioCancel=()=>done(Error('cancelled'));
  timer=setTimeout(()=>done(Error('audio-timeout')),15000);
  try{
   // Match full recorded words; do not splice phonemes or arbitrary syllables.
   const clip=usableAudio(text);
   if(clip){
    const a=new Audio(mediaURL(clip));fgAudioObject=a;
    a.onplaying=()=>{if(valid())started=true;};
    a.onended=()=>done(valid()&&started?null:Error('not-completed'));
    a.onerror=()=>done(Error('audio-error'));
    await a.play();return;
   }
   if(!window.speechSynthesis||!window.SpeechSynthesisUtterance)throw Error('no-voice');
   const startVoice=()=>{
    if(ended||!valid())return done(Error('cancelled'));
    const voice=bestBritishVoice();if(!voice||!/^en[-_]GB$/i.test(voice.lang)||(!navigator.onLine&&voice.localService!==true))return done(Error('no-uk-voice'));
    const u=new SpeechSynthesisUtterance(text);fgSpeechObject=u;u.voice=voice;u.lang='en-GB';u.rate=.9;u.pitch=1;
    u.onstart=()=>{if(valid())started=true;};
    u.onend=()=>done(valid()&&started?null:Error('not-completed'));
    u.onerror=()=>done(Error('voice-error'));speechSynthesis.speak(u);
   };
   if(bestBritishVoice())startVoice();else voiceWait=setTimeout(startVoice,700);
  }catch(e){done(e);}
 });
}
function fgNewSession(lid,returnRoute='spelling-family',mixedIds=null){
 const l=fgById.get(lid);if(!l)return;
 fgResetAudio();stopSpeech();
 const parts=l.parts||[];let bank=parts.map((p,i)=>({id:String(i),text:p}));
 if(parts.length>1){const distractor=['b','t','sh','d'].find(x=>!parts.includes(x));bank.push({id:'d',text:distractor});}
 bank=shuffle(bank);
 fgStore().session={id:uid('fg'),lessonId:lid,stage:mixedIds?'recall':'base',bank,picks:[],answer:'',feedback:null,hinted:false,returnRoute:['kid','learn','spelling-family'].includes(returnRoute)?returnRoute:'spelling-family',mixedIds:mixedIds||null,mixedIndex:0,startedAt:new Date().toISOString()};
 fgWrite();go('family-lesson');render();
}
function fgStart(lid,ret='spelling-family'){
 if(!fgById.has(lid))return;
 const s=fgSession();
 
 fgNewSession(lid,ret);
}
function fgMixed(){
 const seen=fgStore()?.seen||{};
 const learned=FG.lessons.filter(l=>seen[l.id]&&l.word!=='air');
 if(!learned.length){toast('先學一個新字，再混合重溫。');return;}
 // Avoid testing both meanings of fair in the same mixed round.
 const unique=[...new Map(learned.map(l=>[l.word,l])).values()].slice(-3);
 const ids=shuffle([...unique.map(l=>l.id),...FG.mixed.map(l=>l.id)]);
 fgNewSession(ids[0],'spelling-family',ids);
}
function fgOverview(){
 const s=fgSession();
 const root=fgById.get('air');
 return `<section class="fg-overview"><div class="row between"><div><p class="eyebrow">由短字，帶出新字</p><h1>拼字家族</h1></div>${link('返回','kid','quiet')}</div><section class="fg-hero"><div><p class="fg-caption">先記一小塊</p>${fgWord(root)}<p>空氣</p>${fgBtn('先學 air','start','data-lesson="air"','primary')}</div><div><p class="fg-caption">再換開頭</p><div class="fg-hero-examples">${fgWord(fgById.get('hair'),true)}${fgWord(fgById.get('chair'),true)}</div><p>這裏也有 <strong lang="en">air</strong>。</p></div></section>${s&&s.stage!=='done'?`<div class="fg-resume">${fgBtn('繼續剛才的練習','resume','','primary')}<span class="small muted">保留目前步驟及已輸入答案</span></div>`:''}<div class="fg-family-grid">${FG.lessons.filter(l=>l.id!=='air').map(l=>`<button class="fg-family-card" type="button" data-fg="start" data-lesson="${l.id}"><span class="fg-card-symbol" aria-hidden="true">${esc(l.symbol||'Aa')}</span>${fgWord(l,true)}<strong>${esc(l.meaning)}</strong><span class="small muted">${esc(l.level)}</span><span class="fg-status">${esc(fgStatus(l.id))}</span></button>`).join('')}</div><div class="fg-bottom-actions">${fgBtn('混合再試','mixed')}<span class="small muted">混入 book、shoe，不只猜 air。</span></div><details class="fg-adult-note"><summary>家長看這裏</summary><p>這裏比較的是拼法和讀音，不是字的來源。chair 不是「空氣」的意思。repair 也不是「再＋一對」。rep | air 也不是音節的分法。</p><p>fair 有「公平的」和「展覽會」兩個意思，會分開學。孩子每次只選一個字，不會把整組加入學校默書。首批有 7 個英文字、8 個意思。</p><p>新練習的紀錄，和正式默書成績分開。</p></details></section>`;
}
function fgLessonView(){
 const s=fgSession(),l=fgLesson();if(!s||!l)return fgOverview();
 if(s.stage==='done')return fgFinish();
 const root=fgById.get('air'),recall=s.stage==='recall';
 const stageList=l.id==='air'?['base','build','recall']:['base','notice','build','fill','recall'];
 const pos=s.mixedIds?s.mixedIndex+1:stageList.indexOf(s.stage)+1,total=s.mixedIds?s.mixedIds.length:stageList.length;
 let content='';
 if(s.stage==='base')content=`<h1 class="fg-title">先記住這個字</h1><div class="fg-root-card">${fgWord(root)}<p>空氣</p><div class="fg-letter-sequence" aria-label="a i r">a <span>→</span> i <span>→</span> r</div></div><p class="fg-short-tip">先記 a、i、r 的次序。</p>`;
 if(s.stage==='notice')content=`<h1 class="fg-title">這裏也有 air</h1>${fgCue(l)}<div class="fg-comparison"><div class="fg-comparison-unit" data-word="air">${fgWord(root,true)}</div><span aria-hidden="true">→</span><div class="fg-comparison-unit" data-word="${l.word}">${fgWord(l)}</div></div><p class="fg-short-tip">${esc(l.hint)}</p>`;
 if(s.stage==='build'){
  const n=l.parts.length,picked=s.picks.map(i=>s.bank.find(b=>b.id===i)?.text||'');
  content=`<h1 class="fg-title">按字母組合，接起來</h1>${fgCue(l,true)}<div class="fg-build-slots" aria-label="已選字母組合">${Array.from({length:n},(_,i)=>`<span class="fg-slot ${picked[i]==='air'?'fg-shared':''}">${esc(picked[i]||'？')}</span>`).join('')}</div><div class="fg-bank" ${s.feedback?'hidden':''}>${s.bank.map(b=>`<button class="fg-token ${b.text==='air'?'fg-shared':''}" data-fg="pick" data-piece="${b.id}" ${s.picks.includes(b.id)||s.feedback||s.picks.length>=n?'disabled':''} lang="en-GB">${esc(b.text)}</button>`).join('')}</div><div class="fg-build-controls" ${s.feedback?'hidden':''}>${fgBtn('退一格','undo',!s.picks.length||s.feedback?'disabled':'','quiet')}${fgBtn('重新接','clear',!s.picks.length||s.feedback?'disabled':'','quiet')}</div>`;
 }
 if(s.stage==='fill'){
  content=`<h1 class="fg-title">補回熟悉的部分</h1>${fgCue(l,true)}<label class="fg-fill-row" for="fg-answer">${l.parts.map(p=>p==='air'?`<input id="fg-answer" class="fg-fill-input" maxlength="20" inputmode="text" autocomplete="off" autocapitalize="none" autocorrect="off" spellcheck="false" enterkeyhint="done" aria-label="填入缺少的字母" value="${esc(s.answer)}" ${s.feedback?'disabled':''}>`:`<span lang="en-GB" class="${p==='s'?'fg-ending':''}">${esc(p)}</span>`).join('')}</label><p class="small muted fg-fill-caption">有部分字母提示。</p>`;
 }
 if(recall){
  content=`<h1 class="fg-title">自己拼出來</h1>${fgCue(l,true)}<label class="fg-answer-label" for="fg-answer">輸入英文</label><input id="fg-answer" class="input fg-answer" maxlength="40" autocomplete="off" autocapitalize="none" autocorrect="off" spellcheck="false" enterkeyhint="done" value="${esc(s.answer)}" ${s.feedback?'disabled':''}><div class="fg-hint-area" ${s.feedback?'hidden':''}>${s.hinted?`<div class="fg-revealed-hint" role="status">${l.parts?fgWord(l,true):esc(l.word)}<span class="small">用了提示，這題不計入「自己拼對」。</span></div>`:fgBtn('看提示','hint',s.feedback?'disabled':'','quiet')}</div>`;
 }
 let feedback='';
 if(s.feedback){const f=s.feedback;feedback=`<div class="fg-feedback ${f.correct?'fg-ok':'fg-review'}" role="status"><strong>${f.correct?(s.hinted?'有提示下拼對了。':'答對了。'):'再看一次。'}</strong>${!f.correct?`<span lang="en-GB">${esc(s.stage==='fill'?'air':l.word)}</span>`:''}${f.awarded?'<span>+1 金幣</span>':''}${!f.correct?'<span class="small">訂正後再往下一步。</span>':''}</div>`;}
 const actionable=['build','fill','recall'].includes(s.stage);
 return `<section class="fg-shell" data-stage="${s.stage}" data-feedback="${!!s.feedback}"><div class="fg-top"><span>${recall?'拼字練習':'學一個，帶一個'}</span><span>${pos} / ${total}</span>${fgBtn('休息','pause','','quiet')}</div><div class="fg-workspace"><div class="fg-main-card">${content}<div id="fg-audio-box">${fgAudioUI()}</div>${feedback}</div></div><div class="fg-actions">${actionable&&!s.feedback?fgBtn('交答案','submit','id="fg-submit" disabled','primary'):fgBtn(s.feedback&&!s.feedback.correct?'我看清楚了':'下一步','next','id="fg-next"','primary')}</div></section>`;
}
function fgSyncSubmit(){const b=$('#fg-submit'),s=fgSession(),l=fgLesson();if(!b||!s||!l)return;b.disabled=!!s.feedback||(s.stage==='build'?s.picks.length!==l.parts.length:!s.answer.trim());}
function fgCommitAnswer(){
 const s=fgSession(),l=fgLesson();if(!s||!l||s.feedback||!['build','fill','recall'].includes(s.stage))return;
 const built=s.picks.map(id=>s.bank.find(b=>b.id===id)?.text||'').join('');
 const answer=s.stage==='build'?built:s.answer.trim();if(!answer||(s.stage==='build'&&s.picks.length!==l.parts.length))return;
 const correct=norm(answer)===(s.stage==='fill'?'air':norm(l.word));
 const independent=s.stage==='recall'&&!s.hinted;
 const a={id:uid('fa'),lessonId:l.id,word:l.word,stage:s.stage,correct,hinted:!independent,answer,time:new Date().toISOString(),sessionId:s.id,mixed:!!s.mixedIds};
 let awarded=false;
 if(isLoggedIn()){
  const store=fgStore();store.attempts.push(a);if(store.attempts.length>3000)store.attempts.splice(0,store.attempts.length-3000);
  if(correct&&independent){const ledger=dailyLedger(),key='family|'+norm(l.word)+'|recall';if(!ledger.rewardKeys.includes(key)){ledger.rewardKeys.push(key);awarded=false;}}
 }
 s.feedback={correct,awarded};fgResetAudio();fgWrite();playSfx(correct?'correct':'wrong');render();
}
function fgNext(){
 const s=fgSession(),l=fgLesson();if(!s||!l||s.stage==='done')return;
 if(['build','fill','recall'].includes(s.stage)&&!s.feedback)return;
 fgResetAudio();const seen=fgStore().seen;
 if(['base','notice'].includes(s.stage))seen[s.stage==='base'?'air':l.id]=new Date().toISOString();
 if(s.mixedIds){
  if(++s.mixedIndex<s.mixedIds.length){s.lessonId=s.mixedIds[s.mixedIndex];s.stage='recall';}
  else s.stage='done';
 }else{
  const stages=l.id==='air'?['base','build','recall','done']:fgStages;
  s.stage=stages[stages.indexOf(s.stage)+1]||'done';
 }
 s.answer='';s.picks=[];s.feedback=null;s.hinted=false;if(s.stage==='done'&&isLoggedIn())a28RewardFamily();fgWrite();render();
}
function fgFinish(){
 const s=fgSession(),l=fgLesson();if(!s||!l)return fgOverview();
 const records=isLoggedIn()?fgStore().attempts.filter(x=>x.sessionId===s.id):[];
 const independent=records.filter(x=>x.stage==='recall'&&!x.hinted),correct=independent.filter(x=>x.correct).length;
 return `<section class="fg-finish card pad"><div class="fg-finish-mark" aria-hidden="true">✓</div><h1>這一輪完成了</h1>${isLoggedIn()?q36FamilyBlock(s):'<p>訪客不會儲存紀錄或金幣。</p>'}<p class="small muted">剛學過的字，改天再試一次。</p><div class="stack">${fgBtn(s.returnRoute==='learn'?'返回原來練習':'返回拼字家族','return','','primary')}${fgBtn('混合再試','mixed')}</div></section>`;
}
function fgReport(){
 const data=fgStore(),a=data.attempts,rows=a.slice(-16).reverse();
 return `<section class="fg-report card pad"><div class="row between"><h2>拼字家族紀錄</h2>${link('開啟拼字家族','spelling-family','secondary')}</div><p class="small muted"></p>${rows.length?`<ul class="list">${rows.map(x=>`<li><div><strong lang="en-GB">${esc(x.word)}</strong><div class="small muted">${x.stage==='build'?'接字母組合（有提示）':x.stage==='fill'?'補字（有提示）':x.hinted?'拼字（用了提示）':'拼字（無字母提示）'}${x.mixed?' · 混合重溫':''}</div></div><span>${x.correct?'答對':'再練'}</span></li>`).join('')}</ul>`:'<p>未有已儲存的家族練習紀錄。</p>'}<p class="small muted"></p></section>`;
}
function fgAfterRender(){
 const ctx=accountId()+'|'+activeChild()?.id+'|'+lastRoute;
 if(ctx!==fgRouteContext){fgResetAudio();fgRouteContext=ctx;}
 document.body.classList.toggle('family-active',lastRoute==='family-lesson'&&fgSession()?.stage!=='done');
 document.body.classList.toggle('quiz-active',lastRoute==='learn'||(lastRoute==='family-lesson'&&fgSession()?.stage!=='done'));
 if(lastRoute==='spelling-family')$('#app').innerHTML=fgOverview();
 if(lastRoute==='family-lesson'){$('#app').innerHTML=fgLessonView();fgSyncSubmit();}
 if(lastRoute==='kid'){
  const s=fgSession();const box=document.createElement('section');box.className='fg-entry-card';box.innerHTML=`<div><span class="eyebrow">拼字家族</span><h2><span lang="en">air</span> → <span lang="en">chair</span></h2><p>學一小塊，再帶出新字。</p></div><div class="stack">${link('試試拼字家族','spelling-family','primary')}${s&&s.stage!=='done'?fgBtn('繼續家族練習','resume'):''}</div>`;$('#app').append(box);
 }
 if(lastRoute==='practice'){
  const a=document.createElement('a');a.href='#spelling-family';a.className='practice-card';a.innerHTML='<span class="bigicon" lang="en">air</span><strong>拼字家族</strong>';$('#app .practice-grid')?.append(a);
 }
 if(lastRoute==='parent'||lastRoute==='report')$('#app').insertAdjacentHTML('beforeend',fgReport());
 if(lastRoute==='learn'&&currentItem()?.type==='study'){
  const l=fgFindLesson(currentWord()?.en,currentWord()?.zh);
  if(l){const host=document.createElement('div');host.className='fg-study-bridge';host.innerHTML=fgBtn('用 air 記一記','from-study',`data-lesson="${l.id}"`,'secondary');$('.task-actions')?.prepend(host);}
 }
 updateViewport();
}
// Keep the existing renderer and all routes; add the new routes without a second app.
const fgOriginalRender=render;
render=function(){fgOriginalRender();fgAfterRender();};
const fgOriginalDeleteChild=deleteChild;
deleteChild=function(id){fgOriginalDeleteChild(id);if(!db.children.some(c=>c.id===id)&&db.familyLearning?.children){delete db.familyLearning.children[id];fgWrite();}};
const fgOriginalLogout=logout;
logout=function(){fgResetAudio();return fgOriginalLogout();};
const fgOriginalSetChild=setChild;
setChild=function(id){fgResetAudio();return fgOriginalSetChild(id);};
// One handler for this feature; no change to the original input handler or game controls.
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-fg]');if(!b||b.disabled)return;
 const action=b.dataset.fg,s=fgSession(),l=fgLesson();
 if(action==='start')return fgStart(b.dataset.lesson);
 if(action==='from-study')return fgStart(b.dataset.lesson,'learn');
 if(action==='resume'){if(s){fgResetAudio();go('family-lesson');render();}return;}
 if(action==='mixed')return fgMixed();
 if(action==='pause'){fgResetAudio();fgWrite();go(s?.returnRoute==='learn'?'learn':'spelling-family');return;}
 if(action==='return'){fgResetAudio();go(s?.returnRoute==='learn'?'learn':'spelling-family');return;}
 if(action==='speak')return void fgPlay(false);
 if(action==='compare')return void fgPlay(true);
 if(action==='stop-audio'){fgResetAudio();fgUpdateAudioUI();return;}
 if(!s||!l)return;
 if(action==='pick'&&s.stage==='build'&&!s.feedback&&s.picks.length<l.parts.length&&s.bank.some(x=>x.id===b.dataset.piece)&&!s.picks.includes(b.dataset.piece)){s.picks.push(b.dataset.piece);fgWrite();render();}
 if(action==='undo'&&s.stage==='build'&&!s.feedback){s.picks.pop();fgWrite();render();}
 if(action==='clear'&&!s.feedback){s.picks=[];s.answer='';fgWrite();render();}
 if(action==='hint'&&s.stage==='recall'&&!s.feedback){s.hinted=true;fgWrite();render();}
 if(action==='submit')fgCommitAnswer();
 if(action==='next')fgNext();
});
document.addEventListener('input',e=>{if(e.target.id==='fg-answer'){const s=fgSession();if(!s||s.feedback)return;s.answer=e.target.value;fgWrite();fgSyncSubmit();}});
document.addEventListener('keydown',e=>{if(e.target.id==='fg-answer'&&e.key==='Enter'&&!e.isComposing&&!e.repeat){e.preventDefault();fgCommitAnswer();}});
window.addEventListener('pagehide',fgResetAudio);
document.addEventListener('visibilitychange',()=>{if(document.hidden){fgResetAudio();fgUpdateAudioUI();}});
window.addEventListener('offline',()=>{fgResetAudio();fgAudioStatus='沒有網絡。會用已存的音檔，或裝置的英式聲音。';fgUpdateAudioUI();});

// Called during initial load, before module constants exist. Catalogue is preloaded.
function validatePhonicsLearning(raw,children){
 const out={version:1,children:{}};if(raw==null)return out;
 const fail=()=>{throw Error('這個拼字課程備份檔有問題，請換另一份備份。');};
 const obj=x=>!!x&&typeof x==='object'&&!Array.isArray(x);
 const txt=(x,n)=>{if(typeof x!=='string'||x.length>n||/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(x))fail();return x;};
 const safeid=x=>{if(typeof x!=='string'||!/^[A-Za-z0-9_-]{1,100}$/.test(x)||['__proto__','prototype','constructor'].includes(x))fail();return x;};
 const integer=(x,lo,hi)=>{if(!Number.isInteger(x)||x<lo||x>hi)fail();return x;};
 const date=x=>{txt(x,40);if(!Number.isFinite(Date.parse(x)))fail();return x;};
 const array=(x,n)=>{if(!Array.isArray(x)||x.length>n)fail();return x;};
 const ls=new Map(window.WQ_PHONICS_DATA.lessons.map(l=>[l.id,l])),ids=new Set(children.map(c=>c.id));
 const indices=x=>{const a=array(x,4).map(v=>integer(v,0,3));if(new Set(a).size!==a.length)fail();return a;};
 const types=['listenChoice','missing','spell','listenSpell','meaningChoice'];
 function answer(a,i,l){if(!obj(a)||a.question!==i||a.type!==types[i]||typeof a.technical!=='boolean'||typeof a.audioCompleted!=='boolean')fail();const wi=integer(a.wordIndex,0,3),w=l.words[wi],text=txt(a.answer,60),expected=i===1?w.focusIndices.map(n=>w.word[n]).join(''):w.word,needs=[0,3].includes(i);if(a.technical){if(!needs||a.correct!==null||text!==''||a.audioCompleted)fail();}else{if(typeof a.correct!=='boolean'||!text.trim()||needs&&!a.audioCompleted||a.correct!==(text.trim().toLowerCase()===expected.toLowerCase()))fail();}return {question:i,wordIndex:wi,type:types[i],answer:text,correct:a.correct,audioCompleted:a.audioCompleted,technical:a.technical,time:date(a.time)};}
 function results(a,l){a=array(a,5).map((r,i)=>answer(r,i,l));if(a.length===5&&(new Set(a.slice(0,4).map(x=>x.wordIndex)).size!==4||a[4].wordIndex!==a[0].wordIndex))fail();return a;}
 if(raw.version!==1||!obj(raw.children)||Object.keys(raw.children).length>50)fail();
 for(const [cid,v] of Object.entries(raw.children)){
  if(!ids.has(cid)||!obj(v)||!obj(v.progress))fail();const progress={};
  for(const [lid,p] of Object.entries(v.progress)){if(!ls.has(lid)||!obj(p))fail();let latest=null;if(p.latestResult!=null){const r=p.latestResult;const pending=integer(r.pending,0,2),score=integer(r.score,0,5-pending);latest={score,pending,time:date(r.time)};}
   progress[lid]={seen:indices(p.seen),heard:indices(p.heard),read:indices(p.read),bestScore:integer(p.bestScore,0,5),starsAwarded:integer(p.starsAwarded,0,3),completedTests:integer(p.completedTests,0,1000000),latestResult:latest};
  }
  const unique=new Set();const runs=array(v.runs,200).map(r=>{if(!obj(r)||!ls.has(r.lessonId)||r.total!==5)fail();const id=safeid(r.id);if(unique.has(id))fail();unique.add(id);const a=results(r.answers,ls.get(r.lessonId));if(a.length!==5)fail();const pending=a.filter(x=>x.technical).length,score=a.filter(x=>x.correct===true).length;if(r.pending!==pending||r.score!==score)fail();const award=integer(r.award,0,3);if(pending&&award)fail();return {id,lessonId:r.lessonId,time:date(r.time),score,pending,total:5,award,answers:a};});
  let session=null;
  if(v.session!=null){const s=v.session,l=ls.get(s.lessonId);if(!obj(s)||!l||!['learn','quiz','result'].includes(s.mode))fail();const id=safeid(s.id),idx=integer(s.index,0,s.mode==='learn'?3:4),draft=txt(s.draft,60);let queue=[];
   if(s.mode!=='learn'){queue=array(s.queue,5).map((q,i)=>{if(!obj(q)||q.type!==types[i])fail();const wi=integer(q.wordIndex,0,3),base={type:types[i],wordIndex:wi};if([0,4].includes(i)){const opts=array(q.options,4);if(opts.length!==4||new Set(opts).size!==4||opts.some(x=>!l.words.some(w=>w.word===x)))fail();base.options=[...opts];}return base;});if(queue.length!==5||new Set(queue.slice(0,4).map(q=>q.wordIndex)).size!==4||queue[4].wordIndex!==queue[0].wordIndex)fail();}
   const answers=results(s.answers,l);if(s.mode==='learn'&&(answers.length||array(s.queue,0).length))fail();if(s.mode==='quiz'&&(answers.length<idx||answers.length>idx+1))fail();if(s.mode==='result'&&(answers.length!==5||idx!==4||!runs.some(r=>r.id===id&&r.lessonId===l.id)))fail();if(answers.some((a,i)=>a.wordIndex!==queue[i]?.wordIndex))fail();
   session={id,lessonId:l.id,mode:s.mode,index:idx,draft,queue,answers,audioOk:false,startedAt:date(s.startedAt)};
  }
  out.children[cid]={progress,runs,session};
 }
 return out;
}

/* WordQuest V19. Runs INSIDE the existing app closure. Auth, wallet, UK audio,
   private offline assets and original dictation remain shared. No speech recognition. */
const PC=window.WQ_PHONICS_DATA, pcLessons=new Map(PC.lessons.map(l=>[l.id,l]));
let pcEpoch=0,pcCancel=null,pcAudioObj=null,pcUtterance=null,pcAudio={status:'idle',text:''},pcContext='',pcCommitMessage='';
function pcStore(){db.phonicsLearning=db.phonicsLearning||{version:1,children:{}};const id=activeChild()?.id;if(!id)return null;return db.phonicsLearning.children[id]||(db.phonicsLearning.children[id]={progress:{},runs:[],session:null});}
function pcProgress(id){const d=pcStore();return d.progress[id]||(d.progress[id]={seen:[],heard:[],read:[],bestScore:0,starsAwarded:0,completedTests:0,latestResult:null});}
function pcSession(){return pcStore()?.session||null;}
function pcLesson(){return pcLessons.get(pcSession()?.lessonId)||null;}
function pcBtn(text,act,extra='',cls='secondary'){return `<button type="button" class="btn ${cls}" data-pc="${act}" ${extra}>${text}</button>`;}
function pcIntendedStars(score){return score===5?3:score>=3?2:1;}
function pcStop(){pcEpoch++;if(pcCancel){const c=pcCancel;pcCancel=null;c();}if(pcAudioObj){try{pcAudioObj.pause();pcAudioObj.removeAttribute('src');pcAudioObj.load();}catch(_){}pcAudioObj=null;}if(pcUtterance){try{window.speechSynthesis?.cancel();}catch(_){}pcUtterance=null;}voiceBusy=false;pcAudio={status:'idle',text:''};}
function pcReadyToTest(id){return adminUnlocks()||(pcStore()?.progress[id]?.seen?.length||0)===4;}
function pcSessionStart(id,mode){const l=pcLessons.get(id);if(!l)return;if(mode==='quiz'&&!pcReadyToTest(id)){toast('先學完這課的四個字，再做小測。');return;}
 
 pcStop();fgResetAudio();stopSpeech();pcCommitMessage='';const order=shuffle([0,1,2,3]);
 const queue=mode==='quiz'?[
 {type:'listenChoice',wordIndex:order[0],options:shuffle(l.words.map(w=>w.word))},
 {type:'missing',wordIndex:order[1]},
 {type:'spell',wordIndex:order[2]},
 {type:'listenSpell',wordIndex:order[3]},
 {type:'meaningChoice',wordIndex:order[0],options:shuffle(l.words.map(w=>w.word))}]:[];
 pcStore().session={id:uid('pc'),lessonId:id,mode,index:0,draft:'',queue,answers:[],audioOk:false,startedAt:new Date().toISOString()};save();go('phonics-lesson');render();}
function pcWord(w,masked=false){return `<span class="pc-word" ${masked?'':`data-wq-exposure="${esc(w.word)}"`} lang="en-GB" ${masked?'aria-label="補回缺少的字母"':''}>${[...w.word].map((ch,i)=>`<span class="${w.focusIndices.includes(i)?'pc-focus':''}">${masked&&w.focusIndices.includes(i)?'□':esc(ch)}</span>`).join('')}</span>`;}
function pcCue(w,decor=true){return `<div class="pc-cue">${decor?(w.image&&BUILTIN_IMAGES[w.image]?`<img class="pc-picture" src="${BUILTIN_IMAGES[w.image]}" alt="">`:`<span class="pc-symbol" aria-hidden="true">${esc(w.symbol||'')}</span>`):''}<strong>${esc(w.meaning)}</strong></div>`;}
function pcAudioUI(){const s=pcSession();if(!s)return '';const learn=s.mode==='learn',status=pcAudio.status;
 return `<div class="pc-audio-buttons">${pcBtn(status==='done'?'再聽一次':'聽讀音','play','','soft')}${learn?pcBtn('慢一點','slow','','secondary')+(s.index>0?pcBtn('比較讀音','compare','','quiet'):''):''}${['playing','loading'].includes(status)?pcBtn('停止','stop','','quiet'):''}</div><p class="pc-audio-status ${status==='error'?'pc-error':''}" role="status">${esc(pcAudio.text||'')}</p>${status==='error'&&s.mode==='quiz'?pcBtn('這題稍後補聽','skip','','quiet'):''}`;}
function pcAudioUpdate(){const box=$('#pc-audio-box');if(box)box.innerHTML=pcAudioUI();pcSync();}
function pcAudioOne(text,slow,valid){return new Promise((resolve,reject)=>{let settled=false,started=false,wait=null;const timer=setTimeout(()=>done(Error('timeout')),18000);
 function done(err){if(settled)return;settled=true;clearTimeout(timer);clearTimeout(wait);pcCancel=null;if(err){try{pcAudioObj?.pause();if(pcUtterance)window.speechSynthesis?.cancel();}catch(_){}reject(err);}else resolve();}
 pcCancel=()=>done(Error('cancelled'));
 try{const clip=usableAudio(text);if(clip){const a=new Audio(mediaURL(clip));pcAudioObj=a;a.playbackRate=slow?.8:1;a.preservesPitch=true;a.onplaying=()=>{if(valid())started=true;};a.onended=()=>done(valid()&&started?null:Error('unfinished'));a.onerror=()=>done(Error('failed'));a.play().catch(done);return;}
 const start=()=>{if(!valid())return done(Error('cancelled'));const v=bestBritishVoice();if(!window.SpeechSynthesisUtterance||!v||!/^en[-_]GB$/i.test(v.lang)||(!navigator.onLine&&v.localService!==true))return done(Error('no-uk-voice'));
 const u=new SpeechSynthesisUtterance(text);pcUtterance=u;u.voice=v;u.lang='en-GB';u.rate=slow?.72:.9;u.pitch=1;u.onstart=()=>{if(valid())started=true;};u.onend=()=>done(valid()&&started?null:Error('unfinished'));u.onerror=()=>done(Error('failed'));speechSynthesis.speak(u);};if(bestBritishVoice())start();else wait=setTimeout(start,700);
 }catch(e){done(e);}});}
async function pcPlay(kind='play'){
 const s=pcSession(),l=pcLesson();if(!s||!l||s.mode==='result'||lastRoute!=='phonics-lesson')return;
 if(s.mode==='quiz'&&s.answers.length>s.index)return;
 if(kind==='compare'&&s.mode!=='learn')return;
 pcStop();fgResetAudio();stopSpeech();stopSfx();s.audioOk=false;
 const token=pcEpoch,ctx=accountId()+'|'+activeChild()?.id,mode=s.mode,index=s.index,id=s.id;
 const valid=()=>pcEpoch===token&&ctx===accountId()+'|'+activeChild()?.id&&lastRoute==='phonics-lesson'&&pcSession()?.id===id&&pcSession()?.index===index&&pcSession()?.mode===mode;
 const w=l.words[mode==='learn'?index:s.queue[index].wordIndex];const texts=kind==='compare'&&index>0?[l.words[0].word,w.word]:[w.word];
 pcAudio={status:'loading',text:'正在準備讀音…'};voiceBusy=true;pcAudioUpdate();
 try{for(const text of texts){if(!valid())return;pcAudio={status:'playing',text:mode==='learn'?'正在播放整個字…':'正在播放…'};pcAudioUpdate();await pcAudioOne(text,kind==='slow',valid);}
 if(valid()){s.audioOk=true;pcAudio={status:'done',text:mode==='learn'?'聽完了，到你跟讀。':'聽完了，可以作答。'};if(mode==='learn'){const p=pcProgress(l.id);if(!p.heard.includes(index))p.heard.push(index);save();}}}
 catch(_){if(valid()){s.audioOk=false;pcAudio={status:'error',text:'暫時播不到英式讀音。重試，或稍後補聽。'};}}
 finally{if(valid()){voiceBusy=false;pcAudioUpdate();}}
}
function pcOverview(){const d=pcStore(),completed=PC.lessons.filter(l=>d.progress[l.id]?.completedTests>0).length,earned=Object.values(d.progress).reduce((n,p)=>n+p.starsAwarded,0),s=d.session;
 return `<section class="pc-overview"><div class="row between"><div><p class="eyebrow">聽一聽 · 跟着讀 · 自己拼</p><h1>拼字專家</h1></div>${link('返回','kid','quiet')}</div><section class="pc-hero"><div><p class="pc-kicker">發音教學 · 12 課</p><h2>學四個字，再試五題。</h2><p>每課一個拼字重點，按次序慢慢學。</p><div class="pc-path" aria-label="學習流程"><span>1 聽讀音</span><span>2 跟着讀</span><span>3 做小測</span></div></div><div class="pc-course-total"><strong>${completed}<small> / ${PC.lessons.length}</small></strong><span>已完成小測</span><span>${isLoggedIn()?`舊版課程已得 ${earned} 枚金幣`:'訪客可以學，但不會儲存紀錄和金幣'}</span></div></section>${s&&s.mode!=='result'?`<div class="pc-resume">${pcBtn('繼續剛才的一課','resume','','primary')}<span class="small muted">第 ${pcLessons.get(s.lessonId).number} 課 · ${s.mode==='quiz'?'小測':'學習'}</span></div>`:''}<div class="pc-course-grid">${PC.lessons.map(l=>{const p=d.progress[l.id],ready=pcReadyToTest(l.id);return `<article class="pc-course"><div class="pc-course-head"><span class="pc-number">${String(l.number).padStart(2,'0')}</span><strong class="pc-pattern" lang="en">${esc(l.pattern)}</strong><span class="pc-earned" aria-label="課程完成狀態">${p?.completedTests?'✓ 已完成':'待練習'}</span></div><h2>${esc(l.title)}</h2><p class="pc-word-list" lang="en">${l.words.map(w=>`<span data-wq-exposure="${esc(w.word)}">${esc(w.word)}</span>`).join(' · ')}</p><p class="small muted">${p?.completedTests?`最高 ${p.bestScore} / 5`:`已學 ${p?.seen.length||0} / 4`}${p?.latestResult?.pending?' · 有題目待補聽':''}</p><div class="pc-course-actions">${pcBtn((p?.seen?.length||0)===4?'再學一次':'開始學','learn',`data-lesson="${l.id}"`,'secondary')}${pcBtn(p?.completedTests?'再做小測':'課後小測','quiz',`data-lesson="${l.id}" ${ready?'':'disabled'}`,'primary')}</div></article>`;}).join('')}</div><div class="pc-bottom"><p>小測沒有拼法提示。每日金幣最多五枚，小測和其他學習一起計。同一課一天只得一次金幣。</p>${link('自由選字：air 家族','spelling-family','secondary')}</div></section>`;}
function pcLearningBody(s,l){const w=l.words[s.index],p=pcProgress(l.id);
 return `<h1 class="pc-title">聽一聽，再跟讀</h1><div class="pc-lesson-art">${pcCue(w)}${pcWord(w)}<p class="pc-tip">${esc(l.tip)}</p></div><div class="pc-controls"><div id="pc-audio-box">${pcAudioUI()}</div><p class="pc-follow-note"></p>${pcBtn('家長教學小貼士','note','','quiet')}</div>`;}
function pcQuizBody(s,l){const q=s.queue[s.index],w=l.words[q.wordIndex],r=s.answers[s.index],audio=['listenChoice','listenSpell'].includes(q.type);let cue='';
 if(audio)cue=`<div class="pc-ear" aria-hidden="true">♫</div><div id="pc-audio-box">${pcAudioUI()}</div>`;
 else cue=pcCue(w,q.type!=='missing');
 const titles={listenChoice:'聽一聽，選出英文',meaningChoice:'選出這個字',missing:'補回缺少的字母',spell:'自己拼出來',listenSpell:'聽一聽，拼出來'};
 let answer='';
 if(['listenChoice','meaningChoice'].includes(q.type))answer=`<div class="pc-options" role="group" aria-label="選擇英文答案">${q.options.map(v=>`<button class="pc-option ${s.draft===v?'pc-selected':''}" type="button" data-pc="select" data-value="${esc(v)}" aria-pressed="${s.draft===v}" ${r?'disabled':''} lang="en">${esc(v)}</button>`).join('')}</div>`;
 else answer=`${q.type==='missing'?`<div class="pc-mask">${pcWord(w,true)}</div>`:''}<label for="pc-answer" class="pc-label">${q.type==='missing'?'只填方格內的字母，按原來次序':'輸入完整英文'}</label><input class="input pc-answer" id="pc-answer" maxlength="60" autocomplete="off" autocapitalize="none" autocorrect="off" spellcheck="false" enterkeyhint="done" value="${esc(s.draft)}" ${r?'disabled':''}>`;
 return `<h1 class="pc-title">${titles[q.type]}</h1><div class="pc-quiz-cue">${cue}</div><div class="pc-answer-area">${answer}</div>${r?`<div class="pc-feedback ${r.technical?'pc-pending':r.correct?'pc-ok':'pc-retry'}" role="status"><strong>${r.technical?'這題待補聽，不計錯。':r.correct?'答對了。':'看看正確拼法。'}</strong>${!r.technical&&!r.correct?`<span lang="en">${esc(w.word)}</span>`:''}</div>`:''}`;
}
function pcLessonView(){const s=pcSession(),l=pcLesson();if(!s||!l)return pcOverview();if(s.mode==='result')return pcResult();const learn=s.mode==='learn',r=s.answers[s.index];
 return `<section class="pc-shell" data-mode="${s.mode}" data-question="${learn?'learn':s.queue[s.index].type}" data-feedback="${!!r}"><div class="pc-top"><strong>${learn?'第 '+l.number+' 課':'課後小測'}</strong><div class="pc-progress" role="progressbar" aria-label="${learn?'學習':'小測'}進度" aria-valuenow="${s.index+1}" aria-valuemin="0" aria-valuemax="${learn?4:5}"><i style="width:${(s.index+1)/(learn?4:5)*100}%"></i></div><span>${s.index+1} / ${learn?4:5}</span>${pcBtn('休息','pause','','quiet')}</div><div class="pc-workspace"><div class="pc-main-card">${learn?pcLearningBody(s,l):pcQuizBody(s,l)}</div></div>${pcCommitMessage?`<p class="pc-error" role="alert">${esc(pcCommitMessage)}</p>`:''}<div class="pc-actions">${learn?`${pcBtn('先看字，稍後補聽','visual-next','','quiet')}${pcBtn(s.index===3?'我跟讀了，開始小測':'我跟讀了，下一個','learn-next',`id="pc-learn-next" ${s.audioOk?'':'disabled'}`,'primary')}`:r?pcBtn(s.index===4?'看看成績':'下一題','next',`id="pc-next"`,'primary'):pcBtn('交答案','submit','id="pc-submit" disabled','primary')}</div></section>`;
}
function pcSync(){const s=pcSession();if(!s)return;const b=$('#pc-submit'),q=s.queue[s.index];if(b)b.disabled=!!s.answers[s.index]||!s.draft.trim()||(['listenChoice','listenSpell'].includes(q?.type)&&!s.audioOk);const next=$('#pc-learn-next');if(next)next.disabled=!s.audioOk;}
function pcLearnNext(visual=false){const s=pcSession(),l=pcLesson();if(!s||s.mode!=='learn'||(!visual&&!s.audioOk))return;
 const p=pcProgress(l.id),i=s.index;if(!p.seen.includes(i))p.seen.push(i);if(!visual&&!p.read.includes(i))p.read.push(i);pcStop();s.audioOk=false;
 if(s.index<3){s.index++;save();render();}else{save();pcStore().session=null;pcSessionStart(l.id,'quiz');}}
function pcExpected(q,l){const w=l.words[q.wordIndex];return q.type==='missing'?w.focusIndices.map(i=>w.word[i]).join(''):w.word;}
function pcSubmit(technical=false){const s=pcSession(),l=pcLesson();if(!s||s.mode!=='quiz'||s.answers[s.index])return;const q=s.queue[s.index],needs=['listenChoice','listenSpell'].includes(q.type);
 if(technical){if(!needs||pcAudio.status!=='error')return;}else if(!s.draft.trim()||(needs&&!s.audioOk))return;
 s.answers.push({question:s.index,wordIndex:q.wordIndex,type:q.type,answer:technical?'':s.draft.trim(),correct:technical?null:norm(s.draft)===norm(pcExpected(q,l)),audioCompleted:needs&&!technical&&s.audioOk,technical,time:new Date().toISOString()});pcStop();save();if(!technical)playSfx(s.answers.at(-1).correct?'correct':'wrong');render();}
function pcNext(){const s=pcSession();if(!s||s.mode!=='quiz'||!s.answers[s.index])return;pcStop();if(s.index<4){s.index++;s.draft='';s.audioOk=false;save();render();}else pcFinish();}
function pcFinish(){const s=pcSession(),l=pcLesson();if(!s||s.mode!=='quiz'||s.answers.length!==5)return;const before=structuredClone(db),d=pcStore(),p=pcProgress(l.id),existing=d.runs.find(r=>r.id===s.id);if(existing){s.mode='result';render();return;}
 const score=s.answers.filter(a=>a.correct===true).length,pending=s.answers.filter(a=>a.technical).length,desired=0,logged=isLoggedIn();const delta=logged?a28RewardPhonics(s,l,pending):0;
 const result={id:s.id,lessonId:l.id,time:new Date().toISOString(),score,pending,total:5,award:delta,answers:structuredClone(s.answers)};
 p.latestResult={score,pending,time:result.time};if(!pending){p.completedTests++;p.bestScore=Math.max(p.bestScore,score);}/* Historical course starsAwarded remains read-only; a28RewardPhonics already updated the one wallet. */d.runs.push(result);if(d.runs.length>200)d.runs.splice(0,d.runs.length-200);s.mode='result';s.audioOk=false;
 if(!save()){db=before;pcCommitMessage='成績和金幣沒有儲存到。請不要關閉頁面。再按「看看成績」重試。';render();return;}pcCommitMessage='';playSfx('complete');render();}
function pcResult(){const s=pcSession(),l=pcLesson(),d=pcStore(),r=d.runs.find(x=>x.id===s?.id);if(!r||!l)return pcOverview();const p=pcProgress(l.id),next=PC.lessons.find(x=>x.number===l.number+1);
 return `<section class="pc-result card pad"><div class="pc-result-mark" aria-hidden="true">${r.pending?'♫':'✓'}</div><p class="eyebrow">第 ${l.number} 課 · ${esc(l.title)}</p><h1>${r.pending?'有讀音要補聽':'這課小測完成了'}</h1>${r.pending?'<div class="pc-score">'+r.score+'<small> / '+(5-r.pending)+'</small></div>':q36PhonicsBlock(r)}<p>${r.pending?`有 ${r.pending} 題播不出聲音，已跳過，不算錯。補做完整小測，才有金幣。`:(r.score===5?'五題全對！':'先看錯在哪裏，再重溫。')}</p><div class="pc-reward">${isLoggedIn()?(r.award?`🪙 今次獲得 ${r.award} 枚金幣`:`${r.pending?'先補聽，再領金幣':r.score<5?'這次沒有金幣，再試一次吧。':'這一課今天已得過金幣，或今天的金幣已滿。'}`):'登入後，才可以儲存紀錄和金幣。'}</div><p class="small muted">${isLoggedIn()?'':'這次訪客成績不會轉入新帳戶。'}</p><div class="pc-result-actions">${pcBtn('重溫這課','learn',`data-lesson="${l.id}"`,'secondary')}${pcBtn('再做小測','quiz',`data-lesson="${l.id}"`,'secondary')}${next?pcBtn('下一課','learn',`data-lesson="${next.id}"`,'primary'):link('選一課重溫','phonics','primary')}${link('返回課程','phonics','quiet')}</div><details class="pc-result-detail"><summary>看小測訂正</summary><ul class="list">${r.answers.map(a=>`<li><div><strong lang="en">${esc(l.words[a.wordIndex].word)}</strong><small class="muted">${esc(l.words[a.wordIndex].meaning)}</small></div><span>${a.technical?'待補聽':a.correct?'答對':'再練'}</span></li>`).join('')}</ul></details></section>`;}
function pcTeacherNote(){const l=pcLesson();if(!l)return;const d=document.createElement('dialog');d.id='pc-note';d.innerHTML=`<div class="pad"><div class="row between"><h2>家長教學小貼士</h2>${pcBtn('關閉','close-note','','quiet')}</div><p><strong lang="en">${esc(l.pattern)}</strong> · <span lang="en">${esc(l.ipa)}</span></p><p>${esc(l.parentNote)}</p><p>先聽整個字，再跟讀。</p></div>`;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();}
function pcReport(){const d=pcStore();return `<section class="pc-report card pad"><div class="row between"><h2>拼字專家 · 課程紀錄</h2>${link('開啟課程','phonics','secondary')}</div><p class="small muted"></p><div class="pc-report-table"><table><thead><tr><th>課數／重點</th><th>已學／已聽</th><th>最高小測</th><th>舊版獎勵紀錄</th></tr></thead><tbody>${PC.lessons.map(l=>{const p=d.progress[l.id];return `<tr><td>${l.number} · ${esc(l.pattern)}</td><td>${p?.seen.length||0}/4 · ${p?.heard.length||0}/4</td><td>${p?.completedTests?p.bestScore+'/5':'未完成'}${p?.latestResult?.pending?' · 待補聽':''}</td><td>${p?.starsAwarded||0}（歷史）</td></tr>`;}).join('')}</tbody></table></div><details><summary>最近的小測</summary><ul class="list">${d.runs.slice(-12).reverse().map(r=>`<li><span>第 ${pcLessons.get(r.lessonId).number} 課 · ${new Date(r.time).toLocaleDateString('zh-HK')}</span><span>${r.score}/${5-r.pending}${r.pending?' · 待補聽':' '} · +${r.award} 金幣</span></li>`).join('')||'<li>未有紀錄。</li>'}</ul></details><p class="small muted"></p></section>`;}
function pcAfterRender(){const s=pcSession(),ctx=[accountId(),activeChild()?.id,lastRoute,s?.id,s?.mode,s?.index].join('|');if(ctx!==pcContext){pcStop();if(s)s.audioOk=false;pcContext=ctx;$('#pc-note')?.close();}
 const active=lastRoute==='phonics-lesson'&&s&&s.mode!=='result';document.body.classList.toggle('phonics-active',!!active);if(active)document.body.classList.add('quiz-active');
 if(lastRoute==='phonics')$('#app').innerHTML=pcOverview();if(lastRoute==='phonics-lesson'){$('#app').innerHTML=pcLessonView();pcSync();}
 if(lastRoute==='kid'){const box=$('.fg-entry-card');if(box)box.innerHTML=`<div><span class="eyebrow">拼字專家 · 發音教學</span><h2>學一課，試一試。</h2><p>12 課 · 彩色拼法 · 課後小測</p></div><div class="stack">${link('開始拼字課','phonics','primary')}${link('自由練 air 家族','spelling-family','secondary')}</div>`;}
 if(lastRoute==='practice'){const a=document.createElement('a');a.href='#phonics';a.className='practice-card';a.innerHTML='<span class="bigicon" aria-hidden="true">♫</span><strong>拼字專家 · 分課學</strong>';$('#app .practice-grid')?.prepend(a);}
 if(lastRoute==='parent'||lastRoute==='report')$('#app').insertAdjacentHTML('beforeend',pcReport());
 updateViewport();}
const pcOriginalRender=render;render=function(){pcOriginalRender();pcAfterRender();};
const pcOriginalLogout=logout;logout=function(){pcStop();return pcOriginalLogout();};
const pcOriginalSetChild=setChild;setChild=function(id){pcStop();return pcOriginalSetChild(id);};
const pcOriginalDelete=deleteChild;deleteChild=function(id){pcStop();pcOriginalDelete(id);if(!db.children.some(c=>c.id===id)&&db.phonicsLearning?.children){delete db.phonicsLearning.children[id];save();}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-pc]');if(!b||b.disabled)return;const a=b.dataset.pc,s=pcSession();
 if(a==='learn'||a==='quiz')return pcSessionStart(b.dataset.lesson,a==='learn'?'learn':'quiz');
 if(a==='resume'){if(s){pcStop();s.audioOk=false;go('phonics-lesson');render();}return;}
 if(a==='pause'){pcStop();if(s)s.audioOk=false;save();go('phonics');return;}
 if(['play','slow','compare'].includes(a))return void pcPlay(a);
 if(a==='stop'){pcStop();if(s)s.audioOk=false;pcAudioUpdate();return;}
 if(a==='note')return pcTeacherNote();if(a==='close-note')return $('#pc-note')?.close();
 if(a==='learn-next')return pcLearnNext(false);if(a==='visual-next')return pcLearnNext(true);
 if(a==='select'&&s?.mode==='quiz'&&!s.answers[s.index]&&s.queue[s.index].options?.includes(b.dataset.value)){s.draft=b.dataset.value;save();render();return;}
 if(a==='submit')return pcSubmit();if(a==='skip')return pcSubmit(true);if(a==='next')return pcNext();
});
document.addEventListener('input',e=>{if(e.target.id==='pc-answer'){const s=pcSession();if(s?.mode==='quiz'&&!s.answers[s.index]){s.draft=e.target.value;save();pcSync();}}});
document.addEventListener('keydown',e=>{if(e.target.id==='pc-answer'&&e.key==='Enter'&&!e.isComposing&&!e.repeat){e.preventDefault();pcSubmit();}});
window.addEventListener('pagehide',()=>{pcStop();if(pcSession())pcSession().audioOk=false;});
document.addEventListener('visibilitychange',()=>{if(document.hidden){pcStop();if(pcSession())pcSession().audioOk=false;pcAudioUpdate();}});
window.addEventListener('offline',()=>{pcStop();if(pcSession())pcSession().audioOk=false;pcAudio.text='沒有網絡。會用已存的音檔，或裝置的英式聲音。';pcAudioUpdate();});


/* V19 integration, inside the original application's lexical scope. */
function validateArcadeState(raw,children){const out={version:1,active:{},best:{},preferences:{},history:[]};if(raw==null)return out;if(!raw||raw.version!==1)throw Error('arcade version');const cids=new Set(children.map(c=>c.id)),sp=window.WQArcadeCore.spec;const obj=x=>x&&typeof x==='object'&&!Array.isArray(x);const num=(x,lo,hi)=>typeof x==='number'&&Number.isFinite(x)&&x>=lo&&x<=hi;
for(const section of ['active','best','preferences']){if(!obj(raw[section]||{}))throw Error('arcade section');for(const[cid,v]of Object.entries(raw[section]||{})){if(!cids.has(cid))throw Error('arcade owner');if(section==='preferences'){out.preferences[cid]={level:[0,1,2].includes(v?.level)?v.level:1,shooter:v?.shooter!==false};continue;}if(section==='best'){out.best[cid]={};for(const[k,b]of Object.entries(v||{})){if(!/^(kart|volley|stairs|shooter|memory|simon):[012]$/.test(k)||!obj(b)||!num(b.score,0,1e9)||!num(b.seconds,0,181)||!num(b.rounds,1,1000000))throw Error('arcade record');out.best[cid][k]={score:b.score,seconds:b.seconds,rounds:b.rounds};}continue;}
if(v===null){out.active[cid]=null;continue;}if(!obj(v)||v.childId!==cid||!sp[v.game]||typeof v.id!=='string'||!/^arc_[A-Za-z0-9_-]{1,100}$/.test(v.id)||!num(v.durationMs,60000,180000)||!num(v.remainingMs,0,v.durationMs)||!Number.isInteger(v.level)||v.level<0||v.level>2||(v.testOnly===true?(!isTestAdmin()||v.cost!==0):v.cost!==sp[v.game].cost)||!['open','finished'].includes(v.status)||!num(v.round,1,1000000)||!Number.isFinite(Date.parse(v.createdAt)))throw Error('arcade ticket');if(v.snapshot&&!window.WQArcadeCore.snapshotValid(v.snapshot,v.game,v.level))throw Error('arcade snapshot');out.active[cid]={id:v.id,childId:cid,game:v.game,level:v.level,cost:v.cost,testOnly:v.testOnly===true,createdAt:v.createdAt,durationMs:v.durationMs,remainingMs:v.remainingMs,status:v.status,round:v.round,snapshot:v.snapshot?structuredClone(v.snapshot):null,resultRecorded:v.resultRecorded===true};}}
if(!Array.isArray(raw.history||[])||(raw.history||[]).length>100)throw Error('arcade history');out.history=(raw.history||[]).map(h=>{if(!cids.has(h.childId)||!sp[h.game]||typeof h.id!=='string'||h.id.length>110||!Number.isFinite(Date.parse(h.time))||(h.testOnly===true?(!isTestAdmin()||h.cost!==0):h.cost!==sp[h.game].cost)||!num(h.durationMs,60000,180000))throw Error('arcade receipt');return{id:h.id,childId:h.childId,game:h.game,time:h.time,cost:h.cost,testOnly:h.testOnly===true,durationMs:h.durationMs};});return out;}
const ARC=window.WQArcadeCore,PAINT=window.WQArcadePaint;let arEngine=null,arFrame=0,arCanvas=null,arContext=null,arBusy=false,arReleaseLease=null,arReason='',arSaving=false,arPortrait=false,arSizeObserver=null;
let arInput={},arPointers=new Map(),arHeldKeys=new Set(),arLast=0,arSaveClock=0,arHadError=false,arLeasedOwner='';
function arcStore(){return db.arcade||(db.arcade={version:1,active:{},best:{},preferences:{},history:[]});}
function arcPrefs(){const cid=activeChild()?.id;return arcStore().preferences[cid]||(arcStore().preferences[cid]={level:1,shooter:true});}
function arcTicket(){return isLoggedIn()?arcStore().active[activeChild()?.id]||null:null;}
const arFmt=ms=>{let n=Math.ceil(Math.max(0,ms)/1000);return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');};
function arButton(label,action,extra='',cls='secondary'){return `<button type="button" class="btn ${cls}" data-arc="${action}" ${extra}>${label}</button>`;}
function arBest(id){const b=arcStore().best[activeChild()?.id]?.[id+':'+arcPrefs().level];if(!b)return '未有紀錄';return id==='kart'&&b.score>0?'最佳 '+b.seconds.toFixed(1)+' 秒':id==='memory'?'最佳 '+b.score+' 分':'最佳 '+b.score+' 分';}
function arLobby(){const c=activeChild(),t=arcTicket(),p=arcPrefs();return `<section class="arc-lobby"><div class="arc-title"><div><p class="eyebrow">遊戲街機 · 做完練習，休息一會</p><h1>挑戰區</h1><p class="muted">要動手，也要動腦。用金幣換遊戲時間，時間內可以重玩。</p></div><div class="arc-balance">★ <strong id="arc-star-balance">${isLoggedIn()?c?.stars||0:0}</strong><span>學習金幣</span></div></div>${!isLoggedIn()?`<div class="notice">未登入可以照常學習。${link('登入後儲存金幣','login','secondary')} 玩遊戲要用登入帳戶的金幣。</div>`:''}${t&&t.status==='open'&&t.remainingMs>0?`<section class="arc-ticket card pad"><div><span class="eyebrow">尚未用完的遊戲票</span><h2>${ARC.spec[t.game].name}</h2><p>剩餘 ${arFmt(t.remainingMs)} · ${t.testOnly?'測試票，不扣金幣':'已用金幣換好，不會再扣金幣。'}</p></div><div>${arButton('繼續遊戲','resume','','primary')}${arButton('結束這張票','discard','','quiet')}</div></section>`:''}<div class="arc-preferences"><label for="arc-level">挑戰程度</label><select id="arc-level">${['入門','標準','挑戰'].map((n,j)=>`<option value="${j}" ${j===p.level?'selected':''}>${n}</option>`).join('')}</select><span class="small muted">每張票 ${db.settings.gameMinutes} 分鐘 · 重玩不再扣金幣</span></div><div class="arc-grid">${Object.values(ARC.spec).filter(g=>g.id!=='shooter').map(g=>`<article class="arc-gamecard"><div class="arc-thumb" data-thumb="${g.id}" aria-hidden="true"></div><div class="arc-cardbody"><p class="eyebrow">${g.tag}</p><h2>${g.name}</h2><p class="muted">${g.description}</p><span class="arc-best">${arBest(g.id)}</span><div class="arc-cardactions"><span>${adminUnlocks()?'測試免費':`★ ${g.cost}`} <small>/ ${db.settings.gameMinutes} 分鐘</small></span>${arButton('看看玩法','intro',`data-game="${g.id}"`,'primary')}</div></div></article>`).join('')}</div><p class="arc-footnote">圖形和玩法都是原創，沒有廣告，也沒有付費道具和排行榜。得分不會換金幣。</p>${link('返回學習','kid','secondary')}</section>`;}
gameView=arLobby;
function arIntro(game){const g=ARC.spec[game];if(!g||(game==='shooter'&&!arcPrefs().shooter&&!adminUnlocks()))return;arPause('玩法說明',false);$('#arc-intro')?.remove();const d=document.createElement('dialog');d.id='arc-intro';d.className='arc-dialog';const enough=isLoggedIn()&&(adminUnlocks()||activeChild().stars>=g.cost),old=arcTicket();d.innerHTML=`<div class="pad"><div class="row between"><h2>${g.name}</h2>${arButton('關閉','close-intro','','quiet')}</div><div class="arc-thumb intro-thumb" data-thumb="${game}" aria-hidden="true"></div><p>${g.description}</p><p class="arc-controls-help">${g.keys}</p><div class="notice">${['入門','標準','挑戰'][arcPrefs().level]} · ${adminUnlocks()?'測試，不扣金幣':`用 ${g.cost} 枚金幣`}，玩 ${db.settings.gameMinutes} 分鐘。時間內可以重玩。暫停和看結果，都不會用掉時間。</div>${!adminUnlocks()&&old&&old.status==='open'&&old.remainingMs>0?`<p>先繼續或結束已有的遊戲票。</p>${arButton('繼續已有遊戲','resume','','primary full')}`:!isLoggedIn()?link('登入儲金幣','login','primary full'):arButton(adminUnlocks()?'免費開始測試':enough?`使用 ${g.cost} 枚金幣開始`:'金幣不夠，先做練習','buy',`data-game="${game}" ${enough?'':'disabled'}`,'primary full')}<p class="small muted">帳戶和金幣只存在這個瀏覽器，不會上載到雲端。</p></div>`;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();arThumbs(d);d.querySelector('button').focus();}
function arThumbs(root=document){root.querySelectorAll('[data-thumb]').forEach(el=>{const id=el.dataset.thumb,s=ARC.create(id,1,41),c=document.createElement('canvas');c.width=ARC.spec[id].w;c.height=ARC.spec[id].h;PAINT.paint(c.getContext('2d'),s);el.replaceChildren(c);});}
async function arAcquire(){const owner=accountId()+':'+activeChild()?.id;if(arReleaseLease&&arLeasedOwner===owner)return true;if(arReleaseLease){arReleaseLease();arReleaseLease=null;}if(!navigator.locks){toast('這個瀏覽器不能鎖住遊戲票。請更新瀏覽器，或換另一個瀏覽器。','bad');return false;}return new Promise(resolve=>{navigator.locks.request('wordquest-arcade-'+owner,{ifAvailable:true},async lock=>{if(!lock){resolve(false);return;}let release;const hold=new Promise(r=>release=r);arReleaseLease=()=>{release();arReleaseLease=null;arLeasedOwner='';};arLeasedOwner=owner;resolve(true);await hold;}).catch(()=>resolve(false));});}
function arDropLease(){arReleaseLease?.();}
function arReadLatest(){if(!isLoggedIn())return;const raw=localStorage.getItem(dbKey());if(raw){db=validateDb(JSON.parse(raw));loadBlocked=false;}}
async function arBuy(game){if(arBusy||!isLoggedIn()||!ARC.spec[game])return;arBusy=true;try{if(!await arAcquire()){toast('這個帳戶已在另一個分頁開啟遊戲。請先暫停那一頁。','bad');return;}arReadLatest();if(game==='shooter'&&!arcPrefs().shooter&&!adminUnlocks()){arDropLease();return;}const existing=arcTicket();if(!adminUnlocks()&&existing&&existing.status==='open'&&existing.remainingMs>0){$('#arc-intro')?.close();await arResume();return;}const g=ARC.spec[game],c=activeChild();if(!adminUnlocks()&&c.stars<g.cost){arDropLease();toast('金幣未夠，沒有扣款。','bad');return;}const before=structuredClone(db),durationMs=db.settings.gameMinutes*60000,t={id:uid('arc'),childId:c.id,game,level:arcPrefs().level,cost:adminUnlocks()?0:g.cost,testOnly:adminUnlocks(),createdAt:new Date().toISOString(),durationMs,remainingMs:durationMs,status:'open',round:1,snapshot:null,resultRecorded:false};c.stars-=t.cost;arcStore().active[c.id]=t;arcStore().history.push({id:t.id,childId:c.id,game,time:t.createdAt,cost:t.cost,testOnly:t.testOnly,durationMs});arcStore().history=arcStore().history.slice(-100);if(!save()){db=before;arDropLease();toast('遊戲票未能儲存，沒有扣金幣。請家長檢查瀏覽器的儲存設定。','bad');return;}$('#arc-intro')?.close();arEngine={ticketId:t.id,state:ARC.create(game,t.level),paused:true};arReason='ready';stopSpeech();pcStop();fgStopAudio();go('arcade-play');render();}catch(e){arDropLease();toast('遊戲打不開。請家長檢查瀏覽器的儲存設定。','bad');}finally{arBusy=false;}}
async function arResume(){if(!isLoggedIn())return go('login');if(!await arAcquire()){toast('另一個分頁正在用這個帳戶的遊戲票。','bad');return;}try{arReadLatest();const t=arcTicket();if(!t||t.status!=='open'||t.remainingMs<=0){arDropLease();go('game');return;}if(t.game==='shooter'&&!arcPrefs().shooter&&!adminUnlocks()){arDropLease();toast('家長已停用射擊遊戲；遊戲票仍保留。','bad');return;}$('#arc-intro')?.close();arEngine={ticketId:t.id,state:t.snapshot&&ARC.snapshotValid(t.snapshot,t.game,t.level)?structuredClone(t.snapshot):ARC.create(t.game,t.level),paused:true};arEngine.paused=true;arReason=arEngine.state.result?'round':'ready';stopSpeech();pcStop();fgStopAudio();go('arcade-play');render();}catch(e){arDropLease();toast('讀不到遊戲票，原有資料沒有改動。請再試一次。','bad');}}
function arcadePlayView(){const t=arcTicket();if(!t||!arEngine||arEngine.ticketId!==t.id)return `<section class="card pad"><h1>繼續你的遊戲</h1><p>遊戲票和金幣只會在登入後使用。</p>${arButton('讀取遊戲票','resume','','primary')}${link('返回遊戲街機','game','secondary')}</section>`;const g=ARC.spec[t.game],labels={kart:['左轉','右轉','飄移','加速'],volley:['向左','向右','跳躍','扣球'],stairs:['向左','向右','',''],shooter:['向左','向右','','護盾'],memory:['上一張','下一張','翻牌',''],simon:['','','','']}[t.game];return `<section class="arc-shell" data-game="${t.game}" aria-label="${g.name}"><header class="arc-hud"><div><strong>${g.name}</strong><small>${['入門','標準','挑戰'][t.level]} · 第 ${t.round} 局</small></div><span class="arc-clock" id="arc-time" role="timer">${arFmt(t.remainingMs)}</span><div class="arc-hud-actions">${arButton('暫停','pause','','soft')}${arButton('放大','fullscreen','','quiet')}</div></header><div class="arc-viewport"><div class="arc-surface"><canvas id="arc-canvas" tabindex="0" role="img" aria-label="${g.name}遊戲畫面；操作：${g.keys}"></canvas><div id="arc-accessible"></div></div><div id="arc-overlay" class="arc-overlay"></div></div><div class="arc-controlbar"><div class="arc-controlkeys">${labels.map((n,j)=>n?`<button class="arc-pad ${j>1?'action':''}" data-arckey="${['left','right','action','special'][j]}" aria-label="${n}">${j===0?'◀ ':j===1?'▶ ':''}${n}</button>`:'').join('')}${t.game==='simon'?[0,1,2,3].map(n=>`<button class="arc-pad" data-arccell="${n}">${n+1}</button>`).join(''):''}</div><p id="arc-control-hint">${t.game==='shooter'?'可拖動飛船 · 自動發射':g.keys}</p></div><div id="arc-announcer" class="sr-only" aria-live="polite"></div></section>`;}
function arSetInput(){const base={...arInput};for(const k of ['left','right','up','down','action','special'])base[k]=arHeldKeys.has(k)||[...arPointers.values()].includes(k);arInput=base;}
function arClearInput(){arInput={};arPointers.clear();arHeldKeys.clear();$$('.arc-pad').forEach(b=>b.classList.remove('held'));}
function arPointerWorld(e){const r=arCanvas?.getBoundingClientRect(),s=arEngine?.state;if(!r||!s)return null;return{x:(e.clientX-r.left)*s.w/r.width,y:(e.clientY-r.top)*s.h/r.height};}
function arAttach(){if(!arEngine||!$('#arc-canvas'))return;cancelAnimationFrame(arFrame);arSizeObserver?.disconnect();arCanvas=$('#arc-canvas');arContext=arCanvas.getContext('2d',{alpha:false});if(!arContext){arReason='error';arOverlay();return;}arEngine.paused=true;arClearInput();arResize();arSizeObserver=new ResizeObserver(arResize);arSizeObserver.observe($('.arc-viewport'));arCanvas.addEventListener('pointerdown',e=>{if(arEngine.paused)return;arCanvas.setPointerCapture(e.pointerId);const p=arPointerWorld(e);if(arEngine.state.game==='shooter'){arInput.aim={x:p.x,y:p.y-32};arPointers.set(e.pointerId,'aim');}else{const n=ARC.hitCell(arEngine.state,p.x,p.y);if(n>=0)arInput.cell=n;}e.preventDefault();});arCanvas.addEventListener('pointermove',e=>{if(!arEngine.paused&&arPointers.get(e.pointerId)==='aim'){const p=arPointerWorld(e);arInput.aim={x:p.x,y:p.y-32};}});for(const ev of ['pointerup','pointercancel','lostpointercapture'])arCanvas.addEventListener(ev,e=>{if(arPointers.get(e.pointerId)==='aim'){delete arInput.aim;arPointers.delete(e.pointerId);}});
$$('[data-arckey]').forEach(b=>{b.addEventListener('pointerdown',e=>{if(arEngine.paused)return;b.setPointerCapture(e.pointerId);arPointers.set(e.pointerId,b.dataset.arckey);b.classList.add('held');arSetInput();if(arEngine.state.game==='memory'){const s=arEngine.state;if(b.dataset.arckey==='left')s.cursor=(s.cursor+s.cards.length-1)%s.cards.length;if(b.dataset.arckey==='right')s.cursor=(s.cursor+1)%s.cards.length;if(b.dataset.arckey==='action')arInput.cell=s.cursor;}e.preventDefault();});for(const ev of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,e=>{arPointers.delete(e.pointerId);b.classList.remove('held');arSetInput();});});arDraw();arOverlay();}
function arResize(){const vp=$('.arc-viewport'),surface=$('.arc-surface'),s=arEngine?.state;if(!vp||!surface||!arCanvas||!s)return;const r=vp.getBoundingClientRect();arPortrait=s.game==='kart'&&r.height>r.width;const dw=arPortrait?480:s.w,dh=arPortrait?680:s.h,scale=Math.max(.01,Math.min(r.width/dw,r.height/dh)),w=Math.floor(dw*scale),h=Math.floor(dh*scale),dpr=Math.min(2,devicePixelRatio||1);surface.style.width=w+'px';surface.style.height=h+'px';arCanvas.width=Math.max(1,Math.floor(w*dpr));arCanvas.height=Math.max(1,Math.floor(h*dpr));arCanvas.style.width=w+'px';arCanvas.style.height=h+'px';arContext?.setTransform(w*dpr/dw,0,0,h*dpr/dh,0,0);arDraw();arAccess();}
function arDraw(){if(arContext&&arEngine)try{PAINT.paint(arContext,arEngine.state,arPortrait);}catch(e){arEngine.paused=true;arReason='error';arOverlay();}}
function arAccess(){const box=$('#arc-accessible'),s=arEngine?.state;if(!box||!s)return;const signature=JSON.stringify([s.game,arEngine.paused,s.open,s.matched,s.phase,s.cursor]);if(box.dataset.signature===signature)return;box.dataset.signature=signature;const cells=s.game==='memory'?ARC.memoryCells(s):s.game==='simon'?ARC.simonCells():[];box.innerHTML=cells.map((b,j)=>`<button data-arccell="${j}" style="left:${b.x/s.w*100}%;top:${b.y/s.h*100}%;width:${b.w/s.w*100}%;height:${b.h/s.h*100}%" aria-label="${s.game==='memory'?`第 ${j+1} 張牌${s.matched.includes(j)?'，已配對':s.open.includes(j)?'，圖案 '+(s.cards[j]+1):'，未翻開'}`:`第 ${j+1} 個音階`}" ${arEngine.paused||(s.game==='simon'&&s.phase!=='input')?'disabled':''}></button>`).join('');$$('.arc-controlbar [data-arccell]').forEach(b=>b.disabled=arEngine.paused||(s.game==='simon'&&s.phase!=='input'));}
function arOverlay(){const box=$('#arc-overlay'),t=arcTicket(),s=arEngine?.state;if(!box||!s||!t)return;box.hidden=!arEngine.paused;if(!arEngine.paused){box.replaceChildren();arAccess();return;}let title='準備好了？',body=ARC.spec[s.game].description,action=arButton('開始','play','','primary');if(arReason==='paused'){title='已暫停';body='時間已停下來，金幣不會再扣。';action=arButton('繼續','play','','primary');}if(arReason==='round'){title=s.result?.title||'這一局完成';body=`本局 ${s.result?.seconds||s.time.toFixed(1)} 秒 · 分數 ${Math.round(s.score)}。剩餘 ${arFmt(t.remainingMs)}，可再挑戰。`;action=arButton('再挑戰 · 不扣金幣','retry','','primary');}if(t.remainingMs<=0||t.status==='finished'){title='小休完成';body='遊戲票時間已用完。回去學一小段，再來挑戰。';action=link('返回學習','kid','primary');}if(arReason==='save-error'){title='暫時未能儲存';body='遊戲已暫停。請重試儲存，不要關閉這個分頁。';action=arButton('重試儲存','retry-save','','primary');}if(arReason==='conflict'){title='另一個分頁更新了資料';body='遊戲已暫停，以免蓋掉新的紀錄。請只開一個分頁，再從遊戲街機重新讀取遊戲票。';action=arButton('重新讀取','resume','','primary');}if(arReason==='error'){title='遊戲暫時顯示不到，請稍後再試。';body='已停止計時。遊戲票仍保留。回到遊戲街機，可以再試一次。';action=link('返回遊戲街機','game','primary');}box.innerHTML=`<div class="arc-overlaycard" role="group" aria-label="${esc(title)}"><h2>${esc(title)}</h2><p>${esc(body)}</p><div class="row">${action}${arButton('收起遊戲','leave','','secondary')}</div><small>${t.status==='open'?'剩餘 '+arFmt(t.remainingMs)+' · 同一張票可重試':''}</small></div>`;arAccess();}
function arCheckpoint(){if(!arEngine||!isLoggedIn())return false;const t=arcTicket();if(!t||t.id!==arEngine.ticketId)return false;t.snapshot=structuredClone(arEngine.state);if(!save()){arEngine.paused=true;arReason='save-error';arClearInput();arOverlay();return false;}return true;}
function arPause(reason='paused',release=true){if(arEngine){arEngine.paused=true;cancelAnimationFrame(arFrame);arClearInput();if(reason)arReason=reason;arCheckpoint();arOverlay();}if(release)arDropLease();stopSfx();}
function arRecordRound(){const t=arcTicket(),s=arEngine?.state;if(!t||!s||t.resultRecorded)return;const cid=t.childId,key=t.game+':'+t.level,all=arcStore().best[cid]||(arcStore().best[cid]={}),prior=all[key];const score=Math.round(s.score),seconds=Number(s.time.toFixed(1)),isKart=t.game==='kart';const eligible=!isKart||s.result?.won;if(eligible){const improve=!prior||(isKart?seconds<prior.seconds:score>prior.score);all[key]={score:improve?score:prior.score,seconds:improve?seconds:prior.seconds,rounds:(prior?.rounds||0)+1};}t.resultRecorded=true;}
function arSound(e){if(!sfxEnabled()||document.hidden||arEngine?.paused)return;const ctx=ensureAudioCtx();if(!ctx)return;const at=ctx.currentTime+.006;try{if(Number.isInteger(e.note)){tone(ctx,[392,494,587,784][e.note],at,.22,'sine',.028);return;}const notes={ball:[490],point:[523,659],win:[523,659,784],end:[330,294],collect:[740,880],boost:[294,440,587],shield:[220,440],card:[420],hit:[620],bump:[155]};(notes[e.fx]||[]).forEach((f,i)=>tone(ctx,f,at+i*.065,e.fx==='bump'?.10:.09,e.fx==='bump'?'triangle':'sine',.022));}catch(_){} }
function arStepFrame(now){if(!arEngine||arEngine.paused||lastRoute!=='arcade-play')return;const t=arcTicket();if(!t||t.id!==arEngine.ticketId||!arReleaseLease){arPause('paused');return;}const elapsed=Math.max(0,(now-arLast)/1000);arLast=now;if(document.hidden||elapsed>.25){arPause();toast('畫面停了一會，遊戲已暫停。停住的時間不會用掉。');return;}if(pgLegacyBudget()<=0){arPause();toast('今天的遊戲上限到了。沒用完的時間會保留。');return;}const consume=Math.min(t.remainingMs,elapsed*1000,pgLegacyBudget());pgLegacyUsed(consume);t.remainingMs=Math.max(0,t.remainingMs-consume);let pending=Math.min(.25,consume/1000);try{while(pending>1e-6){const step=Math.min(1/60,pending);ARC.tick(arEngine.state,arInput,step);for(const e of arEngine.state.event)arSound(e);pending-=step;if(arEngine.state.result)break;}arDraw();arAccess();$('#arc-time').textContent=arFmt(t.remainingMs);arSaveClock+=elapsed;if(t.remainingMs===0){arRecordRound();t.status='finished';arEngine.paused=true;arReason='time';arCheckpoint();arOverlay();arDropLease();return;}if(arEngine.state.result){arRecordRound();arEngine.paused=true;arReason='round';arCheckpoint();arOverlay();return;}if(arSaveClock>=.8){arSaveClock=0;if(!arCheckpoint())return;}arFrame=requestAnimationFrame(arStepFrame);}catch(e){arEngine.paused=true;arReason='error';arCheckpoint();arOverlay();}}
async function arPlay(retry=false){if(!arEngine||!arcTicket())return;if(!await arAcquire()){toast('請先暫停另一個分頁的遊戲。','bad');return;}const t=arcTicket();if(t.remainingMs<=0||t.status!=='open')return;if(retry){t.round++;t.resultRecorded=false;arEngine.state=ARC.create(t.game,t.level,(arEngine.state.seed+74173)|0);}if(!arCheckpoint())return;arEngine.paused=false;arReason='';arLast=performance.now();arSaveClock=0;arClearInput();arOverlay();arCanvas?.focus({preventScroll:true});ensureAudioCtx();arFrame=requestAnimationFrame(arStepFrame);}
async function arDiscard(){const t=arcTicket();if(!t||t.status!=='open'||!confirm('要結束這張遊戲票嗎？沒用完的時間不會退回金幣。遊戲紀錄會保留。'))return;if(!await arAcquire()){toast('請先暫停另一個分頁。','bad');return;}arReadLatest();const current=arcTicket(),before=structuredClone(db);if(current){current.remainingMs=0;current.status='finished';if(!save()){db=before;arDropLease();return;}}arEngine=null;arDropLease();render();}
function arViewport(){const vh=window.visualViewport?.height||innerHeight;document.documentElement.style.setProperty('--arc-vh',vh+'px');document.documentElement.style.setProperty('--arc-header',($('.header')?.getBoundingClientRect().height||65)+'px');arResize();}
const arPriorAfterRender=afterRender;afterRender=function(route){arPriorAfterRender(route);document.body.classList.toggle('arcade-active',route==='arcade-play');if(route==='arcade-play'){arAttach();arViewport();}else{if(arEngine&&!arEngine.paused)arPause('paused');arSizeObserver?.disconnect();arCanvas=null;arContext=null;if(route==='game')arThumbs();}if(route==='parent'||route==='report'){const t=arcTicket(),rows=arcStore().history.filter(x=>x.childId===activeChild()?.id).slice(-8).reverse();$('#app').insertAdjacentHTML('beforeend',`<details class="card pad" style="margin-top:18px"><summary><strong>遊戲街機 · 遊戲票紀錄</strong></summary><p class="small muted">遊戲成績不會算進英文能力。每張票只扣一次金幣，暫停時不計時。</p>${t&&t.status==='open'?`<p>現有：${ARC.spec[t.game].name} · 剩餘 ${arFmt(t.remainingMs)}</p>`:''}<ul class="list">${rows.map(r=>`<li><span>${ARC.spec[r.game].name}<small class="muted"> · ${new Date(r.time).toLocaleDateString('zh-HK')}</small></span><span>${r.testOnly?'測試，不扣金幣':`−${r.cost} 金幣`} · ${r.durationMs/60000} 分鐘</span></li>`).join('')||'<li>未有遊戲票紀錄。</li>'}</ul></details>`);}if(route==='settings'){const sec=document.createElement('section');sec.className='card pad';sec.style.marginTop='18px';sec.innerHTML=`<h2>挑戰區</h2><label class="arc-check"><input id="arc-shooter-setting" type="checkbox" ${arcPrefs().shooter?'checked':''}>顯示非血腥太空射擊</label><p class="small muted">關閉後，孩子的遊戲街機不會出現射擊遊戲。</p>${arButton('儲存遊戲設定','save-prefs','','primary')}`;$('#app').append(sec);}};
const arPriorLogout=logout;logout=function(){arPause('paused');arEngine=null;return arPriorLogout();};const arPriorChild=setChild;setChild=function(id){arPause('paused');arEngine=null;return arPriorChild(id);};const arPriorDelete=deleteChild;deleteChild=function(id){arPause('paused');arPriorDelete(id);if(!db.children.some(c=>c.id===id)&&db.arcade){delete db.arcade.active[id];delete db.arcade.best[id];delete db.arcade.preferences[id];db.arcade.history=db.arcade.history.filter(h=>h.childId!==id);save();}};
const arPriorRender=render;render=function(){const route=(location.hash||'#kid').slice(1).split('?')[0];if(lastRoute==='arcade-play'&&route!==lastRoute)arPause('paused');arPriorRender();document.body.classList.toggle('arcade-active',route==='arcade-play');if(route==='arcade-play')arViewport();};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-arc]');if(b&&!b.disabled){const a=b.dataset.arc;if(a==='intro')arIntro(b.dataset.game);if(a==='close-intro')$('#arc-intro')?.close();if(a==='buy')await arBuy(b.dataset.game);if(a==='resume')await arResume();if(a==='play')await arPlay();if(a==='pause')arPause();if(a==='retry')await arPlay(true);if(a==='retry-save'){if(arCheckpoint()){arReason='paused';arOverlay();}}if(a==='leave'){arPause();go('game');}if(a==='discard')await arDiscard();if(a==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch(_){toast('這個瀏覽器不能全螢幕。直接在這個畫面玩就可以。');}}if(a==='save-prefs'){const p=arcPrefs(),old=p.shooter;p.shooter=$('#arc-shooter-setting').checked;if(save())toast('遊戲設定已儲存。');else p.shooter=old;}}
const cell=e.target.closest('[data-arccell]');if(cell&&!cell.disabled&&arEngine&&!arEngine.paused)arInput.cell=Number(cell.dataset.arccell);});
document.addEventListener('change',e=>{if(e.target.id==='arc-level'){const p=arcPrefs(),prev=p.level;p.level=Number(e.target.value);if(!save())p.level=prev;render();}});
const arKeyMap={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down',a:'left',d:'right',w:'up',s:'down',' ':'action',x:'special',X:'special'};
document.addEventListener('keydown',e=>{if(lastRoute!=='arcade-play'||!arEngine||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key==='Escape'){e.preventDefault();arPause();return;}if(arEngine.paused)return;const key=arKeyMap[e.key];if(key){e.preventDefault();arHeldKeys.add(key);arSetInput();if(arEngine.state.game==='memory'&&!e.repeat){const s=arEngine.state;s.cursor=(s.cursor+(key==='left'?-1:key==='right'?1:key==='up'?-4:key==='down'?4:0)+s.cards.length)%s.cards.length;if(key==='action')arInput.cell=s.cursor;}}if(arEngine.state.game==='simon'&&/^[1-4]$/.test(e.key)&&!e.repeat){e.preventDefault();arInput.cell=Number(e.key)-1;}});
document.addEventListener('keyup',e=>{const key=arKeyMap[e.key];if(key){arHeldKeys.delete(key);arSetInput();}});
window.addEventListener('blur',()=>{if(arEngine&&!arEngine.paused)arPause();});document.addEventListener('visibilitychange',()=>{if(document.hidden)arPause();});window.addEventListener('pagehide',()=>arPause());window.addEventListener('resize',arViewport);window.visualViewport?.addEventListener('resize',arViewport);
window.addEventListener('storage',e=>{if(isLoggedIn()&&e.key===dbKey()&&arEngine){cancelAnimationFrame(arFrame);arEngine.paused=true;arReason='conflict';arDropLease();arClearInput();arOverlay();}});

/* Prevent stale tabs from overwriting newer local account data. Not a cloud security boundary. */
const saveBeforeV19=save;
save=function(){if(!isLoggedIn())return true;if(loadBlocked)return saveBeforeV19();const rev=Number(db.writeRevision)||0;try{const raw=localStorage.getItem(dbKey());let remote=null;if(raw){try{remote=JSON.parse(raw);}catch(e){if(!arRecoveringCorrupt)throw e;}}if(remote&&(Number(remote.writeRevision)||0)>rev){persistenceIssue='另一個分頁有較新的資料，這裏沒有蓋掉它。請先匯出備份，再重新打開頁面。';showSaveIssue();return false;}db.writeRevision=rev+1;const ok=saveBeforeV19();if(!ok)db.writeRevision=rev;return ok;}catch(e){persistenceIssue='這部裝置儲存不到資料。請不要關閉這個分頁，並先匯出備份。';showSaveIssue();return false;}};

/* Intentional backup restore/reset carries the CURRENT revision, never the old backup's.
   This is distinct from a stale background tab overwriting the current account. */
let arRecoveringCorrupt=false;
function arSaveReplacement(previous,wasBlocked){
 const originalRevision=db.writeRevision;
 db.writeRevision=Number(previous?.writeRevision)||0;
 arRecoveringCorrupt=wasBlocked===true;
 try{const ok=save();if(ok){cancelAnimationFrame(arFrame);arClearInput();arEngine=null;arDropLease();}
 else db.writeRevision=originalRevision;return ok;}finally{arRecoveringCorrupt=false;}
}

/* V20 parent import workspace, installed inside the existing application closure.
 * Leaves V19 accounts, phonics, assessment and arcade code intact.
 */
const V20=window.WQImportCore;
const v20Dictionary=V20.dictIndex(sharedEntries);
function v20Fresh(){return {mode:'list',items:[],documents:[],history:[],common:new Set(V20.COMMON),revision:0,filter:'all',showLimit:120,rawDirty:false,parsedRaw:'',message:'',mergeStart:null,mergeMode:false,editing:false,saving:false};}
let v20=v20Fresh(),v20Photo=null,v20PhotoEpoch=0,v20FileLoading=false,v20Origin=null;
function v20Owner(){return (accountId()||'guest')+'|'+(activeChild()?.id||'');}
function v20History(){v20.history.push({items:V20.clone(v20.items),documents:v20.documents.slice(),raw:importDraft.raw,parsedRaw:v20.parsedRaw,rawDirty:v20.rawDirty,mode:v20.mode,common:[...v20.common]});if(v20.history.length>20)v20.history.shift();}
function v20Touch(){v20.revision++;v20.editing=true;importDraft.confirmed=false;if(ocrBusy){cancelOCR();v20.message='你改了選字，這次辨認已停止。原有的修改會保留。';updateImportPhoto();}const cb=$('#confirm-import');if(cb)cb.checked=false;}
function v20Kind(c){return c.kind==='sentence'?'整句':c.kind==='phrase'?'詞組':'生字';}
function v20Recheck(c){const g=V20.gloss(c.en,v20Dictionary);c.known=g.known;c.choices=g.choices;c.example=g.example;c.common=v20.common.has(V20.fold(c.en))&&!/\s/.test(c.en)&&c.kind!=='sentence';return c;}
function v20KnownWords(){const map=new Map();if(!isLoggedIn())return map;const words=new Map(childWords().map(w=>[w.id,w]));for(const a of db.attempts){if(!words.has(a.wordId)||!['spell','listenSpell','cloze'].includes(a.type)||a.assisted||a.technical)continue;const w=words.get(a.wordId),k=w.en+'|'+(w.zh||''),old=map.get(k);if(!old||a.time>old.time)map.set(k,a);}return map;}
function v20Info(c){if(V20.pending(c))return '請核對';if(c.reviewed)return '已核對';if(c.excludedReason)return '未加入';return c.kind==='phrase'?'整個詞組':c.common?'常用字':'按一下取消';}
function v20Selected(){return V20.selected(v20.items);}
function v20Pending(){return v20.items.filter(V20.pending);}
function v20SyncDraft(){draftWords=v20Selected().map(c=>({en:c.en,zh:c.zh,kind:c.kind}));}
function v20Card(c,known){const isKnown=known.get(c.en+'|'+c.zh)?.correct===true;return `<article class="v20-candidate ${c.selected?'is-selected':''} ${V20.pending(c)?'is-review':''} ${v20.mergeStart===c.id?'merge-start':''}" data-candidate-id="${esc(c.id)}"><button class="v20-token" type="button" data-imp="toggle" data-id="${esc(c.id)}" aria-pressed="${c.selected}" aria-label="${c.selected?'取消':'加入'} ${esc(c.en)}"><span class="tick" aria-hidden="true">${c.selected?'✓':''}</span><span class="txt"><strong lang="en-GB">${esc(c.en)}</strong><small>${esc(c.zh||'中文可稍後補上')}</small>${isKnown?'<small>曾經自己拼對</small>':''}</span></button><div class="v20-candidate-foot"><span>${v20Info(c)}${c.occurrences>1?' · '+c.occurrences+' 處':''}</span><button type="button" data-imp="edit" data-id="${esc(c.id)}" aria-label="核對或修改 ${esc(c.en)}">${V20.pending(c)?'核對':'修改'}</button></div></article>`;}
rangeNewView=function(){return `${navTabs('ranges')}<section class="import-v20" id="import-v20"><div class="row between"><div><div class="eyebrow">家長 · 默書範圍</div><h1>拍好，選字，就能練。</h1><p class="small muted">先整理，再由你選今次要默的內容。</p></div>${link('返回','ranges','quiet')}</div><div class="v20-stepper" aria-label="匯入步驟"><span>1 加入相片／文字</span><span>2 點選字詞</span><span>3 核對及加入</span></div><div class="v20-layout"><section class="card v20-source"><h2>1. 加入範圍</h2><div class="form-grid"><div class="v20-field"><label for="range-title">名稱</label><input id="range-title" maxlength="120" placeholder="例如 Unit 4" value="${esc(importDraft.title)}"></div><div class="v20-field"><label for="range-date">默書日期（可不填）</label><input id="range-date" type="date" value="${esc(importDraft.date)}"></div></div><div class="v20-choices"><button class="btn secondary" data-act="open-camera"><span class="ico" aria-hidden="true">📷</span>拍照</button><button class="btn secondary" data-act="open-upload"><span class="ico" aria-hidden="true">🖼️</span>上傳圖片</button></div><input id="ocr-camera" type="file" accept="image/*" capture="environment" hidden><input id="ocr-upload" type="file" accept="image/*" hidden><div id="ocr-file-name" class="v20-file-name">未選擇圖片</div><div class="v20-photo"><img id="ocr-preview" alt="所選默書相片" hidden></div><div class="v20-toolbar" id="v20-photo-tools" ${v20Photo?'':'hidden'}><button class="btn secondary" data-imp="crop">框選／拉直</button><button class="btn quiet" data-imp="full-photo">看原相</button></div><div class="row"><button class="btn primary" data-act="run-ocr" id="run-ocr" disabled>辨認所選範圍</button><button class="btn quiet" data-imp="cancel-ocr" id="v20-cancel-ocr" hidden>停止</button></div><div id="ocr-progress" class="v20-progress" hidden><span></span></div><div id="ocr-status" class="v20-inline-status" role="status"></div><details id="v20-text-details" ${importDraft.raw||!v20Photo?'open':''}><summary>或直接貼上文字</summary><div class="v20-field"><label for="raw-words">原文（保留作對照）</label><textarea id="raw-words" maxlength="30000" spellcheck="false" placeholder="apple banana orange&#10;ice cream&#10;school bag&#10;&#10;也可每行輸入：英文 | 中文">${esc(importDraft.raw)}</textarea></div><button class="btn secondary full" data-imp="parse">整理成可選字詞</button></details><details><summary>相片辨認及私隱</summary><p class="small muted">請先裁走姓名、校名等個人資料。只能辨認印刷的英文。第一次使用要連上網絡，下載辨認用的資料。相片只在這個瀏覽器處理，不會上傳。辨認結果要對照原稿檢查。</p><p class="small muted">原相片和未儲存的草稿，只留在這個分頁。重新載入或關閉頁面，就會消失。加入教材時，只儲存已選的字詞和對應的文字片段，不會儲存整張相片。</p><div class="v20-field"><label for="v20-psm">版面處理</label><select id="v20-psm"><option value="3">自動分欄</option><option value="6">已框選的一欄文字</option><option value="11">分散的生字表</option></select></div><label class="v20-check"><input type="checkbox" id="v20-enhance">稍為加強文字對比</label></details></section><section class="card v20-selection"><div class="row between"><h2>2. 點選字詞</h2><button class="btn quiet" data-imp="add" style="font-size:14px">＋ 自己加入</button></div><div class="v20-modes" role="group" aria-label="選取方式">${[['list','生字清單','整行多字會拆開'],['passage','文章挑字','常用字可略過'],['sentences','整句默書','保留字詞及標點']].map(([k,t,s])=>`<button class="v20-mode" data-imp="mode" data-value="${k}" aria-pressed="${v20.mode===k}"><strong>${t}</strong><small>${s}</small></button>`).join('')}</div><p class="v20-mode-note" id="v20-mode-note"></p><div id="v20-message" class="v20-inline-status" role="status"></div><div id="word-editor"></div></section></div><div class="v20-selected-footer" id="v20-import-dock"><div class="inner"><div><strong id="v20-selected-count">已選 0 項</strong><small id="v20-pending-count">最多 120 項</small></div><button class="btn primary" data-imp="summary" id="v20-confirm-next" disabled>核對及加入 →</button></div></div></section>`;};
renderWordEditor=function(){v20RenderWords();};
syncDraftInputs=function(){v20SyncDraft();};
captureImportDraft=function(){if(skipImportCapture){skipImportCapture=false;return;}if(!$('#range-title'))return;importDraft.title=$('#range-title').value;importDraft.date=$('#range-date').value;if($('#raw-words'))importDraft.raw=$('#raw-words').value;if($('#confirm-import'))importDraft.confirmed=$('#confirm-import').checked;v20SyncDraft();};
restoreImportDraft=function(){if(!$('#range-title'))return;$('#range-title').value=importDraft.title;$('#range-date').value=importDraft.date;$('#raw-words').value=importDraft.raw;v20RenderWords();updateImportPhoto();};
const v20PreviousClear=clearImportDraft;
clearImportDraft=function(){v20PhotoEpoch++;v20CloseAll();for(const d of v20.documents||[])if(d.previewURL)URL.revokeObjectURL(d.previewURL);if(v20Photo?.originalURL)URL.revokeObjectURL(v20Photo.originalURL);v20Photo=null;v20FileLoading=false;v20=v20Fresh();v20Origin=null;v20PreviousClear();};
function v20RenderWords(){const box=$('#word-editor');if(!box)return;v20SyncDraft();const note=$('#v20-mode-note');if(note)note.textContent={list:'清單裏的短字也會保留。拼法相同的字和詞組，由你核對。',passage:'先全選，按需要略過常用字。只改選取，不改原句。',sentences:'保留完整句子、大小寫及標點，不移除常用字。多欄請逐欄框選。'}[v20.mode];$$('[data-imp="mode"]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.value===v20.mode));
 const msg=$('#v20-message');if(msg)msg.textContent=v20.rawDirty?'原文已修改，請按「整理成可選字詞」；原有選詞暫時保留。':v20.message;
 const selection=v20Selected(),pend=v20Pending();$('#v20-selected-count').textContent=`已選 ${selection.length} / 120 項`;$('#v20-pending-count').textContent=pend.length?`${pend.length} 項需核對 · 可修改或略過`:selection.length?'按一下字母組合可取消':'先加入相片或文字';$('#v20-confirm-next').disabled=!selection.length||v20.rawDirty||v20FileLoading||ocrBusy;$('#v20-confirm-next').textContent=pend.length?`核對 ${pend.length} 項 →`:'核對及加入 →';
 if(!v20.items.length){box.innerHTML='<div class="v20-empty"><div class="empty-mark" aria-hidden="true">Aa ✓</div><p>拍照、上傳或貼上文字。<br>這裏會變成可點選的字詞。</p></div>';return;}
 const known=v20KnownWords(),excluded=v20.items.filter(c=>c.excludedReason&&!c.selected),all=v20.items.filter(c=>!c.excludedReason||c.selected),common=v20.mode==='passage'?all.filter(c=>c.common):[];
 const filter=items=>items.filter(c=>v20.filter==='review'?V20.pending(c):v20.filter==='unselected'?!c.selected:true);const normal=filter(v20.mode==='passage'?all.filter(c=>!c.common):all);const subset=normal.slice(0,v20.showLimit);
 const commonRows=filter(common);const duplicateCount=selection.length-new Set(selection.map(c=>c.en+'\u0000'+c.zh)).size;
 box.innerHTML=`<div class="v20-filter" role="group" aria-label="篩選字詞">${[['all','全部'],['review',`需核對 ${pend.length}`],['unselected','未選']].map(([k,t])=>`<button data-imp="filter" data-value="${k}" aria-pressed="${v20.filter===k}">${t}</button>`).join('')}</div><div class="v20-toolbar"><button class="btn quiet" data-imp="select-all">全選教材</button><button class="btn quiet" data-imp="select-none">取消全選</button><button class="btn quiet" data-imp="merge-mode" aria-pressed="${v20.mergeMode}">${v20.mergeMode?'取消合併':'合併字詞'}</button><button class="btn quiet" data-imp="undo" ${v20.history.length?'':'disabled'}>復原</button></div>${v20.mode==='passage'&&common.length?`<div class="v20-toolbar"><button class="btn secondary" data-imp="skip-common">略過常用字（${common.length}）</button><span class="small muted">原句及詞組不會改動</span></div>`:''}${v20.mergeMode?`<p class="v20-review-notice">${v20.mergeStart?'再按同一行的最後一個字。':'按同一行的第一個字，再按最後一個字。'}合併只調整選詞，不改原稿。</p>`:''}${duplicateCount?`<p class="v20-review-notice">有 ${duplicateCount} 個完全相同的已選項目。<button class="btn quiet" data-imp="dedupe">合併相同項目</button></p>`:''}<div class="v20-grid ${v20.mode==='sentences'?'sentences':''}">${subset.map(c=>v20Card(c,known)).join('')||'<p class="small muted">這組暫時沒有字詞。</p>'}</div>${normal.length>subset.length?`<button class="btn secondary full" data-imp="more">再顯示 ${Math.min(120,normal.length-subset.length)} 項（還有 ${normal.length-subset.length} 項）</button>`:''}${v20.mode==='passage'&&common.length?`<details class="v20-common" ${v20.filter==='review'?'open':''}><summary>常用字 ${common.length} 項 · 已選 ${common.filter(c=>c.selected).length} 項</summary><p class="small muted"></p><div class="v20-toolbar"><button class="btn secondary" data-imp="skip-common">略過這組</button><button class="btn quiet" data-imp="select-common">全部加入</button><button class="btn quiet" data-imp="edit-common">更改分組</button></div><div class="v20-grid">${commonRows.slice(0,v20.showLimit).map(c=>v20Card(c,known)).join('')}</div></details>`:''}${excluded.length?`<details class="v20-excluded"><summary>未加入內容 ${excluded.length} 項</summary><p class="small muted">可能是頁首、姓名或日期。沒有刪除，需要時可以加回。</p>${excluded.map(c=>`<div class="v20-source-line"><div><p lang="en">${esc(c.en)}</p><small>${esc(c.excludedReason)}</small></div><button class="btn secondary" data-imp="restore" data-id="${esc(c.id)}">加入</button></div>`).join('')}</details>`:''}`;
}
function v20Parse(){captureImportDraft();const raw=importDraft.raw;if(!raw.trim()){toast('請先貼上英文，或用相片辨認。','bad');return;}if(raw.length>30000){toast('文字太長，請分開加入。','bad');return;}if(v20.items.length&&!confirm('要按目前的原文重新整理嗎？現有的點選和修改會重設。可以按「復原」取回。'))return;v20History();v20Touch();const doc=V20.fromText(raw,uid('text'));const items=V20.candidates(doc,{mode:v20.mode,dictionary:v20Dictionary,common:v20.common});if(items.length>1500){toast('內容太多，請分區或分段加入。','bad');return;}v20.documents=[doc];v20.items=items;v20.rawDirty=false;v20.parsedRaw=raw;v20.mergeMode=false;v20.filter='all';v20.showLimit=120;v20.message='已整理。按字母組合選取；不確定的字可按「核對」。';v20RenderWords();$('#v20-mode-note')?.scrollIntoView({block:'start'});}
function v20ChangeMode(mode){if(!['list','passage','sentences'].includes(mode)||mode===v20.mode)return;if(v20.items.length&&!confirm('換選取方式後，字詞會重新分開，並全部選取。原文不變。可以按「復原」取回。'))return;const docs=v20.rawDirty?[V20.fromText(importDraft.raw,uid('text'))]:v20.documents;const items=docs.flatMap(d=>V20.candidates(d,{mode,dictionary:v20Dictionary,common:v20.common}));if(items.length>1500){toast('項目太多，請縮小範圍再整理。','bad');return;}v20History();v20Touch();v20.mode=mode;v20.documents=docs;v20.items=items;v20.filter='all';v20.rawDirty=false;v20.parsedRaw=importDraft.raw;v20.mergeMode=false;v20.message='已換選取方式。常用字不會自動取消。';v20RenderWords();}
function v20Undo(){const state=v20.history.pop();if(!state)return;v20Touch();Object.assign(v20,state);v20.common=new Set(state.common||V20.COMMON);importDraft.raw=state.raw;$('#raw-words').value=state.raw;v20.mergeMode=false;v20.message='已復原上一個操作。';v20RenderWords();}
function v20CloseAll(){for(const d of $$('.v20-dialog')){try{d.close();}catch(_){}d.remove();}}
function v20Dialog(title,body,foot='',id='v20-dialog'){const current=$('#'+id);current?.remove();const origin=document.activeElement;const d=document.createElement('dialog');d.id=id;d.className='v20-dialog';d.setAttribute('aria-label',title);d.innerHTML=`<header class="v20-dialog-head"><h2>${esc(title)}</h2><button type="button" data-imp="close-dialog">關閉</button></header><div class="v20-dialog-body">${body}</div>${foot?`<footer class="v20-dialog-foot">${foot}</footer>`:''}`;document.body.append(d);d.addEventListener('close',()=>{d.remove();if(origin?.isConnected)origin.focus({preventScroll:true});});d.showModal();d.querySelector('button')?.focus({preventScroll:true});return d;}
function v20SourceBody(c){const d=v20.documents.find(d=>d.id===c.sourceRegionId),b=V20.union(c.sourceBoxes);return `<p class="v20-source-label">原來辨認到：<strong lang="en">${esc(c.originalText)}</strong></p>${d?.previewURL?`<img class="v20-crop-snippet" id="v20-snippet" alt="這個字在辨認相片中的位置"><details><summary>看整個辨認範圍</summary><div class="v20-full-source"><img src="${esc(d.previewURL)}" alt="這次辨認的相片範圍">${b?`<span class="v20-box" style="left:${100*b.x0/d.width}%;top:${100*b.y0/d.height}%;width:${100*(b.x1-b.x0)/d.width}%;height:${100*(b.y1-b.y0)/d.height}%"></span>`:''}</div></details>`:''}<details ${!d?.previewURL?'open':''}><summary>對照原文</summary><p class="v20-snippet" lang="en">${esc(c.sourceText)}</p></details>${c.confidenceRaw!==null?`<details><summary>辨認資訊</summary><p class="small muted">辨認分數：${Math.round(c.confidenceRaw)}。即使沒有提示，也可能認錯或漏字。</p></details>`:''}`;}
function v20FillSnippet(c){const region=v20.documents.find(d=>d.id===c.sourceRegionId),el=$('#v20-snippet');if(!el||!region?.previewURL)return;const b=V20.union(c.sourceBoxes);if(!b){el.src=region.previewURL;return;}const image=new Image();image.onload=()=>{if(!el.isConnected)return;const pad=Math.max(12,(b.y1-b.y0)*.8),x=Math.max(0,b.x0-pad),y=Math.max(0,b.y0-pad),w=Math.min(image.width-x,b.x1-b.x0+2*pad),h=Math.min(image.height-y,b.y1-b.y0+2*pad);if(w<=0||h<=0){el.src=region.previewURL;return;}const cv=document.createElement('canvas');cv.width=Math.min(1000,Math.max(250,w*2));cv.height=Math.max(35,Math.round(h*cv.width/w));cv.getContext('2d').drawImage(image,x,y,w,h,0,0,cv.width,cv.height);el.src=cv.toDataURL('image/png');};image.onerror=()=>{el.src=region.previewURL;};image.src=region.previewURL;}
function v20Edit(id){const c=v20.items.find(x=>x.id===id);if(!c)return;const sugg=V20.suggestions(c.en,v20Dictionary);const reasons=c.reviewReasons.length?`<p class="v20-review-notice">${esc(c.reviewReasons.join('；'))}。</p>`:'';const body=`${reasons}${v20SourceBody(c)}<div class="v20-field"><label for="v20-edit-en">今次要默的英文</label><input id="v20-edit-en" value="${esc(c.en)}" maxlength="240" autocomplete="off" autocapitalize="off" spellcheck="false"></div>${sugg.length?`<div class="v20-source-label">可能的拼法（不會自動更改）</div><div class="v20-suggest">${sugg.map(s=>`<button data-imp="suggest" data-value="${esc(s)}" lang="en">${esc(s)}</button>`).join('')}</div>`:''}<div class="v20-field"><label for="v20-edit-zh">今次的中文意思</label><input id="v20-edit-zh" maxlength="300" value="${esc(c.zh)}" placeholder="原稿未有中文，可以先留空"></div>${c.choices.length>1?`<div class="v20-suggest">${c.choices.map(s=>`<button data-imp="meaning" data-value="${esc(s)}">${esc(s)}</button>`).join('')}</div>`:''}<p class="small muted">保留原稿的單複數、時態及大小寫；詞庫未收錄的字也可以加入。</p><label class="v20-check"><input id="v20-item-checked" type="checkbox" ${c.reviewed?'checked':''}>我已核對這項英文及今次要教的意思</label><div id="v20-edit-error" role="alert"></div>`;
 const d=v20Dialog('核對字詞',body,`${/\s/.test(c.en)&&c.kind!=='sentence'?`<button class="btn secondary" data-imp="split" data-id="${esc(c.id)}">拆成單字</button>`:''}<button class="btn primary" data-imp="save-edit" data-id="${esc(c.id)}">保留修改</button>`,'v20-edit-dialog');v20FillSnippet(c);d.addEventListener('input',e=>{if(['v20-edit-en','v20-edit-zh'].includes(e.target.id))$('#v20-item-checked').checked=false;});}
function v20SaveEdit(id){const c=v20.items.find(x=>x.id===id);if(!c)return;const en=V20.exact($('#v20-edit-en').value),zh=$('#v20-edit-zh').value.trim(),checked=$('#v20-item-checked').checked;if(!validEnglish(en)||zh.length>300){$('#v20-edit-error').innerHTML='<p class="v20-error">請只輸入英文字母、撇號和連字號。每項最多 240 個字元。</p>';return;}v20History();v20Touch();Object.assign(c,{en,zh,kind:c.kind==='sentence'?'sentence':kindOf(en),reviewed:checked,selected:true,edited:true});v20Recheck(c);if(!checked&&!c.reviewReasons.length)c.reviewReasons=['修改後請核對'];$('#v20-edit-dialog').close();v20.message=checked?'這項已核對。':'修改已保留，確認前請再核對。';v20RenderWords();if($('#v20-summary'))v20RenderSummary();}
function v20Add(){v20Dialog('自己加入字詞',`<div class="v20-field"><label for="v20-add-en">英文</label><input id="v20-add-en" maxlength="240" autocomplete="off" spellcheck="false"></div><div class="v20-field"><label for="v20-add-zh">中文意思（可不填）</label><input id="v20-add-zh" maxlength="300"></div><p class="small muted">原相漏了字，可以在這裏補回；也可以重新框選該部分。</p><p id="v20-add-error" role="alert"></p>`, '<button class="btn primary" data-imp="save-add">加入並選取</button>','v20-add-dialog');}
function v20SaveAdd(){const en=V20.exact($('#v20-add-en').value),zh=$('#v20-add-zh').value.trim();if(!validEnglish(en)){ $('#v20-add-error').textContent='請輸入可用英文；單字、詞組或句子都可以。';return;}v20History();v20Touch();const doc=V20.fromText(en,uid('manual'));const c=V20.candidates(V20.fromText(en+' | '+zh,doc.id),{mode:'list',dictionary:v20Dictionary,common:v20.common})[0];Object.assign(c,{en,zh,originalText:en,sourceText:en,reviewReasons:[],reviewed:true,selected:true,kind:kindOf(en),excludedReason:''});v20.documents.push(doc);v20.items.push(c);$('#v20-add-dialog').close();v20RenderWords();}
function v20Summary(){if(v20.rawDirty){toast('請先整理剛修改的原文。','bad');return;}if(!v20Selected().length)return;v20Dialog('3. 核對及加入','<div id="v20-summary-content"></div>','<button class="btn secondary" data-imp="close-dialog">繼續選字</button><button class="btn primary" data-act="save-range" id="v20-save-range">確認加入</button>','v20-summary');v20RenderSummary();}
function v20RenderSummary(){const box=$('#v20-summary-content');if(!box)return;const rows=v20Selected(),pend=v20Pending(),dup=rows.length-new Set(rows.map(c=>c.en+'\u0000'+c.zh)).size;const blocked=pend.length||rows.length>120||!rows.length||dup>0||v20.rawDirty;
 box.innerHTML=`<p><strong>${esc(importDraft.title||'英文默書')}</strong> · ${rows.length} 項</p>${blocked?`<p class="v20-review-notice">${rows.length>120?'每份最多 120 項，請取消部分選取。':pend.length?`尚有 ${pend.length} 項需逐項核對或略過。`:dup?'有完全相同的項目，請先返回選字頁合併。':'請先選取字詞。'}</p>`:'<p class="small muted">最後請對照原稿。認不出的字，可以返回補上。</p>'}<ul class="v20-summary-list">${rows.map(c=>`<li><span><strong lang="en">${esc(c.en)}</strong><small>${esc(c.zh||'未填中文')} · ${V20.pending(c)?'待核對':'可加入'}</small></span><button data-imp="edit" data-id="${esc(c.id)}">${V20.pending(c)?'核對':'修改'}</button><button data-imp="summary-remove" data-id="${esc(c.id)}" aria-label="略過 ${esc(c.en)}">略過</button></li>`).join('')}</ul><label class="v20-check v20-summary-check"><input type="checkbox" id="confirm-import" ${blocked?'disabled':''}>我已對照原稿，確認這些是今次默書範圍</label><p class="small muted">只會加入上面的項目。不會儲存整張相片和沒選的內容。姓名和班別預設不選。</p><div id="v20-save-error" role="alert"></div>`;
 const b=$('#v20-save-range');if(b)b.disabled=!!blocked||!$('#confirm-import').checked;}
function v20ValidateEvidence(p){if(!p||typeof p!=='object'||Array.isArray(p))throw Error('import evidence');const text=(v,max)=>{if(typeof v!=='string'||v.length>max||/[\u0000-\u0008\u000b\u000c]/.test(v))throw Error('import text');return v;};if(!['list','passage','sentences','manual'].includes(p.mode)||!Array.isArray(p.sources)||p.sources.length>10)throw Error('import source');return {version:1,mode:p.mode,checked:p.checked===true,sources:p.sources.map(s=>({original:text(s.original,240),context:text(s.context,500),region:text(s.region,100),boxes:(Array.isArray(s.boxes)?s.boxes:[]).slice(0,60).map(b=>{const z=window.WQImportCore.box(b);if(!z||Object.values(z).some(x=>x<0||x>50000))throw Error('import box');return z;})}))};}
saveRange=function(){if(v20.saving)return;captureImportDraft();const selected=v20Selected();const dup=selected.length-new Set(selected.map(c=>c.en+'\u0000'+c.zh)).size;if(!selected.length||selected.length>120||v20Pending().length||v20.rawDirty||dup||!$('#confirm-import')?.checked){v20RenderSummary();toast('請先核對已選項目，並勾選確認。','bad');return;}const bad=selected.find(c=>!validEnglish(c.en)||c.zh.length>300);if(bad){toast('「'+bad.en+'」格式需要修改。','bad');return;}const c=activeChild();if(!c||v20Origin&&v20Origin!==v20Owner()){toast('孩子或帳戶已切換，請重新確認匯入。','bad');return;}const title=importDraft.title.trim()||'英文默書';if(title.length>120){toast('名稱請用 120 字以內。','bad');return;}const before=structuredClone(db);v20.saving=true;
 try{const r={id:uid('r'),childId:c.id,title,dictationDate:importDraft.date,createdAt:new Date().toISOString()};db.ranges.push(r);for(const x of selected){const meta=V20.gloss(x.en,v20Dictionary),sources=[{original:x.originalText.slice(0,240),context:x.sourceText.slice(0,500),region:x.sourceRegionId,boxes:x.sourceBoxes},...(x.moreSources||[]).map(s=>({original:s.text.slice(0,240),context:s.sourceText.slice(0,500),region:s.regionId,boxes:s.boxes}))].slice(0,10);db.words.push({id:uid('w'),childId:c.id,rangeId:r.id,en:x.en,zh:x.zh,kind:x.kind,example:meta.choices.length===1&&meta.zh===x.zh?meta.example:'',emoji:'',createdAt:new Date().toISOString(),studySeen:0,reviewLevel:0,reviewDue:null,lastSeen:null,importEvidence:v20ValidateEvidence({mode:v20.mode,checked:true,sources})});}c.activeRangeId=r.id;db.session=null;if(!save()){db=before;$('#v20-save-error').innerHTML='<p class="v20-error">儲存失敗。選好的字詞和草稿還在。請先備份，再重試。</p>';return;}const wasLogged=isLoggedIn();clearImportDraft();mediaSelectedRange=r.id;mediaMessage='已加入你選定的默書內容。請核對圖片及準備讀音。';toast(wasLogged?'已儲存所選範圍。':'已加入試玩範圍；離開後不會儲存。');if(window.WQP40)WQP40.landed(r.id);else go('offline');}
 catch(e){db=before;const el=$('#v20-save-error');if(el)el.innerHTML='<p class="v20-error">加入失敗。原有教材沒有改動，草稿還在。請再試一次。</p>';}
 finally{v20.saving=false;}};
function v20RenderOriginal(){const cv=v20Photo?.original;if(!cv)return;const d=v20Dialog('原相','<img alt="原相" id="v20-original-image" style="width:100%;height:auto"><p class="small muted">查看有沒有漏辨認的區域；可返回「框選／拉直」再辨認。</p>','','v20-original');d.querySelector('img').src=v20Photo.originalURL;}
function v20DrawWorking(){const p=v20Photo;if(!p)return;const a=(p.turn+p.angle)*Math.PI/180,w=p.original.width,h=p.original.height;const cw=Math.ceil(Math.abs(w*Math.cos(a))+Math.abs(h*Math.sin(a))),ch=Math.ceil(Math.abs(h*Math.cos(a))+Math.abs(w*Math.sin(a)));const cv=document.createElement('canvas');cv.width=cw;cv.height=ch;const ctx=cv.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,cw,ch);ctx.translate(cw/2,ch/2);ctx.rotate(a);ctx.drawImage(p.original,-w/2,-h/2);p.working=cv;if(p.workingURL)URL.revokeObjectURL(p.workingURL);p.workingURL=cv.toDataURL('image/png');}
setOcrFile=async function(file,source='upload'){if(!file)return;if(file.size>20*1024*1024){toast('相片超過 20 MB，請縮小後再上傳。','bad');return;}if(!/^image\//i.test(file.type)||/svg/i.test(file.type)){toast('請用 JPG 或 PNG 相片。','bad');return;}cancelOCR();const epoch=++v20PhotoEpoch;v20FileLoading=true;const url=URL.createObjectURL(file);const im=new Image();try{await new Promise((resolve,reject)=>{im.onload=resolve;im.onerror=reject;im.src=url;});if(epoch!==v20PhotoEpoch)return;if(im.naturalWidth*im.naturalHeight>40000000)throw Error('圖片像素太大，請先縮小。');const scale=Math.min(1,2800/Math.max(im.naturalWidth,im.naturalHeight));const cv=document.createElement('canvas');cv.width=Math.round(im.naturalWidth*scale);cv.height=Math.round(im.naturalHeight*scale);const ctx=cv.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,cv.width,cv.height);ctx.drawImage(im,0,0,cv.width,cv.height);if(v20Photo?.originalURL)URL.revokeObjectURL(v20Photo.originalURL);v20Photo={id:uid('photo'),original:cv,originalURL:url,working:cv,workingURL:'',turn:0,angle:0,crop:{left:0,top:0,right:1,bottom:1},width:cv.width,height:cv.height};v20DrawWorking();if(ocrPreviewUrl)URL.revokeObjectURL(ocrPreviewUrl);ocrPreviewUrl=v20Photo.workingURL;ocrSelectedFile=file;importDraft.source=source;importDraft.fileName=file.name;v20.message=v20.items.length?'新相片已準備好。新辨認結果只會加在後面，不會蓋掉你已改的字。':'可先框選要默的部分，再辨認。';v20Origin=v20Owner();updateImportPhoto();}
 catch(e){URL.revokeObjectURL(url);if(epoch===v20PhotoEpoch)toast('相片讀不到或太大。請改用 JPG／PNG，或直接貼上文字。','bad');}
 finally{if(epoch!==v20PhotoEpoch){URL.revokeObjectURL(url);return;}v20FileLoading=false;updateImportPhoto();v20RenderWords();}};
updateImportPhoto=function(){const im=$('#ocr-preview'),name=$('#ocr-file-name'),run=$('#run-ocr');if(im){im.hidden=!v20Photo;if(v20Photo)im.src=v20Photo.workingURL;}if(name)name.textContent=importDraft.fileName?(importDraft.source==='camera'?'已拍攝：':'已選擇：')+importDraft.fileName:'未選擇圖片';if(run)run.disabled=!v20Photo||ocrBusy||v20FileLoading;const tools=$('#v20-photo-tools');if(tools)tools.hidden=!v20Photo;const cancel=$('#v20-cancel-ocr');if(cancel)cancel.hidden=!ocrBusy;};
function v20Crop(){if(!v20Photo)return;v20Origin=v20Owner();const p=v20Photo;const body=`<p class="small muted">先點左上角，再點右下角。只辨認橙框內；左右兩欄可分兩次加入。</p><div class="v20-crop-stage" id="v20-crop-stage"><canvas id="v20-crop-canvas"></canvas><div class="v20-crop-frame" id="v20-crop-frame"></div></div><div id="v20-crop-status" class="v20-inline-status" role="status">先點範圍的左上角。</div><div class="v20-crop-values">${[['left','左'],['top','上'],['right','右'],['bottom','下']].map(([k,t])=>`<label>${t}邊界 %<input type="number" min="0" max="100" step="1" data-crop-edge="${k}" value="${Math.round(p.crop[k]*100)}"></label>`).join('')}</div><div class="v20-toolbar"><button class="btn secondary" data-imp="rotate" data-value="-90">左轉 90°</button><button class="btn secondary" data-imp="rotate" data-value="90">右轉 90°</button><button class="btn quiet" data-imp="crop-reset">用整張相</button></div><label class="v20-rotation">微調傾斜<input id="v20-angle" type="range" min="-10" max="10" step="0.5" value="${p.angle}"><output id="v20-angle-value">${p.angle}°</output></label><p class="small muted">相片歪得很厲害或有反光，請把紙平放再拍。這裏只能框選和旋轉，補不回看不見的字。</p>`;v20Dialog('框選／拉直相片',body,'<button class="btn primary" data-imp="crop-done">用這個範圍</button>','v20-crop');v20CropPaint();let first=null;$('#v20-crop-stage').addEventListener('pointerup',e=>{if(e.button!==0&&e.pointerType==='mouse')return;const el=$('#v20-crop-canvas'),r=el.getBoundingClientRect(),x=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));if(!first){first={x,y};$('#v20-crop-status').textContent='再點右下角。';}else{const left=Math.min(first.x,x),top=Math.min(first.y,y),right=Math.max(first.x,x),bottom=Math.max(first.y,y);if(right-left<.015||bottom-top<.015){$('#v20-crop-status').textContent='範圍太小，請重新點左上角。';first=null;return;}p.crop={left,top,right,bottom};first=null;v20PhotoEpoch++;cancelOCR();v20CropPaint();$('#v20-crop-status').textContent='已選好。可以再點兩個角重新選取。';}});}
function v20CropPaint(){if(!v20Photo)return;const cv=$('#v20-crop-canvas'),p=v20Photo;if(cv){const h=Math.min(460,window.innerHeight*.4),scale=Math.min(1,420/p.working.width,h/p.working.height);cv.width=Math.round(p.working.width*scale);cv.height=Math.round(p.working.height*scale);$('#v20-crop-stage').style.maxWidth=cv.width+'px';cv.getContext('2d').drawImage(p.working,0,0,cv.width,cv.height);}const f=$('#v20-crop-frame');if(f){const c=p.crop;Object.assign(f.style,{left:c.left*100+'%',top:c.top*100+'%',width:(c.right-c.left)*100+'%',height:(c.bottom-c.top)*100+'%'});$$('[data-crop-edge]').forEach(i=>i.value=Math.round(c[i.dataset.cropEdge]*100));}updateImportPhoto();}
function v20ProcessPhoto(){const p=v20Photo;if(!p)throw Error('未有相片');const c=p.crop;if(c.left>=c.right||c.top>=c.bottom)throw Error('框選範圍不正確，請調整四個邊界。');const x=Math.floor(p.working.width*c.left),y=Math.floor(p.working.height*c.top),w=Math.max(1,Math.floor(p.working.width*(c.right-c.left))),h=Math.max(1,Math.floor(p.working.height*(c.bottom-c.top)));const sc=Math.min(2,Math.max(1,1300/Math.max(w,h))),pad=16;const canvas=document.createElement('canvas');canvas.width=Math.round(w*sc)+2*pad;canvas.height=Math.round(h*sc)+2*pad;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(p.working,x,y,w,h,pad,pad,w*sc,h*sc);if($('#v20-enhance')?.checked){const data=ctx.getImageData(0,0,canvas.width,canvas.height);for(let i=0;i<data.data.length;i+=4){const val=.299*data.data[i]+.587*data.data[i+1]+.114*data.data[i+2],v=Math.max(0,Math.min(255,(val-128)*1.12+128));data.data[i]=data.data[i+1]=data.data[i+2]=v;}ctx.putImageData(data,0,0);}return canvas;}
runOCR=async function(){if(!v20Photo||ocrBusy||v20FileLoading)return;if(v20.rawDirty){toast('你剛修改了原文，請先整理文字再辨認其他範圍。','bad');return;}if(v20.documents.length>=12){toast('已加入多個範圍，請先完成這份教材，再加入下一份。','bad');return;}if(v20.items.length&&!confirm('保留你已選及修改的字詞，將這次辨認加在後面？'))return;captureImportDraft();v20Origin=v20Owner();const owner=v20Owner(),photoId=v20Photo.id,epoch=v20PhotoEpoch,rev=v20.revision,psm=$('#v20-psm')?.value||'3',job=++ocrJob;let image;try{image=v20ProcessPhoto();}catch(e){toast(e.message,'bad');return;}ocrBusy=true;updateOCR('正在準備辨認；未完成前不會更改你的選詞。',4);updateImportPhoto();v20RenderWords();let worker=null,timer=null;const valid=()=>job===ocrJob&&photoId===v20Photo?.id&&epoch===v20PhotoEpoch&&rev===v20.revision&&owner===v20Owner()&&lastRoute==='range-new';
 const timeout=new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('辨認逾時，請縮小範圍後再試。')),90000);});
 try{const result=await Promise.race([(async()=>{await loadTesseract();if(!valid())return null;if(!window.Tesseract?.createWorker)throw Error('辨認功能還沒載入，請稍後再試。');const logger=m=>{if(valid()){const percent=m.status==='recognizing text'?Math.round((m.progress||0)*100):10;updateOCR(m.status==='recognizing text'?`${window.s50PassLabel||'正在辨認'} ${percent}%`:'正在載入辨認資料…',percent);}};worker=await Tesseract.createWorker('eng+chi_tra',1,{...(await window.WQR3OCR.options()),logger,errorHandler:()=>{}});if(!valid()){await worker.terminate();return null;}activeOcrWorker=worker;return await window.s50Recognize(worker,image,psm,valid);})(),timeout]);if(!valid()||!result)return;const doc=V20.fromOCR(result.data,uid('ocr'));const items=V20.candidates(doc,{mode:v20.mode,dictionary:v20Dictionary,common:v20.common});if(v20.items.length+items.length>1500)throw Error('內容太多，請框選較小的範圍。');if(!items.length){if(window.WQP40){WQP40.ocrEmpty();return;}updateOCR('這個範圍未辨認到英文。請看原相，重新框選或手動補字。',0);return;}const blob=await new Promise(resolve=>image.toBlob(resolve,'image/png'));if(!valid())return;if(blob){doc.previewURL=URL.createObjectURL(blob);doc.width=image.width;doc.height=image.height;}doc.engineText=String(result.data.text||'').slice(0,30000);v20History();v20.documents.push(doc);v20.items.push(...items);v20.revision++;v20.parsedRaw=v20.documents.map(d=>d.raw).join('\n\n');importDraft.raw=v20.parsedRaw;$('#raw-words').value=importDraft.raw;v20.rawDirty=false;v20.filter='all';v20.message=doc.warnings.length?doc.warnings.join(' '):'已分成可點選項目。仍請核對錯字及漏字；選取後才會加入教材。';updateOCR(`已辨認 ${items.length} 個候選項目，請對照原稿。`,100);if(window.WQP40)WQP40.ocrDone(doc,items);v20RenderWords();}
 catch(e){if(valid()&&window.WQP40){WQP40.ocrError(e);return;}if(valid())updateOCR(navigator.onLine?(e.message||'暫時未能辨認，請重試或貼上文字。'):'目前沒有網絡，辨認功能或英文資料還沒準備好。仍可貼上文字和選字。',0);}
 finally{clearTimeout(timer);if(worker)try{await worker.terminate();}catch(_){}if(activeOcrWorker===worker)activeOcrWorker=null;if(job===ocrJob){ocrBusy=false;updateImportPhoto();v20RenderWords();}}};
applyOCR=function(payload){const doc=typeof payload==='string'?V20.fromText(payload,uid('ocrtext')):V20.fromOCR(payload,uid('ocr'));v20History();v20Touch();v20.documents.push(doc);v20.items.push(...V20.candidates(doc,{mode:v20.mode,dictionary:v20Dictionary,common:v20.common}));v20.parsedRaw=v20.documents.map(d=>d.raw).join('\n\n');importDraft.raw=v20.parsedRaw;if($('#raw-words'))$('#raw-words').value=importDraft.raw;v20.rawDirty=false;v20RenderWords();};
function v20CommonDialog(){const terms=[...new Set(v20.items.filter(c=>!c.en.includes(' ')&&c.kind!=='sentence').map(c=>V20.fold(c.en)))].sort();v20Dialog('今次哪些字放常用字？','<p class="small muted"></p><div class="v20-common-editor">'+terms.map(t=>`<label><input type="checkbox" data-common="${esc(t)}" ${v20.common.has(t)?'checked':''}>${esc(t)}</label>`).join('')+'</div>','<button class="btn primary" data-imp="save-common">儲存今次分組</button>','v20-common-dialog');}
function v20Click(e){const b=e.target.closest('[data-imp]');if(!b||b.disabled)return;const a=b.dataset.imp,id=b.dataset.id,c=v20.items.find(x=>x.id===id);try{
 if(a==='close-dialog'){b.closest('dialog')?.close();return;}
 if(a==='parse')v20Parse();if(a==='mode')v20ChangeMode(b.dataset.value);if(a==='filter'){v20.filter=b.dataset.value;v20.showLimit=120;v20RenderWords();}if(a==='more'){v20.showLimit+=120;v20RenderWords();}
 if(a==='toggle'&&c){if(v20.mergeMode){if(!v20.mergeStart){v20.mergeStart=c.id;v20RenderWords();return;}const merged=V20.merge(v20.items,v20.mergeStart,c.id,uid('merged'));v20History();v20Touch();v20.items=merged;v20.items.forEach(v20Recheck);v20.mergeMode=false;v20.mergeStart=null;v20RenderWords();return;}v20History();v20Touch();c.selected=!c.selected;if(c.selected&&c.excludedReason){c.reviewReasons=['請確認這不是頁首或個人資料'];c.reviewed=false;}v20RenderWords();}
 if(a==='edit'&&c)v20Edit(id);if(a==='save-edit')v20SaveEdit(id);if(a==='suggest'){$('#v20-edit-en').value=b.dataset.value;const g=V20.gloss(b.dataset.value,v20Dictionary);$('#v20-edit-zh').value=g.zh;$('#v20-item-checked').checked=false;}if(a==='meaning'){$('#v20-edit-zh').value=b.dataset.value;$('#v20-item-checked').checked=false;}
 if(a==='split'&&c){const children=V20.split(c,uid('split')).map(v20Recheck);v20History();v20Touch();const i=v20.items.indexOf(c);v20.items.splice(i,1,...children);$('#v20-edit-dialog').close();v20RenderWords();if($('#v20-summary'))v20RenderSummary();}
 if(a==='merge-mode'){v20.mergeMode=!v20.mergeMode;v20.mergeStart=null;v20RenderWords();}
 if(['select-all','select-none','skip-common','select-common'].includes(a)){v20History();v20Touch();v20.items.forEach(c=>{if(c.excludedReason&&!c.selected)return;if(a==='select-all')c.selected=true;if(a==='select-none')c.selected=false;if(v20.mode==='passage'&&c.common){if(a==='skip-common')c.selected=false;if(a==='select-common')c.selected=true;}});v20.message=a==='skip-common'?'已略過常用字；原文及詞組保持不變。':'';v20RenderWords();}
 if(a==='restore'&&c){v20History();v20Touch();c.selected=true;c.reviewed=false;c.reviewReasons=['請確認這不是頁首或個人資料'];v20RenderWords();v20Edit(c.id);}
 if(a==='summary')v20Summary();if(a==='summary-remove'&&c){v20History();v20Touch();c.selected=false;v20RenderWords();v20RenderSummary();}
 if(a==='dedupe'){v20History();v20Touch();const r=V20.deduplicate(v20.items);v20.items=r.items;v20.message=`已合併 ${r.count} 個完全相同的項目，原來的出現位置仍保留。`;v20RenderWords();}
 if(a==='undo')v20Undo();if(a==='add')v20Add();if(a==='save-add')v20SaveAdd();if(a==='edit-common')v20CommonDialog();if(a==='save-common'){v20History();v20Touch();$$('[data-common]').forEach(i=>i.checked?v20.common.add(i.dataset.common):v20.common.delete(i.dataset.common));v20.items.forEach(c=>c.common=v20.common.has(V20.fold(c.en))&&!/\s/.test(c.en)&&c.kind!=='sentence');$('#v20-common-dialog').close();v20RenderWords();}
 if(a==='crop')v20Crop();if(a==='full-photo')v20RenderOriginal();if(a==='crop-done'){const p=v20Photo;if(!p||p.crop.left>=p.crop.right||p.crop.top>=p.crop.bottom){toast('框選範圍的右邊要在左邊的右方，下邊要在上邊的下方。','bad');return;}$('#v20-crop').close();v20.message='已框選。按「辨認所選範圍」加入候選字詞。';v20RenderWords();}
 if(a==='crop-reset'&&v20Photo){v20Photo.crop={left:0,top:0,right:1,bottom:1};v20PhotoEpoch++;cancelOCR();v20CropPaint();}if(a==='rotate'&&v20Photo){v20Photo.turn=(v20Photo.turn+Number(b.dataset.value)+360)%360;v20Photo.crop={left:0,top:0,right:1,bottom:1};v20PhotoEpoch++;cancelOCR();v20DrawWorking();v20CropPaint();}
 if(a==='cancel-ocr'){cancelOCR();updateOCR('已停止辨認。原有選詞及更正仍然保留。',0);updateImportPhoto();v20RenderWords();}
 }catch(err){toast(err.message||'未完成操作，原有資料仍保留。','bad');}}
document.addEventListener('click',v20Click);
/* Catch original source edits before the legacy listener which cleared every draft row. */
document.addEventListener('input',e=>{if(e.target.id==='raw-words'){e.stopImmediatePropagation();cancelOCR();importDraft.raw=e.target.value;v20.rawDirty=importDraft.raw!==v20.parsedRaw;v20.revision++;importDraft.confirmed=false;v20RenderWords();updateImportPhoto();}if(e.target.matches?.('[data-crop-edge]')&&v20Photo){const v=Number(e.target.value)/100;if(Number.isFinite(v)&&v>=0&&v<=1){v20Photo.crop[e.target.dataset.cropEdge]=v;v20PhotoEpoch++;cancelOCR();const f=$('#v20-crop-frame'),c=v20Photo.crop;if(f)Object.assign(f.style,{left:c.left*100+'%',top:c.top*100+'%',width:Math.max(0,c.right-c.left)*100+'%',height:Math.max(0,c.bottom-c.top)*100+'%'});}}if(e.target.id==='v20-angle'&&v20Photo){v20Photo.angle=Number(e.target.value);v20Photo.crop={left:0,top:0,right:1,bottom:1};v20PhotoEpoch++;cancelOCR();v20DrawWorking();v20CropPaint();$('#v20-angle-value').textContent=v20Photo.angle+'°';}},true);
document.addEventListener('change',e=>{if(e.target.id==='confirm-import'&&$('#v20-summary')){importDraft.confirmed=e.target.checked;$('#v20-save-range').disabled=!e.target.checked||v20Pending().length>0||v20Selected().length>120;}});
const v20PrevRender=render;render=function(){const route=(location.hash||'#kid').slice(1).split('?')[0];if(route!=='range-new')v20CloseAll();v20PrevRender();document.body.classList.toggle('import-selection-active',route==='range-new');if(route==='range-new'&&!v20Origin)v20Origin=v20Owner();};
window.addEventListener('pagehide',()=>cancelOCR());
/* Read-only diagnostic metadata. Tests attach their own state hook before startup. */
window.__WQ_IMPORT_V20__=Object.freeze({version:V20.VERSION,dictionarySize:v20Dictionary.size,sourceFormat:'blocks-lines-words / TSV / text',limits:{items:1500,selected:120,regions:12},draftPolicy:'memory-only',count:()=>({all:v20.items.length,selected:v20Selected().length,review:v20Pending().length})});

const v20OriginalToast=toast;toast=function(message,type='ok'){if(lastRoute!=='range-new'||!$('#import-v20'))return v20OriginalToast(message,type);v20.message=message;const dialog=[...document.querySelectorAll('.v20-dialog[open]')].at(-1);if(dialog){let status=dialog.querySelector('.v20-dialog-notice');if(!status){status=document.createElement('p');status.className='v20-dialog-notice';status.setAttribute('role','status');dialog.querySelector('.v20-dialog-body').prepend(status);}status.className='v20-dialog-notice '+(type==='bad'?'v20-error':'v20-review-notice');status.textContent=message;}else{const status=$('#v20-message');if(status){status.textContent=message;status.setAttribute('role',type==='bad'?'alert':'status');}}};



/* V21 test admin integration. It is intentionally not a protected staff portal.
   Role is derived from the reserved session ID, never a user-supplied backup role/name. */
async function loginTestAdmin(){
 if(!WQ_TEST_MODE){toast('標準版沒有管理員功能。','bad');return;}
 if(authBusy)return;const pin=$('#login-pin')?.value||'';if(!(WQ_LOCAL_TEST_ALLOWED?/^\d{4}$/:/^.{10,128}$/).test(pin)){toast('帳戶名稱或密碼不對，請再試一次。','bad');return;}
 authBusy=true;let previous='';let wroteSession=false;
 try{
  const hash=await pinHash(pin,WQ_LOCAL_TEST_ALLOWED?TEST_ADMIN.salt:R37_ADMIN.salt),expected=!globalThis.crypto?.subtle?(WQ_LOCAL_TEST_ALLOWED?TEST_ADMIN.legacyHash:''):WQ_LOCAL_TEST_ALLOWED?TEST_ADMIN.hash:R37_ADMIN.hash;
  if(hash!==expected){toast('帳戶名稱或 PIN 不對，請再試一次。','bad');return;}
  previous=sessionStorage.getItem(SESSIONKEY)||'';
  // Verify both storage mechanisms before switching accounts. Do not overwrite existing data.
  const probe='wordquest-v21-storage-probe';localStorage.setItem(probe,'1');localStorage.removeItem(probe);
  sessionStorage.setItem(SESSIONKEY,TEST_ADMIN.id);wroteSession=true;
  stopSpeech();pcStop();fgStopAudio();clearImportDraft();loadBlocked=false;persistenceIssue='';
  db=load();if(!await arAcquire())throw Error('另一分頁正在編輯。');if(!loadBlocked&&!save())throw Error('storage');
  toast('已登入測試帳戶。');go('admin');render();
 }catch(e){
  if(wroteSession){try{if(previous)sessionStorage.setItem(SESSIONKEY,previous);else sessionStorage.removeItem(SESSIONKEY);}catch(_){}loadBlocked=false;db=load();}
  toast('不能登入測試帳戶。請允許這個網站使用瀏覽器的儲存功能。','bad');
 }finally{authBusy=false;}
}
function adminButton(text,action,extra='',cls='secondary'){return `<button type="button" class="btn ${cls}" data-admin="${action}" ${extra}>${esc(text)}</button>`;}
function adminView(){
 if(!isTestAdmin())return `<section class="card pad"><h1>管理員測試</h1><p>請先用管理員測試帳戶登入。</p>${link('前往登入','login','primary')}</section>`;
 return `<section class="admin-dashboard"><div class="row between"><div><p class="eyebrow">學霸星球 · 測試專用</p><h1>測試中心</h1></div>${link('返回孩子首頁','kid','secondary')}</div>
 <div class="notice"><strong>只管理這個瀏覽器的測試資料。</strong>請用暱稱，默書紙也要先去掉個人資料。</div>
 <section class="card pad admin-mode"><div><h2>${adminUnlocks()?'全部開放':'按一般規則測試'}</h2><p>${adminUnlocks()?'十二課可直接做小測，六款遊戲及三種難度可免費測試。':'課後小測要先學完才可做。遊戲照常扣測試帳戶的金幣。切回「全部開放」，成績不變。'}</p></div>${adminButton(adminUnlocks()?'改用一般規則':'開放全部功能','toggle','','primary')}</section>
 <div class="admin-cards"><section class="card pad"><h2>教材及學習</h2><div class="admin-links">${link('拍照／上傳及點選字詞','range-new')}${link('全部默書範圍','ranges')}${link('所有題型','practice')}${link('air 拼字家族','spelling-family')}${link('離線圖片及讀音','offline')}${link('孩子資料','children')}${link('默書報告','report')}${link('聲效、設定及備份','settings')}</div></section>
 <section class="card pad"><h2>遊戲測試</h2><p class="small muted">先選難度，再選遊戲；切換遊戲會結束上一張測試票。仍保留 1–3 分鐘時限。</p><label for="admin-level">挑戰程度</label><select id="admin-level">${['入門','標準','挑戰'].map((n,i)=>`<option value="${i}" ${arcPrefs().level===i?'selected':''}>${n}</option>`).join('')}</select><div class="admin-links">${Object.values(ARC.spec).filter(g=>g.id!=='shooter').map(g=>adminButton(g.name,'game',`data-game="${g.id}"`)).join('')}</div>${link('到遊戲街機看玩法','game','soft')}</section></div>
 <section class="card pad admin-courses"><h2>拼字專家 · 十二課</h2><p class="small muted">已聽讀音、跟讀和答題結果按實際操作記錄，不會因管理員權限而自動填滿。</p><div class="admin-lessons">${PC.lessons.map(l=>`<article><strong>${l.number} · ${esc(l.pattern)}</strong><span>${esc(l.title)}</span><div>${pcBtn('看教學','learn',`data-lesson="${l.id}"`,'secondary')}${pcBtn('課後小測','quiz',`data-lesson="${l.id}" ${pcReadyToTest(l.id)?'':'disabled'}`,'primary')}</div></article>`).join('')}</div></section>
 <details class="card pad admin-reset"><summary>重新開始測試</summary><p>重設只會清除測試帳戶的教材文字、成績、金幣和遊戲票，不會清除其他本機帳戶。自備的圖片和音檔，請在「離線教材」管理。</p>${adminButton('重設測試資料','reset','','danger')}${link('先匯出備份','settings','secondary')}</details></section>`;
}
const adminPriorLoginView=loginView;loginView=function(){return adminPriorLoginView()+(!isLoggedIn()?'<p class="small muted admin-login-note">本機家庭試用：可自建帳戶；不要使用真名或其他網站的密碼。</p>':'');};
const adminPriorRender=render;
render=function(){
 adminPriorRender();
 document.body.classList.toggle('admin-test-session',isTestAdmin());
 const brand=$('.brand');if(brand){brand.href=isTestAdmin()?'#admin':'#kid';brand.title=isTestAdmin()?'測試中心':'學霸星球 首頁';const name=brand.querySelector('span:last-child');if(name)name.textContent=isTestAdmin()?'Admin':'學霸星球';}
 if(lastRoute==='admin'){$('#app').innerHTML=adminView();document.body.classList.remove('quiz-active','arcade-active','phonics-active','family-active','import-selection-active');}
 if(isTestAdmin()&&['kid','parent','game','phonics','report'].includes(lastRoute)){
  const b=document.createElement('p');b.className='notice admin-state';b.textContent=adminUnlocks()?'測試模式：所有功能已開放，遊戲免費。':'測試模式（一般規則）：照正常學習和扣金幣的方式測試。';$('#app').prepend(b);
 }
 const f=document.querySelector('.footer');if(f)f.firstChild && (f.firstChild.nodeType===3) && (f.firstChild.textContent='WordQuest · 帳戶、金幣和紀錄只存在這個瀏覽器，不會上載到雲端。請不要輸入個人敏感資料。');
 updateViewport();
};
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-admin]');if(!b||b.disabled)return;if(!isTestAdmin()){go('login');return;}
 if(b.dataset.admin==='toggle'){
  arPause();arEngine=null;
  // A free test ticket must never be usable after switching to normal rules.
  if(adminUnlocks()){const t=arcTicket();if(t?.testOnly&&t.status==='open'){const old=structuredClone(db);t.status='finished';t.remainingMs=0;if(!save()){db=old;return;}}}
  try{sessionStorage.setItem('wordquest-v29-admin-rules',adminUnlocks()?'normal':'unlocked');}catch(_){toast('測試方式沒有改到。請再試一次。','bad');return;}
  render();
 }
 if(b.dataset.admin==='game'){
  const level=Number($('#admin-level')?.value);if([0,1,2].includes(level)){const old=arcPrefs().level;arcPrefs().level=level;if(!save()){arcPrefs().level=old;return;}}
  arIntro(b.dataset.game);
 }
 if(b.dataset.admin==='reset'){arPause();resetAll();if(lastRoute==='parent')go('admin');}
});
// Enter in PIN inputs submits the intended form, never creates an account implicitly.
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.isComposing&&!e.repeat&&e.target.id==='login-pin'){e.preventDefault();loginAccount();}});
if(WQ_TEST_MODE)window.__WQ_ADMIN_INFO__=Object.freeze({version:21,localTestOnly:true,active:()=>isTestAdmin(),unlocked:()=>adminUnlocks()});

/* Appended INSIDE the existing WordQuest app closure. V21 remains the host. */
const PG=window.WQRewards;
let pgGame=null,pgMeta=null,pgPlaying=false,pgBusy=false,pgFrame=0,pgLast=0,pgAcc=0,pgReason='ready',pgOwner='',pgTools=[],pgHint='',pgResult=null,pgFree=false,pgSlot='',pgError='',pgFilter='已開放';
const pgThumbCache=new Map();
function pgRoot(){return db.playgroundV22||(db.playgroundV22=PG.initial('legacy'));}
function pgChild(){return PG.get(pgRoot(),activeChild().id);}
function pgDay(){return today();}
function pgTime(ms){return arFmt(Math.max(0,ms));}
function pgAllow(id){return isLoggedIn()&&PG.allowed(pgChild(),id,adminUnlocks());}
function pgButton(label,action,extra='',style='secondary'){return `<button type="button" class="btn ${style}" data-pg="${action}" ${extra}>${label}</button>`;}
function pgInfo(){const c=pgChild(),n=PG.count(c),next=[5,15,30,50].find(v=>n<v);return{c,n,next};}
function pgLegacy(){return Object.values(ARC.spec).filter(g=>g.id!=='shooter');}
function pgLobby(){const {c,n,next}=pgInfo(),t=c.ticket,open=PG.catalog.filter(g=>pgAllow(g.id)).length;
return `<section class="pg-lobby"><div class="pg-hero"><div><p class="eyebrow">學霸星球 · 學一小段，玩一會</p><h1>你的遊戲街機</h1><p>用金幣換時間。重玩或換遊戲，都不會再扣金幣。</p><div class="row"><span class="chip">已通過複習 <b>${n}</b> 個學習項目</span><span class="chip">${open} / 20 款已開放</span></div></div><div class="pg-wallet"><span>可用金幣</span><strong>★ ${isLoggedIn()?activeChild().stars:0}</strong><small>${adminUnlocks()?'測試模式：免費，不影響正常存檔':'5 金幣 / 90 秒 · 10 金幣 / 3 分鐘'}</small></div></div>
${!isLoggedIn()?`<div class="notice">訪客可以先學習。登入本機帳戶後，才會儲存金幣和遊戲進度。${link('登入／建立帳戶','login','primary')}</div>`:''}
${t?.remainingMs>0?`<section class="pg-resume card pad"><div><h2>還有 ${pgTime(t.remainingMs)} 可以玩</h2><p class="muted">這是用金幣換好的時間。重開或換遊戲，都不用再付金幣。</p></div><div class="row">${pgButton('繼續遊戲','intro',`data-id="${t.last}"`,'primary')}${t.usedMs===0&&!t.refunded&&t.cost>0?pgButton('取消未用時段 · 退回 '+t.cost+' 枚金幣','refund',`data-receipt="${esc(t.id)}"`,'quiet'):''}</div></section>`:''}
<div class="pg-progress card pad"><div><strong>${next?`再通過 ${Math.max(0,next-n)} 個複習，下一組遊戲就開放。`:'20 款遊戲的字數門檻全部達成'}</strong><p class="small muted">自己拼對後，隔至少 24 小時再拼對，才會計入。看過答案後馬上答對，不計。用金幣不會減少字數。</p></div><div class="bar"><span style="width:${Math.min(100,n/50*100)}%"></span></div><span class="small">今日已玩 ${pgTime(PG.day(c,pgDay()).usedMs)} ／ ${c.limit} 分鐘（包括原有遊戲）</span></div>
<div class="pg-tabs" role="group" aria-label="遊戲分類">${['全部','已開放','動作','運動','解謎','策略','創作'].map(f=>pgButton(f,'filter',`data-filter="${f}" aria-pressed="${pgFilter===f}"`,pgFilter===f?'primary':'soft')).join('')}</div><div class="pg-grid">${PG.catalog.filter(p=>{const g=WQGames.find(g=>g.id===p.id);return pgFilter==='全部'||pgFilter==='已開放'&&(pgAllow(p.id)||!isLoggedIn()&&p.words===0)||g.category===pgFilter;}).map(p=>{const g=WQGames.find(g=>g.id===p.id),yes=pgAllow(p.id);return `<article class="pg-card ${yes?'':'pg-locked'}"><div class="pg-art" data-pgthumb="${g.id}" aria-hidden="true"></div><div class="pg-cardbody"><div class="eyebrow">${g.tag} · ${g.category}</div><h2>${g.name}</h2><p>${g.desc}</p><div class="pg-cardfoot"><span>${yes?adminUnlocks()?'測試免費':`${p.cost} 金幣 / ${p.seconds===90?'90 秒':'3 分鐘'}`:c.override[g.id]==='blocked'?'家長暫停開放':`${p.words} 個學習項目解鎖`}</span>${pgButton(yes?'看看玩法':'了解解鎖','intro',`data-id="${g.id}"`,yes?'primary':'soft')}</div></div></article>`;}).join('')}</div>
<details class="card pad pg-legacy"><summary><strong>原有 5 款非暴力遊戲</strong> · 舊設定與紀錄保留</summary><p class="small muted">金幣價錢和每次 ${db.settings.gameMinutes} 分鐘都不變。每日遊戲上限，新舊遊戲一起計。原有的遊戲票可以繼續用。</p><div class="row">${pgLegacy().map(g=>arButton(g.name,'intro',`data-game="${g.id}"`,'soft')).join('')}</div>${arcTicket()?.status==='open'&&arcTicket()?.game!=='shooter'?arButton('繼續原有遊戲票','resume','','primary'):''}${arcTicket()?.status==='open'&&arcTicket()?.game==='shooter'?`<div class="notice">射擊遊戲已停用，舊紀錄保留。沒用完的時間，可以免費轉到新遊戲。${pgButton('轉移未用時間','transfer')}</div>`:''}</details><p class="small muted">只存在這部裝置，不會上載到雲端。${link('家長遊戲設定','game-settings','quiet')} ${link('返回學習','kid','quiet')}</p></section>`;}
function pgSettingsView(){if(!isLoggedIn())return loginView();const c=pgChild(),n=PG.count(c),d=PG.day(c,pgDay());return `${navTabs('settings')}<section class="card pad"><p class="eyebrow">${esc(activeChild().name)} · 家長設定</p><h1>金幣與遊戲</h1><div class="notice"></div><div class="grid2"><div class="field"><label for="pg-limit">每日遊戲上限（新舊合計）</label><select id="pg-limit">${[0,3,6,9,15,30,60].map(v=>`<option value="${v}" ${c.limit===v?'selected':''}>${v===0?'暫停遊戲':v+' 分鐘'}</option>`).join('')}</select></div><div class="field"><label for="pg-mode">主站練習的金幣獎勵方式（這個帳戶）</label><select id="pg-mode"><option value="legacy" ${pgRoot().mode==='legacy'?'selected':''}>保留原有：原本答題及完成獎勵</option><option value="balanced" ${pgRoot().mode==='balanced'?'selected':''}>平衡版：不看提示答對得 1 金幣，完成訂正得 5 金幣</option></select></div></div><p class="small muted">平衡版：主站練習每日最多 30 金幣。同一個字、同一種題型，一天只計一次。拼字家族和 12 堂拼音課照原有獎勵，不計入這 30 金幣。舊餘額不變。新遊戲價錢固定：5 金幣 = 90 秒，10 金幣 = 3 分鐘。</p><div class="field"><label for="pg-difficulty">新遊戲挑戰程度</label><select id="pg-difficulty">${['入門','標準','挑戰'].map((v,i)=>`<option value="${i}" ${c.difficulty===i?'selected':''}>${v}</option>`).join('')}</select></div><details style="margin:20px 0"><summary><strong>逐款遊戲權限</strong></summary><p>提前開放只會開放遊戲，不會增加「通過複習」的字數。已通過的複習會保留。</p><div class="pg-permissions">${PG.catalog.map(g=>`<label>${WQGames.find(m=>m.id===g.id).name}<select data-pgpermission="${g.id}"><option value="auto" ${!c.override[g.id]?'selected':''}>按字數（${g.words} 字）</option><option value="open" ${c.override[g.id]==='open'?'selected':''}>提前開放</option><option value="blocked" ${c.override[g.id]==='blocked'?'selected':''}>暫停開放</option></select></label>`).join('')}</div></details>${pgButton('儲存遊戲設定','save-settings','','primary')} ${link('返回遊戲','game','soft')}<hr><h2>紀錄</h2><p>可用 ${activeChild().stars} 金幣 · 通過複習 ${n} 字 · 今日主站平衡獎勵 ${d.earned} 金幣</p><details><summary>查看通過複習的字</summary><p>${Object.entries(c.evidence).filter(([,e])=>e.qualifiedAt>0).map(([w])=>esc(w)).join('、')||'未有新的複習紀錄。舊成績沒有刪除，但不會算作已通過複習。'}</p></details><details><summary>最近 10 筆換領紀錄</summary><ul class="list">${c.sessions.slice(-10).reverse().map(r=>`<li><span>${esc(r.date)} · ${r.durationMs/1000} 秒</span><strong>${r.refunded?'已退回':`−${r.cost} 金幣`}</strong></li>`).join('')||'<li>未有換領紀錄。</li>'}</ul></details><p class="small muted">遊戲進度、時間和解鎖，會跟着原有的「設定／備份」一起匯出。圖片和英式音檔，仍用原有的教材包。</p></section>`;}
function pgPlayView(){if(!pgGame||pgOwner!==accountId()+':'+activeChild().id)return `<section class="card pad"><h1>繼續你的小休息</h1><p>到遊戲街機選遊戲，就能讀取金幣和存檔。</p>${link('前往遊戲街機','game','primary')}</section>`;return `<section class="pg-play"><div class="pg-playhead"><div><p class="eyebrow">${pgFree?'測試模式':'遊戲街機'}</p><h1>${pgMeta.name}</h1></div><strong id="pg-clock" role="timer">${pgFree?'測試不限時':pgTime(pgChild().ticket?.remainingMs||0)}</strong></div><div class="pg-viewport"><canvas id="pg-canvas" width="800" height="560" tabindex="0" aria-label="${pgMeta.name}遊戲畫面"></canvas><div id="pg-overlay" class="pg-overlay"></div></div><div class="pg-controls">${pgMeta.keys.map(([k,l])=>`<button class="btn soft pg-key" data-pgkey="${k}" aria-label="${esc(l)}">${l}</button>`).join('')}</div><div id="pg-tools" class="pg-tools"></div><p id="pg-hint" class="small muted"></p><div class="row">${pgButton('暫停','pause','','secondary')}${pgButton('儲存並返回遊戲街機','leave','','soft')}${pgButton('操作說明','help','','quiet')}<span id="pg-score" class="chip"></span></div><div id="pg-status" class="sr-only" aria-live="polite"></div></section>`;}
function pgThumbs(){for(const box of $$('[data-pgthumb]')){const id=box.dataset.pgthumb;if(!pgThumbCache.has(id)){const cv=document.createElement('canvas');cv.width=800;cv.height=560;const meta=WQGames.find(g=>g.id===id);try{const game=new meta.Class({ctx:cv.getContext('2d'),meta,difficulty:1,seed:72,preview:true,tools(){},hint(){},announce(){},tone(){},complete(){},clock(){return 0},instrument(){},getData(){return null},putData(){}});game.draw();pgThumbCache.set(id,cv.toDataURL('image/webp',.76));}catch(e){console.error('thumbnail',id,e);}}const src=pgThumbCache.get(id);if(src){const im=document.createElement('img');im.src=src;im.alt='';im.loading='eager';im.width=800;im.height=560;box.append(im);}}}
function pgIntro(id){pgPause();const g=WQGames.find(g=>g.id===id),p=PG.catalog.find(g=>g.id===id);if(!g)return;$('#pg-dialog')?.remove();const d=document.createElement('dialog');d.id='pg-dialog';d.className='pg-dialog';const c=pgChild(),t=c.ticket,yes=pgAllow(id),left=PG.remainingDaily(c,pgDay());d.innerHTML=`<div class="pad"><div class="row between"><h2>${g.name}</h2>${pgButton('關閉','close-dialog','','quiet')}</div><p>${esc(g.guide)}</p>${yes?`<p class="small muted">挑戰程度：${['入門','標準','挑戰'][c.difficulty]} · 遊戲分數不會換成金幣。</p>${adminUnlocks()?pgButton('免費開始測試','buy',`data-id="${id}" data-plan="short"`,'primary full'):t?.remainingMs>0?`${pgButton('使用餘下 '+pgTime(t.remainingMs)+' · 不扣金幣','buy',`data-id="${id}" data-plan="short" ${left>0?'':'disabled'}`,'primary full')}`:`<div class="pg-plans">${['short','standard'].map(plan=>{const q=PG.plans[plan],can=activeChild().stars>=q.cost&&left>=q.ms;return pgButton(`${q.cost} 金幣 · ${q.ms/1000} 秒`,'buy',`data-id="${id}" data-plan="${plan}" ${can?'':'disabled'}`,p.cost===q.cost?'primary':'secondary');}).join('')}</div>`}<p>今天還剩 ${pgTime(left)}。按「確認」只扣一次，然後自己按「開始」。時間內可以重玩，也可以換遊戲。</p>`:`<div class="notice">${!isLoggedIn()?'先登入本機帳戶。':c.override[id]==='blocked'?'家長已暫停這款遊戲。':`通過 ${p.words} 個學習項目的複習，這款遊戲就永久開放。現在有 ${PG.count(c)} 個。`}</div>${link('返回學習','kid','primary')}`}<p class="small muted">用金幣不會失去解鎖和存檔。看玩法不扣金幣。</p></div>`;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();}
function pgApi(meta,ctx,preview=false){return{ctx,meta,difficulty:pgChild().difficulty,seed:Math.floor(Math.random()*0xffffffff),preview,latency:0,
 tools(items){pgTools=items;pgRenderTools();},hint(t){pgHint=t;if($('#pg-hint'))$('#pg-hint').textContent=t;},announce(t){if($('#pg-status'))$('#pg-status').textContent=t;},tone:(...a)=>pgAudio.tone(...a),clock:()=>pgAudio.clock(),instrument:(...a)=>pgAudio.instrument(...a),
 complete(r){pgResult=r;pgPlaying=false;pgReason='round';pgAudio.pause();pgCheckpoint();pgOverlay();},getData:k=>pgFree?null:pgChild().extras[k],putData(k,v){if(pgFree)return false;pgChild().extras[k]=JSON.parse(JSON.stringify(v));return pgCheckpoint();},downloadJSON:pgDownload,importJSON:pgImport};}
function pgDownload(name,obj){const u=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function pgImport(callback){if(!pgPause())return;const owner=pgOwner,game=pgGame;const i=document.createElement('input');i.type='file';i.accept='.json,application/json';i.onchange=async()=>{const f=i.files[0];if(!f||f.size>50000)return toast('作品檔要少於 50 KB。','bad');try{const value=JSON.parse(await f.text());if(owner!==pgOwner||game!==pgGame||owner!==accountId()+':'+activeChild().id)throw Error('孩子或遊戲已切換');callback(value);pgCheckpoint();pgGame?.draw();}catch{toast('作品檔的格式不對，請換另一個檔案。','bad');}};i.click();}
async function pgBuy(id,plan){if(pgBusy||!pgAllow(id))return;const intentOwner=accountId()+':'+activeChild().id;pgBusy=true;pgError='';try{if(!pgPause())throw Error('有遊戲進度未能儲存。請家長檢查瀏覽器的儲存設定。');arPause();arEngine=null;if(!await arAcquire())throw Error('另一個分頁正在玩遊戲；請先暫停它。');if(intentOwner!==accountId()+':'+activeChild().id)throw Error('已換了孩子，沒有扣金幣。');arReadLatest();if(!pgAllow(id))throw Error('這款遊戲尚未開放。');pgFree=adminUnlocks();const g=WQGames.find(g=>g.id===id),cv=document.createElement('canvas');cv.width=800;cv.height=560;pgTools=[];pgResult=null;const candidate=new g.Class(pgApi(g,cv.getContext('2d'))),c=pgChild(),slot=id+'|'+c.difficulty;
 if(!pgFree&&c.saves[slot])PG.restore(candidate,c.saves[slot],WQCore.rng);candidate.draw(); // resource/restore preflight BEFORE charging
 const before=structuredClone(db);if(!pgFree){if(!c.ticket||c.ticket.remainingMs<=0){const result=PG.purchase(c,activeChild().stars,plan,pgDay(),uid('pg'),id);activeChild().stars=result.balance;}if(PG.remainingDaily(c,pgDay())<=0)throw Error('今天的遊戲時間已用完。沒用完的時間會保留。');c.ticket.last=id;if(!save()){db=before;throw Error('儲存失敗，沒有扣金幣。請再試一次。');}}
 pgGame=candidate;pgMeta=g;pgSlot=slot;pgOwner=accountId()+':'+activeChild().id;pgPlaying=false;pgReason=candidate.done?'round':'ready';pgGame.toolbar?.();$('#pg-dialog')?.close();stopSpeech();pcStop();fgStopAudio();go('playground');render();
}catch(e){pgError=e.message;toast('未能開始：'+e.message,'bad');arDropLease();}finally{pgBusy=false;}}
function pgCheckpoint(){if(!pgGame||pgFree)return true;if(pgOwner!==accountId()+':'+activeChild().id)return false;try{const c=pgChild();c.saves[pgSlot]=PG.snapshot(pgGame);const score=Number(pgGame.score);if(Number.isFinite(score)&&score>=0)c.bests[pgSlot]=Math.max(c.bests[pgSlot]||0,score);if(!save())throw Error('還沒儲存。請不要關閉頁面，先匯出備份。');return true;}catch(e){pgPlaying=false;pgReason='error';pgError=e.message;pgAudio.pause();cancelAnimationFrame(pgFrame);pgOverlay();return false;}}
function pgPause(){if(!pgGame)return true;pgPlaying=false;cancelAnimationFrame(pgFrame);pgAudio.pause();pgGame.keys.clear();if('charging' in pgGame)pgGame.charging=false;try{pgGame.pointer('cancel',{x:0,y:0});}catch{}pgReason=pgReason==='error'?'error':pgGame.done?'round':'paused';const ok=pgCheckpoint();arDropLease();pgOverlay();return ok;}
function pgOverlay(){const box=$('#pg-overlay');if(!box||!pgGame)return;box.hidden=pgPlaying;if(pgPlaying){box.replaceChildren();pgRenderTools();return;}let title='準備好了？',body='按開始才計時；暫停及看結果不扣時間。',actions=pgButton('開始','play','','primary');const c=pgChild(),left=c.ticket?.remainingMs||0;
 if(pgReason==='paused'){title='已暫停';body='進度和未用時間保留。';actions=pgButton('繼續','play','','primary');}
 if(pgGame.done){title=pgResult?.title||'這一關完成';body=pgResult?.text||'可以繼續挑戰，或儲存進度，回到遊戲街機。';actions=(pgGame._wqNext?pgButton('下一關 · 不扣金幣','next','','primary'):'')+pgButton('重新挑戰 · 不扣金幣','restart','','secondary');}
 if(!pgFree&&(left<=0||PG.remainingDaily(c,pgDay())<=0)){title=left<=0?'這次小休完成':'今日小休時間已用完';body='已儲存目前關卡，下次可以接着玩。不會自動扣金幣續玩。';actions=link('返回學習','kid','primary');}
 if(pgReason==='error'){title='遊戲已安全暫停';body=pgError||'儲存失敗，請先匯出備份。';actions=pgButton('重試儲存','retry-save','','primary');}
 box.innerHTML=`<div class="pg-overlaycard"><h2>${esc(title)}</h2><p>${esc(body)}</p><div class="row">${actions}${pgButton('返回遊戲街機','leave','','soft')}</div><small>${pgFree?'測試模式不扣金幣，也不會改動孩子的遊戲進度。':`還剩 ${pgTime(left)} · 已換好，不再扣金幣`}</small></div>`;pgRenderTools();}
function pgRenderTools(){const box=$('#pg-tools');if(!box)return;box.innerHTML=pgTools.map(t=>`<button type="button" class="btn ${t.active?'primary':'soft'}" data-pgtool="${esc(t.id)}" ${typeof t.active==='boolean'?`aria-pressed="${t.active}"`:''} ${t.ariaLabel?`aria-label="${esc(t.ariaLabel)}"`:''} ${!pgPlaying||t.disabled?'disabled':''}>${esc(t.label)}</button>`).join('');$$('[data-pgkey]').forEach(b=>b.disabled=!pgPlaying);}
function pgAttach(){const cv=$('#pg-canvas');if(!cv||!pgGame)return;pgGame.c=cv.getContext('2d');pgGame.api.ctx=pgGame.c;pgPlaying=false;pgGame.draw();pgOverlay();pgRenderTools();$('#pg-hint').textContent=pgHint;let pointer=null;const point=e=>{const r=cv.getBoundingClientRect();return{x:(e.clientX-r.left)*800/r.width,y:(e.clientY-r.top)*560/r.height};};
 cv.addEventListener('pointerdown',e=>{if(!pgPlaying||pointer!==null)return;pointer=e.pointerId;cv.setPointerCapture(pointer);e.preventDefault();pgGame.pointer('down',point(e));});cv.addEventListener('pointermove',e=>{if(pgPlaying&&(pointer===null||pointer===e.pointerId))pgGame.pointer('move',point(e));});for(const ev of ['pointerup','pointercancel','lostpointercapture'])cv.addEventListener(ev,e=>{if(pointer!==e.pointerId)return;pointer=null;if(pgPlaying)pgGame.pointer(ev==='pointerup'?'up':'cancel',point(e));});
 $$('[data-pgkey]').forEach(b=>{b.addEventListener('pointerdown',e=>{if(!pgPlaying)return;e.preventDefault();b.setPointerCapture(e.pointerId);pgGame.key(b.dataset.pgkey,true);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>pgGame?.key(b.dataset.pgkey,false));});}
async function pgPlay(){if(pgBusy||!pgGame||pgGame.done)return;if(pgOwner!==accountId()+':'+activeChild().id||(pgFree&&!adminUnlocks())){pgGame=null;go('game');render();return;}pgBusy=true;try{if(!await arAcquire())throw Error('另一個分頁正在玩，請先暫停。');const remote=JSON.parse(localStorage.getItem(dbKey())||'null');if(remote&&remote.writeRevision>db.writeRevision)throw Error('另一個分頁更新了資料。請重新打開頁面，不要蓋掉新紀錄。');if(!pgFree&&(pgChild().ticket?.remainingMs<=0||PG.remainingDaily(pgChild(),pgDay())<=0))return pgOverlay();if(!pgFree&&!pgAllow(pgMeta.id))throw Error('這款遊戲已暫停開放。');if(!pgCheckpoint())return;pgPlaying=true;pgReason='';pgGame.keys.clear();pgLast=performance.now();pgAcc=0;pgOverlay();$('#pg-canvas')?.focus({preventScroll:true});await pgAudio.unlock();if(!pgPlaying)return;pgLast=performance.now();pgGame.onResume?.();cancelAnimationFrame(pgFrame);pgFrame=requestAnimationFrame(pgTick);}catch(e){pgError=e.message;pgReason='error';pgOverlay();arDropLease();}finally{pgBusy=false;}}
function pgTick(now){if(!pgPlaying||!pgGame||lastRoute!=='playground')return;const elapsed=Math.max(0,now-pgLast);pgLast=now;if(document.hidden){pgPause();return;}try{const ms=pgFree?elapsed:PG.consume(pgChild(),pgDay(),elapsed);let left=Math.min(ms/1000,.25);while(left>1e-7&&pgPlaying){const h=Math.min(1/60,left);pgGame.tick(h);left-=h;}pgGame.draw();$('#pg-clock').textContent=pgFree?'測試不限時':pgTime(pgChild().ticket.remainingMs);$('#pg-score').textContent=`${pgGame.stat||''} · ${Math.round(pgGame.score||0)} 分`;pgAcc+=elapsed;if(!pgFree&&(pgChild().ticket.remainingMs<=0||PG.remainingDaily(pgChild(),pgDay())<=0)){pgPause();return;}if(pgAcc>=600){pgAcc=0;if(!pgCheckpoint())return;}if(pgPlaying)pgFrame=requestAnimationFrame(pgTick);}catch(e){pgPlaying=false;pgError=e.message;pgReason='error';pgAudio.pause();pgCheckpoint();pgOverlay();}}
function pgNext(){if(!pgGame?._wqNext)return;pgGame.done=false;pgGame._wqNext=false;switch(pgMeta.id){case'honey-delivery':case'rolling-block':case'juice-lines':case'color-workshop':pgGame.level++;pgGame.load();break;case'little-engineer':pgGame.level++;pgGame.loadSim();pgGame.toolbar();break;case'number-garden':break;default:pgGame.done=true;return;}pgResult=null;pgCheckpoint();pgPlay();}
function pgRestart(){if(!pgGame)return;const cv=$('#pg-canvas');pgGame=new pgMeta.Class(pgApi(pgMeta,cv.getContext('2d')));pgResult=null;pgCheckpoint();pgPlay();}
/* Host-closure audio adapter. A gesture unlocks the context BEFORE play is committed.
 * Both buses honour the global mute. Zero volume means no scheduled nodes.
 * No wall-clock sequencer: game simulation schedules music, so pause is immediate.
 */
const pgAudio={ctx:null,nodes:new Set(),master:null,musicMaster:null,epoch:0,lastError:'',sample:false,
 async unlock(){const request=++this.epoch;try{if(!this.ctx||this.ctx.state==='closed'){const AC=window.AudioContext||window.webkitAudioContext;if(!AC){this.lastError='這個瀏覽器不能播放遊戲聲音。';return false;}this.ctx=new AC();this.master=this.ctx.createGain();this.musicMaster=this.ctx.createGain();this.master.connect(this.ctx.destination);this.musicMaster.connect(this.ctx.destination);}this.mute();if(this.ctx.state==='suspended')await this.ctx.resume();if(request!==this.epoch)return false;this.lastError='';return this.ctx.state==='running';}catch(e){this.lastError=String(e.message||e);toast('音效開不到。可以不開聲音玩，或按「試音」再試。');return false;}},
 volume(kind){const key=kind==='music'?'arcadeMusicVolume':'arcadeSfxVolume',n=db?.settings?.[key];return Math.max(0,Math.min(100,Number.isFinite(n)?n:kind==='music'?35:60))/100;},
 tone(f=600,d=.1,wave='sine',vol=.1,at=null,kind='sfx'){if(!this.ctx||this.ctx.state!=='running'||!sfxEnabled()||!pgPlaying&&!this.sample||this.volume(kind)===0||this.nodes.size>=64)return;const t=Math.max(this.ctx.currentTime+.001,at??this.ctx.currentTime+.003),duration=Math.max(.025,Math.min(.5,Number.isFinite(d)?d:.1));const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=['sine','triangle','square','sawtooth'].includes(wave)?wave:'sine';o.frequency.value=Math.max(30,Math.min(6000,Number.isFinite(f)?f:600));g.gain.setValueAtTime(.00001,t);g.gain.exponentialRampToValueAtTime(Math.max(.00002,Math.min(.22,Number.isFinite(vol)?vol:.1)),t+.007);g.gain.exponentialRampToValueAtTime(.00001,t+duration);o.connect(g);g.connect(kind==='music'?this.musicMaster:this.master);o.start(t);o.stop(t+duration+.025);this.nodes.add(o);o.onended=()=>{this.nodes.delete(o);try{o.disconnect();g.disconnect();}catch{}};},
 drum(kind,at){this.tone(kind===0?95:kind===1?230:1150,kind===0?.18:.045,kind===0?'sine':'triangle',kind===0?.15:.06,at);},
 instrument(track,step,at){if(track<3)this.drum(track,at);else this.tone((track===3?[130.81,146.83,164.81,174.61]:[523.25,587.33,659.25,783.99])[step%4],.22,'triangle',.07,at);},
 pause(){this.epoch++;this.sample=false;for(const n of this.nodes)try{n.stop();}catch{}this.nodes.clear();if(this.ctx?.state==='running')this.ctx.suspend().catch(()=>{});},
 clock(){return this.ctx?this.ctx.currentTime:performance.now()/1000;},
 mute(){if(!this.ctx)return;const enabled=sfxEnabled(),t=this.ctx.currentTime;for(const[k,b]of [['sfx',this.master],['music',this.musicMaster]])if(b){b.gain.cancelScheduledValues(0);b.gain.value=enabled?this.volume(k)*.8:0;}},
 async test(){if(!sfxEnabled()){toast('聲音全部關了。請先按頁面上方的聲音開關。');return;}if(!await this.unlock())return;const epoch=this.epoch;this.sample=true;this.tone(523.25,.14,'triangle',.1);this.tone(659.25,.14,'triangle',.1,this.ctx.currentTime+.15);setTimeout(()=>{if(epoch!==this.epoch)return;this.sample=false;if(!pgPlaying)this.pause();},420);}
};

// Learning signals: no fabricated back-fill from older ambiguous attempt history.
function pgHinted(){return !!currentItem()&&pgChild().hints.includes(currentItem().id);}
const pgPriorHelp=showHelp;showHelp=function(){if(isLoggedIn()&&currentItem()&&currentWord()){const c=pgChild();if(!c.hints.includes(currentItem().id))c.hints.push(currentItem().id);c.hints=c.hints.slice(-2000);v24Expose([currentWord().en]);save();}return pgPriorHelp();};
const pgPriorBody=taskBody;taskBody=function(it,w){if(isLoggedIn()&&['study','meaning','listenChoice','missing'].includes(it.type)){PG.reveal(pgChild(),w.en,Date.now());save();}return pgPriorBody(it,w);};
