// Capture phase prevents the inherited click handlers from applying expired parent writes.
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-v23]');if(b){e.preventDefault();e.stopImmediatePropagation();const a=b.dataset.v23;
  if(a==='parent-unlock')void v23Unlock();
  if(a==='change-password')void v23ChangePassword();
  if(a==='acquire')void(async()=>{if(v23Dirty){toast('先儲存或匯出還沒儲存的進度。','bad');return;}if(await arAcquire()){db=load();render();}else toast(v23CapabilityError(),'bad');})();
  if(a==='reset-game')void(async()=>{if(!await arAcquire())return;if(!confirm('只重設這款遊戲這個難度的進度嗎？金幣和其他遊戲不變。'))return;const before=structuredClone(db),c=pgChild();delete c.saves[b.dataset.slot];delete c.quarantine?.[b.dataset.slot];if(!save()){db=before;return;}pgGame=null;pgIntro(b.dataset.game);})();
  return;
 }
 const pg=e.target.closest('[data-pg]'),act=e.target.closest('[data-act]'),admin=e.target.closest('[data-admin]');
 if(isLoggedIn()&&!v23HasLease()&&(pg||admin||act&&!['logout','login-submit','close-help','export-data','export-raw'].includes(act.dataset.act))){e.preventDefault();e.stopImmediatePropagation();toast(v23CapabilityError(),'bad');return;}
 if(!v23ParentAllowed()&&(pg?.dataset.pg==='save-settings'||admin||act&&v23ParentActions.has(act.dataset.act))){e.preventDefault();e.stopImmediatePropagation();$('#app').innerHTML=v23Gate();return;}
},true);
window.addEventListener('pagehide',()=>{pgPause();v23Release();v23ParentUntil=0;});
