function a28Root(){if(!db.arcadeV28)COIN28.migrate(db);for(const c of db.children)if(!db.arcadeV28.children[c.id])db.arcadeV28.children[c.id]=COIN28.child();return db.arcadeV28;}
function a28Child(){return a28Root().children[activeChild().id];}
function a28Run(){return a28Child().run;}
function a28Meta(id){return WQGames.find(g=>g.id===id);}
function a28Qualified(){return PG.count(pgChild());}
function a28Own(){return accountId()+':'+activeChild().id;}
function a28Active(){const r=a28Run();return r&&!['finished','refunded'].includes(r.phase);}
function a28CanWrite(){return isLoggedIn()&&v24CanWrite()&&v23HasLease();}
function a28Allow(id){return isLoggedIn()&&COIN28.allowed(a28Child(),id,a28Qualified(),pgChild().override,adminUnlocks());}
