 function openGallery(id){const c=context();if(c.busy||c.exam||route()==='playground')return;selected=C.ids.includes(id)?id:'owl';selectedPose='front';stopVoice();if(dialog){paintDialog();return;}origin=document.activeElement;dialog=elem('dialog','wq32-modal');dialog.id='wq32-character-dialog';dialog.setAttribute('aria-label','認識學習夥伴');document.body.append(dialog);dialog.addEventListener('cancel',e=>{e.preventDefault();closeGallery();});dialog.addEventListener('close',()=>{if(dialog)closeGallery();});paintDialog();dialog.showModal();Q('[data-wq32="close"]',dialog)?.focus({preventScroll:true});}
