 function voiceNote(card,text){let p=Q('.wq32-voice-note',card);if(!p){p=elem('p','wq32-subtle wq32-voice-note');p.setAttribute('role','status');(Q('.wq32-guide-copy',card)||card).append(p);}p.textContent=text;}
 function stopVoice(){++speechEpoch;clearTimeout(speechTimer);if(activeSpeech){activeSpeech=null;try{speechSynthesis.cancel();}catch(_){}}}
 function speak(card){const c=context();if(!pref.show||c.busy||c.exam||document.hidden)return;stopVoice();try{if(typeof speechSynthesis==='undefined'||typeof SpeechSynthesisUtterance==='undefined')throw Error('這部裝置沒有角色語音，請看文字。');if(speechSynthesis.speaking||(typeof voiceBusy!=='undefined'&&voiceBusy)||l30AudioKey)throw Error('先聽完教材讀音，再聽角色說明。');const v=speechSynthesis.getVoices().find(v=>v.localService&&/^(yue|zh[-_]HK)/i.test(v.lang));if(!v)throw Error('裝置沒有廣東話聲音，請看文字說明。');const u=new SpeechSynthesisUtterance(Q('.wq32-line',card)?.textContent||'');activeSpeech=u;const epoch=++speechEpoch;u.voice=v;u.lang=v.lang;u.rate=.9;u.onend=()=>{if(speechEpoch===epoch){activeSpeech=null;clearTimeout(speechTimer);}};u.onerror=()=>{if(speechEpoch===epoch){activeSpeech=null;clearTimeout(speechTimer);voiceNote(card,'語音沒有播完，不影響教材和成績。可以再按一次，或看文字。');}};speechTimer=setTimeout(()=>{if(epoch===speechEpoch){stopVoice();voiceNote(card,'角色語音已停止，請看文字。');}},16000);speechSynthesis.speak(u);}catch(e){voiceNote(card,e.message||'角色語音未能啟動，請看文字。');}}
 function addHintPortrait(c){if(c.exam)return;for(const sel of ['[data-l30="hint"]','[data-l31="hint"]']){const b=Q(sel);if(!b||Q('[data-wq32-character]',b))continue;const im=image('star','front','wq32-hint-icon');im.alt='';b.prepend(im);b.setAttribute('aria-label','需要提示（請刺刺幫忙）');}}
 function gameOverlay(){const box=Q('#pg-overlay .a28-overlaycard');if(!box||!pref.show||Q('.wq32-overlay-face',box))return;const state=pgFree?pgReason:a28Run()?.phase;const finished=state==='finished'||pgFree&&pgGame?.done;const id=finished?'bee':pref.gameBuddy;const icon=Q('.a28-overlay-symbol',box);if(icon)icon.replaceWith(image(id,finished?'face0':'front','wq32-overlay-face'));else box.prepend(image(id,finished?'face0':'front','wq32-overlay-face'));}
 function gameBar(){if(!pref.show)return;const stage=Q('.a28-play');if(!stage)return;let bar=Q('.wq32-gamebar',stage);if(!bar){bar=mark(elem('div','wq32-gamebar'));bar.id='wq32-game-buddy';bar.append(image(pref.gameBuddy,'front'));const cp=elem('div');cp.append(elem('strong','',C.roles[pref.gameBuddy].name+' · 遊戲學伴'),elem('p','wq32-game-line','先看清楚玩法，準備好才開始。'));bar.append(cp,elem('span','wq32-game-state','陪伴角色 · 不改遊戲難度'));Q('.a28-playhead',stage)?.after(bar);}const line=Q('.wq32-game-line',bar);const state=pgPlaying?'playing':(pgFree?pgReason:a28Run()?.phase)||'ready';if(bar.dataset.state!==state){bar.dataset.state=state;line.textContent=pgPlaying?'我在旁邊陪你，專心操作就好。':state==='finished'?'這局結束了。成績看畫面上的分數。':state==='paused'?'休息一下。進度和生命都保留。':state==='retry'?'還有生命。想好方法再試。':'先看清楚玩法，準備好才開始。';}}
 function galleryEntry(){const e=mark(elem('div','wq32-entry'));const t=elem('div');t.append(elem('strong','','學習夥伴'),elem('p','','每位角色都有自己的工作。'));e.append(t,button('認識學習夥伴與顯示設定','page'));return e;}
