/* V32 + Maths 0.1.2 integration R1. Insert INSIDE the English application closure.
 * No account registry, password hashes or mutable English database is exported.
 * Browser-local coordination is not server authentication or anti-cheat.
 */
(function installMathHost(){
  const root=window, clone=x=>JSON.parse(JSON.stringify(x));
  const C=()=>root.WQMathCore;
  const scope=()=>accountId()+':'+activeChild()?.id;
  function profile(){
    const ch=activeChild();
    if(!ch||!C()?.safeId(ch.id))throw Error('讀不到這位孩子的資料。請重新整理頁面再試。');
    return {id:ch.id,name:ch.name,grade:ch.grade,account:accountId()||'guest',persistent:isLoggedIn(),balance:ch.stars||0};
  }
  function assertWritable(){
    if(root.WQR3?.dataBusy())throw Error("家庭資料正在處理，數學暫時不能儲存。");
    if(!isLoggedIn())return;
    if(loadBlocked)throw Error('讀不到英文的原有資料，所以數學也暫時不能儲存。原有檔案沒有改動。請先匯出備份。');
    if(!v23HasLease())throw Error('這個分頁不能編輯。請回到英文，按「在這個分頁編輯」，再繼續數學。');
    arReadLatest();
  }
  function beforeOpen(){
    const route=(location.hash||'#kid').slice(1).split('?')[0];
    if(['learn','learning','assembly-learn','family-lesson','phonics-lesson','range-new'].includes(route))
      throw Error('請先暫停英文練習，或儲存匯入的內容，回到首頁後再打開數學。');
    if(a28Active()||pgPlaying||(pgGame&&!pgGame.done)||miniGame&&!miniGame.ended||arEngine&&!arEngine.paused)
      throw Error('請先結束目前的遊戲，再打開數學。沒有扣金幣。');
    if(isLoggedIn())assertWritable();
    stopSpeech();fgResetAudio();pcStop();
  }
  function award(request,expected){
    const p=profile();if(!p.persistent)return 0;
    if(p.account+':'+p.id!==expected)throw Error('已換了孩子或帳戶，沒有給獎勵。');
    assertWritable();
    // Only settle an event already committed to the active child's sidecar.
    const raw=localStorage.getItem('wqm-state-v1:'+expected);
    if(!raw)throw Error('沒有已儲存的數學獎勵紀錄。');
    const state=C().validateState(JSON.parse(raw),C().library(root.WQMathData));
    const e=state.outbox.find(x=>x.id===request?.id);
    if(!e)throw Error('找不到已儲存的這項數學任務。請回到數學頁再試。');
    for(const k of ['key','day','startedAt','completedAt','valid'])if(e[k]!==request[k])throw Error('獎勵資料和已儲存的任務對不上。');
    if(e.settled)return 0;
    if(C().hkDay(e.completedAt)!==e.day||e.completedAt>Date.now()+5000||Date.now()-e.completedAt>7*86400000)
      throw Error('獎勵日期超出可自動處理的範圍。請保留數學備份。');
    const before=clone(db);
    try{
      a28Root();const child=db.children.find(c=>c.id===p.id);
      const result=COIN28.task(db.arcadeV28.children[p.id],child.stars,
        {key:'math:'+e.key,day:e.day,startedAt:e.startedAt,completedAt:e.completedAt,valid:e.valid===true});
      child.stars=result.balance;
      if(save()!==true)throw Error('金幣沒有儲存成功，這次獎勵沒有完成。請再試一次。');
      if(result.award>0)try{a33CoinCue('');}catch(_){}
      return result.award;
    }catch(err){db=before;throw err;}
  }
  // Remove the math sidecar AND its pre-restore copy when the corresponding
  // English child is deleted. Cancel the English write if cleanup fails.
  const priorSave=save;
  save=function(){
    let copies=[],familyCleanup=null;
    try{
      if(isLoggedIn()){
        const raw=localStorage.getItem(dbKey()),old=raw?JSON.parse(raw):null;
        const removed=(old?.children||[]).filter(c=>!db.children.some(n=>n.id===c.id));
        for(const ch of removed){
          const key='wqm-state-v1:'+accountId()+':'+ch.id;
          for(const k of [key,key+':before-restore',...['normal','sandbox'].map(mode=>'wordquest-v32-characters:'+mode+':'+accountId()+':'+ch.id)])copies.push([k,localStorage.getItem(k)]);
        }
        if(removed.length){const fk='wq-r3-family:'+accountId(),raw=localStorage.getItem(fk);if(raw){const f=window.WQFamilyCore.validateSettings(JSON.parse(raw));for(const ch of removed){delete f.usage[ch.id];f.migrationReceipts=f.migrationReceipts.filter(r=>r.target!==ch.id);}f.revision++;copies.push([fk,raw]);familyCleanup=[fk,JSON.stringify(f)];}}if(copies.length)assertWritable();
        for(const[k]of copies)localStorage.removeItem(k);if(familyCleanup)localStorage.setItem(...familyCleanup);
      }
      if(priorSave()===true){if(familyCleanup)r3ReloadSettings();return true;}
    }catch(err){persistenceIssue='沒有完成儲存或刪除：'+err.message;showSaveIssue();}
    for(const[k,v]of copies)try{if(v!==null)localStorage.setItem(k,v);}catch(err){persistenceIssue='刪除備用副本沒有完成。請不要關閉這個頁面，並匯出備份。'+err.message;showSaveIssue();}
    return false;
  };
  let wqmGateReturn=0;
  root.WQMathHost=Object.freeze({apiVersion:1,version:'V32-M0.1.2-R1',mode:'wordquest',profile,award,beforeOpen,assertWritable,
    parentAllowed:()=>!isLoggedIn()||v23ParentAllowed(),
    openParentGate(){wqmGateReturn=Date.now();go('parent');render();toast('請輸入家長密碼，完成後會回到數學進度。');},
    afterClose(){render();}
  });
  function summary(){
    const p=profile();if(!p.persistent)return '試玩不儲存進度或金幣。';
    const raw=localStorage.getItem('wqm-state-v1:'+p.account+':'+p.id);
    if(!raw)return '數學尚未有作答紀錄。';
    const s=C().validateState(JSON.parse(raw),C().library(root.WQMathData));
    const n=s.attempts.filter(a=>a.track==='normal').length,o=s.attempts.filter(a=>a.track==='olympiad').length;
    return '普通數學 '+n+' 次作答 · 奧數 '+o+' 次作答。兩條路線分開記錄。';
  }
  function decorate(){
    const rt=(location.hash||'#kid').slice(1).split('?')[0],app=$('#app');if(!app)return;
    if(wqmGateReturn){
      if(!['parent','report'].includes(rt)||Date.now()-wqmGateReturn>600000)wqmGateReturn=0;
      else if(!isLoggedIn()||v23ParentAllowed()){wqmGateReturn=0;setTimeout(()=>{try{root.WQMathApp?.open?.('parent');}catch(err){toast(err.message,'bad');}},0);}
    }
    const badge=$('#v25-build-badge');if(badge)badge.textContent='英文與數學';
    if(false){
      const box=document.createElement('section');box.id='wq-subjects';box.className='card pad wq-subjects';box.setAttribute('aria-label','選擇學科');
      box.innerHTML='<div><p class="eyebrow">選擇今天的學習</p><h2>英文與數學，同一個學習帳戶</h2><p class="muted">英文練習在下面。數學和奧數共用同一位孩子和金幣，學習進度分開儲存。</p></div><div class="row"><button class="btn primary" type="button" data-wqm-open="normal">普通數學</button><button class="btn secondary" type="button" data-wqm-open="olympiad">奧數思維</button><button class="btn soft" type="button" data-wqm-open="home">數學學習首頁</button></div>';
      app.prepend(box);
    }
    if(['parent','report'].includes(rt)&&(!isLoggedIn()||v23ParentAllowed())&&!$('#wq-maths-parent')){
      const box=document.createElement('section');box.className='card pad';box.id='wq-maths-parent';
      const h=document.createElement('h2');h.textContent='數學與奧數進度';const p=document.createElement('p');
      try{p.textContent=summary();}catch(e){p.textContent='讀不到數學資料，原有檔案沒有改動。請先匯出備份。'+e.message;}
      const b=document.createElement('button');b.type='button';b.className='btn secondary';b.dataset.wqmOpen='parent';b.textContent='數學進度及設定';box.append(h,p,b);app.append(box);
    }
  }
  const priorRender=render;render=function(){const result=priorRender.apply(this,arguments);decorate();return result;};
  document.addEventListener('click',e=>{const b=e.target.closest?.('[data-wqm-open]');if(!b)return;e.preventDefault();
    if(!root.WQMathApp?.open){toast('數學還沒載入完成。請重新打開完整的檔案。','bad');return;}
    try{root.WQMathApp.open(b.dataset.wqmOpen);}catch(err){toast(err.message,'bad');}
  });
  const priorDiagnostics=v25Diagnostics;v25Diagnostics=function(){return {...priorDiagnostics(),integrationVersion:'V32-M0.1.2-R1',mathBaseVersion:'0.1.2',mathHostBridge:1};};
})();

/* R2 host UI. No mutable database or game engine is exported to public callers. */
function r2AudioPanel(){return `<details class="r2-audio"><summary>音量與試音</summary><div><label>遊戲音效 <input type="range" min="0" max="100" step="5" data-r2-volume="arcadeSfxVolume" value="${Math.round(pgAudio.volume('sfx')*100)}" aria-label="遊戲音效音量"></label><label>新遊戲配樂 <input type="range" min="0" max="100" step="5" data-r2-volume="arcadeMusicVolume" value="${Math.round(pgAudio.volume('music')*100)}" aria-label="新遊戲配樂音量"></label>${a28Btn('試音','r2-test-audio','','soft')}</div><p class="small muted">所有街機沿用頁首聲效開關。靜音也可以玩。音量設為 0，就完全沒有聲音。</p></details>`;}
function r2Records(){const c=a28Child(),rows=Object.entries(c.bests).sort((a,b)=>a[0].localeCompare(b[0]));return `<details class="r2-records"><summary>我的遊戲紀錄 · 原有 21 款遊戲的紀錄繼續保留</summary><p>舊遊戲繼續用原本的紀錄。五款新遊戲另外記分，不會把舊分數換算成新成績。</p>${rows.length?`<div class="r2-score-list">${rows.map(([k,v])=>{const[id,d]=k.split('|');return `<div><span>${esc(a28Meta(id)?.name||id)} · ${['入門','標準','挑戰'][Number(d)]||''}</span><strong>${v} 分</strong></div>`;}).join('')}</div>`:'<p>目前未有最高分紀錄。</p>'}<p class="small muted"></p></details>`;}
let r2Immersive=null,r2FitToken=0;
function r2Fit(){cancelAnimationFrame(r2FitToken);r2FitToken=requestAnimationFrame(()=>{const v=$('.a28-viewport'),cv=$('#pg-canvas');if(!v||!cv)return;const w=v.clientWidth,h=v.clientHeight-(typeof WQArcPlus!=='undefined'?WQArcPlus.reserve(v):0),scale=Math.min(w/800,h/560);if(scale>0){cv.style.width=(800*scale)+'px';cv.style.height=(560*scale)+'px';} });}
function r2ExitFullscreen(){if(r2Immersive){r2Immersive.classList.remove('r2-immersive');r2Immersive=null;document.body.classList.remove('r2-fullscreen');}if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});r2Fit();}
async function r2Fullscreen(){const el=$('.a28-play');if(!el)return;if(r2Immersive||document.fullscreenElement){r2ExitFullscreen();return;}r2Immersive=el;el.classList.add('r2-immersive');document.body.classList.add('r2-fullscreen');r2Fit();try{if(el.requestFullscreen)await el.requestFullscreen();}catch{toast('瀏覽器不能全螢幕，已改為在頁面內放大。');}r2Fit();}
window.addEventListener('resize',r2Fit);window.visualViewport?.addEventListener('resize',r2Fit);
