function r3SaveSettings(next){if(!isLoggedIn())throw Error('請先登入家庭帳戶');if(r3Busy||!v24CanWrite())throw Error('這個分頁不能儲存，設定沒有改動。請先按「在這個分頁編輯」。');const key=r3FamilyKey();if(localStorage.getItem(key)!==r3SettingsRaw)throw Error('另一個分頁更新了英文和數學的資料。請重新打開頁面。');next=F3.validateSettings(next);next.revision++;const raw=JSON.stringify(next);localStorage.setItem(key,raw);r3SettingsCache=next;r3SettingsRaw=raw;}
function r3Parent(rescue){if(!isLoggedIn()){go('login');render();throw Error('先登入家庭帳戶');}if(rescue===true){if(!v24RequireParent(false))throw Error('請先完成家長確認，並按「在這個分頁編輯」');if(!v23HasLease())throw Error('請先關閉其他正在編輯的分頁，再按「在這個分頁編輯」。');if(r3Busy)throw Error('資料還在處理，暫時不能儲存其他東西。請稍後再試。');return;}if(!v24RequireParent(true)||!v23HasLease())throw Error('請先完成家長確認，並按「在這個分頁編輯」');if(r3Busy)throw Error('資料還在處理，暫時不能儲存其他東西。請稍後再試。');}
function r3PauseWork(wq20o){const wq20R=!!(wq20o&&wq20o.rescue);if(mediaBusy)throw Error('教材的圖片或音檔還在處理。請等處理完成或取消，再備份／還原。');if(window.WQMathApp?.close()===false&&!wq20R)throw Error('數學草稿儲存失敗，所以沒有開始。請再試一次。');if(!pgPause()&&!wq20R)throw Error('遊戲不能暫停。請先結束遊戲，再試一次。');if(arEngine&&!arEngine.paused)arPause();stopSpeech();fgResetAudio();pcStop();if(!wq20R&&!save())throw Error('現有資料還沒儲存，所以沒有開始。請先儲存，再試一次。');}
async function r3Digest(value){if(!crypto.subtle)throw Error('這個瀏覽器不能檢查備份檔，所以沒有建立備份。請用 https 網址，或本機啟動器。');const bytes=new TextEncoder().encode(typeof value==='string'?value:JSON.stringify(value));return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');}
const r3BlobURL=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error||Error('圖片或音檔讀取失敗，請再試一次。'));r.readAsDataURL(blob);});
function r3DataBlob(row){const raw=atob(row.data.split(',')[1]),a=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)a[i]=raw.charCodeAt(i);return new Blob([a],{type:row.mime});}
function r3Download(name,data,mime='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:mime});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function r3OwnedKeys(a=accountId()){const main=DBKEY_PREFIX+a,mp='wqm-state-v1:'+a+':';return Array.from({length:localStorage.length},(_,i)=>localStorage.key(i)).filter(k=>k===main||k===main+'-before-restore'||k===main+'-v24-protection'||k===r3FamilyKey(a)||k?.startsWith(mp)||k?.startsWith('wordquest-v32-characters:normal:'+a+':')||k?.startsWith('wordquest-v32-characters:sandbox:'+a+':'));}
function r3ReadKV(a=accountId()){return Object.fromEntries(r3OwnedKeys(a).map(k=>[k,localStorage.getItem(k)]));}
// A separate durable IndexedDB journal supports recovery across localStorage and media transactions.
function r3OpenJournal(){return new Promise((resolve,reject)=>{const r=indexedDB.open('wordquest-family-journal-r3',1);r.onupgradeneeded=()=>r.result.createObjectStore('transactions',{keyPath:'owner'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error||Error('無法建立備用紀錄。請稍後再試。'));r.onblocked=()=>reject(Error('請關閉其他分頁再重試'));});}
async function r3Journal(mode,row){const d=await r3OpenJournal();try{return await new Promise((resolve,reject)=>{const tx=d.transaction('transactions',mode==='get'?'readonly':'readwrite'),s=tx.objectStore('transactions');const r=mode==='get'?s.get(row):mode==='delete'?s.delete(row):s.put(row);let value;r.onsuccess=()=>value=r.result;tx.oncomplete=()=>resolve(value);tx.onabort=()=>reject(tx.error||Error('備用紀錄儲存失敗，請稍後再試。'));tx.onerror=()=>{};});}finally{d.close();}}
async function r3ReplaceMedia(owner,rows){const d=await openMediaDb();return new Promise((resolve,reject)=>{const tx=d.transaction('assets','readwrite'),s=tx.objectStore('assets'),r=s.index('owner').getAllKeys(owner);r.onsuccess=()=>{for(const key of r.result)s.delete(key);for(const row of rows)s.put({...row,id:recordId(owner,row.key),owner});};tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error||Error('圖片或音檔處理失敗，請再試一次。'));tx.onerror=()=>{};});}
function r3ReplaceKV(owner,values){WQR32Safety.validateKV(values,owner,DBKEY_PREFIX+owner);for(const k of r3OwnedKeys(owner))if(!Object.hasOwn(values,k))localStorage.removeItem(k);for(const [k,v]of Object.entries(values))if(v===null)localStorage.removeItem(k);else localStorage.setItem(k,v);}
async function r3Transaction(values,media,label,wq20Opts){
 const wq20R=!!(wq20Opts&&wq20Opts.rescue);r3Parent(wq20R);r3PauseWork({rescue:wq20R});let wq20Orig=null,wq20Media=null;const owner=accountId(),intent=v23Owner(),beforeDb=r3Clone(db),before=r3ReadKV(owner),inert=document.body.inert;let prepared=false,committed=false,journalWritten=false;r3Busy=true;document.body.inert=true;
 const unchanged=()=>{if(owner!==accountId()||intent!==v23Owner()||!v23ParentAllowed()||!v23HasLease())throw Error('帳戶或家長確認已改變，請重新操作。');};
 try{const ek=DBKEY_PREFIX+owner;if(values[ek]){const next=JSON.parse(values[ek]);next.writeRevision=(db.writeRevision||0)+1;values[ek]=JSON.stringify(next);}const beforeMedia=await readMediaOwner(owner);unchanged();
  if(wq20R){wq20Orig=await wq20RescueBegin(owner,before,beforeMedia);wq20Media=beforeMedia;}await r3Journal('put',{owner,before,beforeMedia,at:Date.now(),label:wq20R?'rescue-before':label});journalWritten=true;if(!wq20R)localStorage.setItem(r3Marker(owner),'prepared');prepared=true;unchanged();r3ReplaceKV(owner,values);await r3ReplaceMedia(owner,media);unchanged();localStorage.setItem(r3Marker(owner),'committed');committed=true;
  await r3Journal('delete',owner);localStorage.removeItem(r3Marker(owner));prepared=false;db=validateDb(JSON.parse(localStorage.getItem(ek)));loadBlocked=false;persistenceIssue='';r3ReloadSettings();stopMediaPlayback();revokeMediaUrls();mediaOwner='';mediaPromise=null;await syncMediaOwner(true);cancelAnimationFrame(arFrame);arEngine=null;pgGame=null;pgPlaying=false;
 }catch(e){if(committed){loadBlocked=true;persistenceIssue='資料已儲存，但最後一步還沒完成。請按「處理未完成的操作」完成。';showSaveIssue();throw Error(persistenceIssue);}
  if(prepared&&wq20R){try{await wq20RescueRollback(owner,before,wq20Media,wq20Orig);db=owner===accountId()?beforeDb:load();r3SettingsOwner='';}catch(rollback){loadBlocked=true;persistenceIssue='資料處理中途停了，備用紀錄已保留。請不要清除瀏覽器的資料：'+rollback.message;showSaveIssue();throw Error(persistenceIssue);}}
  else if(prepared){try{const j=await r3Journal('get',owner);if(!j)throw Error('找不到備用紀錄。請用家庭備份還原。');WQR32Safety.validateJournal(j,owner,DBKEY_PREFIX+owner);validateDb(JSON.parse(j.before[DBKEY_PREFIX+owner]));r3ReplaceKV(owner,j.before);await r3ReplaceMedia(owner,j.beforeMedia);localStorage.setItem(r3Marker(owner),'rolled-back');await r3Journal('delete',owner);localStorage.removeItem(r3Marker(owner));db=owner===accountId()?beforeDb:load();r3ReloadSettings();}catch(rollback){loadBlocked=true;persistenceIssue='資料處理中途停了，備用紀錄已保留。請不要清除瀏覽器的資料：'+rollback.message;showSaveIssue();throw Error(persistenceIssue);}}
  else if(journalWritten){try{await r3Journal('delete',owner);}catch(_){} }throw e;
 }finally{r3Busy=false;document.body.inert=inert;}window.dispatchEvent(new Event('wq-r3-data-replaced'));render();
}
async function r3Recover(){
 if(!isLoggedIn()||!localStorage.getItem(r3Marker()))return false;if(!v23ParentAllowed()){v24RequireParent(false);throw Error('請先完成家長確認，再按「處理未完成的操作」');}if(!v23HasLease())throw Error('請先按「在這個分頁編輯」');const owner=accountId(),inert=document.body.inert;r3Busy=true;document.body.inert=true;
 try{const marker=localStorage.getItem(r3Marker(owner)),j=await r3Journal('get',owner);if(!['prepared','committed','rolled-back'].includes(marker))throw Error('未完成操作的狀態不明，資料沒有改動。');if(marker==='prepared'){if(!j)throw Error('備用紀錄不見了，不能安全地處理。請保留現有資料，並用家庭備份還原。');WQR32Safety.validateJournal(j,owner,DBKEY_PREFIX+owner);validateDb(JSON.parse(j.before[DBKEY_PREFIX+owner]));r3ReplaceKV(owner,j.before);await r3ReplaceMedia(owner,j.beforeMedia);localStorage.setItem(r3Marker(owner),'rolled-back');}if(j)await r3Journal('delete',owner);localStorage.removeItem(r3Marker(owner));loadBlocked=false;persistenceIssue='';db=load();r3ReloadSettings();await syncMediaOwner(true);window.dispatchEvent(new Event('wq-r3-data-replaced'));toast(marker==='committed'?'已完成未完成的操作。':'已回到操作之前的資料。');return true;
 }finally{r3Busy=false;document.body.inert=inert;render();}
}
async function r3Export(){const wq20R=wq20Marked();r3Parent(wq20R);r3PauseWork({rescue:wq20R});if(wq20R)wq20RescueExportCheck();const exportInert=document.body.inert;r3Busy=true;document.body.inert=true;try{const owner=accountId(),intent=v23Owner(),raw=localStorage.getItem(dbKey()),familyRaw=localStorage.getItem(r3FamilyKey()),MC=window.WQMathCore,lib=MC.library(window.WQMathData);const english=validateDb(r3Clone(db));const math=english.children.map(c=>{const a=localStorage.getItem(r3MathKey(c.id)),b=localStorage.getItem(r3MathKey(c.id)+':before-restore');return {childId:c.id,state:a?MC.validateState(JSON.parse(a),lib):null,recovery:b?MC.validateState(JSON.parse(b),lib):null};});const allKeys=r3ReadKV();const rows=await wq20ExportMediaRows(owner),media=[];for(const row of rows){const {blob,id,owner:ignored,key,kind,...meta}=row;const entry={key,kind,meta};if(blob instanceof Blob){entry.mime=blob.type;entry.data=await r3BlobURL(blob);}media.push(entry);}if(owner!==accountId()||intent!==v23Owner()||!v23ParentAllowed()||raw!==localStorage.getItem(dbKey())||familyRaw!==localStorage.getItem(r3FamilyKey())||JSON.stringify(allKeys)!==JSON.stringify(r3ReadKV()))throw Error('匯出期間資料有改動，所以沒有建立備份。請先暫停學習，再試一次。');const family=r3Clone(r3Settings());const characterPreferences=[];for(const c of english.children)for(const mode of ['normal','sandbox']){const raw=localStorage.getItem('wordquest-v32-characters:'+mode+':'+owner+':'+c.id);if(raw)characterPreferences.push({childId:c.id,mode,preferences:JSON.parse(raw)});}const payload={sourceOwner:owner,english,math,family,media,characterPreferences};F3.validatePayload(payload,validateDb,MC,lib);const pack={format:'wordquest-family',version:1,createdAt:new Date().toISOString(),appVersion:'R3.7.0',warning:'備份檔有孩子的姓名和學習紀錄，沒有加密。不含帳戶密碼和語音服務的金鑰。',payload,integrity:{algorithm:'SHA-256',digest:await r3Digest(payload)}};if(owner!==accountId()||intent!==v23Owner()||!v23ParentAllowed()||!v23HasLease()||JSON.stringify(allKeys)!==JSON.stringify(r3ReadKV()))throw Error('匯出檢查期間，資料或帳戶有改動，所以沒有建立備份。請再試一次。');const serial=JSON.stringify(pack,null,2);if(!WQR32Safety.canExport(new TextEncoder().encode(serial).length))throw Error('家庭備份超過 140 MB，所以沒有建立備份檔。');r3Download('SmartQuest_Family_'+F3.day()+'.json',serial);return pack;}finally{r3Busy=false;document.body.inert=exportInert;}}
async function r3ValidatePack(file){if(!file||file.size>140000000)throw Error('家庭備份檔超過 140 MB，或還沒選擇檔案。');const pack=F3.envelope(JSON.parse(await file.text()));if(await r3Digest(pack.payload)!==pack.integrity.digest)throw Error('備份檢查失敗，檔案可能不完整，或有人改過。資料沒有改動。');return F3.validatePayload(pack.payload,validateDb,window.WQMathCore,window.WQMathCore.library(window.WQMathData));}
async function r3Restore(payload){const wq20R=wq20Marked();r3Parent(wq20R);const MC=window.WQMathCore,owner=accountId();const clean=F3.validatePayload(payload,validateDb,MC,MC.library(window.WQMathData));const english=clean.english;
 if(clean.sourceOwner===owner){
  for(const c of english.children){const old=db.children.find(o=>o.id===c.id);if(old)c.stars=old.stars;}
  if(db.arcadeV28&&english.arcadeV28){for(const cid of Object.keys(english.arcadeV28.children||{}))if(db.arcadeV28.children?.[cid])english.arcadeV28.children[cid]=r3Clone(db.arcadeV28.children[cid]);}
  for(const name of ['dailyLedger']){english[name]=english[name]||{};for(const c of english.children)if(db[name]?.[c.id])english[name][c.id]=r3Clone(db[name][c.id]);}
  const current=wq20SafeSettings();for(const cid of english.children.map(c=>c.id))for(const [day,row] of Object.entries(current.usage[cid]||{})){const days=clean.family.usage[cid]||(clean.family.usage[cid]={}),prev=days[day]||(days[day]={english:0,math:0,olympiad:0,arcade:0});for(const subject of Object.keys(prev))prev[subject]=Math.max(prev[subject],row[subject]||0);}
  F3.validateSettings(clean.family);validateDb(english);
 }
 english.writeRevision=(db.writeRevision||0)+1;const values={[dbKey()]:JSON.stringify(english),[r3FamilyKey()]:JSON.stringify(clean.family)};for(const m of clean.math){if(m.state)values[r3MathKey(m.childId)]=JSON.stringify(m.state);if(m.recovery)values[r3MathKey(m.childId)+':before-restore']=JSON.stringify(m.recovery);}for(const row of clean.characterPreferences)values['wordquest-v32-characters:'+row.mode+':'+owner+':'+row.childId]=JSON.stringify(row.preferences);const media=wq20LiveMediaRows(clean.media,english.words).map(row=>({...row.meta,key:row.key,kind:row.kind,...(row.kind==='note'?{}:{blob:r3DataBlob(row)}),owner,updatedAt:new Date().toISOString()}));await r3Transaction(values,media,'restore-family',{rescue:wq20R});toast('家庭備份已還原。所有孩子、數學紀錄、圖片和音檔都已處理。舊的數學獎勵不會再給一次。');}
resetAll=async function(){try{const wq20R=wq20Marked();r3Parent(wq20R);if(wq20R)await wq20RescueCheck();if(!confirm(wq20R?'上次有一個操作沒有完成。\\n\\n清除目前帳戶的資料後，所有孩子、教材、進度和自訂的圖片音檔都會消失，未完成的標記也會一起清除，之後只能用家庭備份還原。\\n\\n如果你有家庭備份，請按「取消」，改用「還原家庭備份」。\\n\\n仍要清除目前帳戶的資料嗎？':'要清除目前家庭的英文、數學、奧數、遊戲、使用時間紀錄、自訂圖片／音檔，和所有備用副本嗎？其他家庭不受影響。請先匯出家庭完整備份。'))return;const fresh=isTestAdmin()?adminInitialDb():upgradeDb(newUserDb('小朋友'));fresh.writeRevision=(db.writeRevision||0)+1;await r3Transaction({[dbKey()]:JSON.stringify(fresh)},[],'reset-family',{rescue:wq20R});clearMiniTimers();miniGame=null;clearImportDraft();r3SettingsOwner='';go('parent');render();toast('目前家庭的資料和備用副本已清除。');}catch(e){toast(e.message,'bad');}};
const r3PriorSave=save;save=function(){if(r3Busy||isLoggedIn()&&localStorage.getItem(r3Marker())){persistenceIssue='家庭資料的處理還沒完成，暫時不能儲存其他資料。請到「家長 → 家庭管理」處理。';showSaveIssue();return false;}return r3PriorSave.apply(this,arguments);};
function r3Weekly(){const c=activeChild(),raw=isLoggedIn()?localStorage.getItem(r3MathKey(c.id)):null;let math=null;if(raw)math=window.WQMathCore.validateState(JSON.parse(raw),window.WQMathCore.library(window.WQMathData));return F3.weekly(db,math,c.id);}
function r3ReportHTML(){const r=r3Weekly(),set=r3Settings(),c=activeChild(),labels={english:'英文',normal:'普通數學',olympiad:'奧數'};return `<h2>${esc(c.name)} · 跨科週報</h2><p>${r.from} 至 ${r.to}。只計實際作答，沒有紀錄不作估計。</p><div class="r3-table"><table><thead><tr><th>學科</th><th>作答次數</th><th>全對次數</th><th>曾用提示</th></tr></thead><tbody>${Object.entries(r.rows).map(([k,v])=>`<tr><td>${labels[k]}</td><td>${v.attempts}</td><td>${v.correct}</td><td>${v.assisted}</td></tr>`).join('')}</tbody></table></div><h3>數學重溫優先</h3><p>${r.mathWeak.length?r.mathWeak.map(x=>esc(window.WQMathData.skills.find(s=>s.id===x.skill)?.name_zh||x.skill)+'（'+x.score+'%）').join('、'):'未有低於80%的已作答技能紀錄。'}</p><p>今天玩遊戲用了 ${Math.ceil(r3ArcadeMs(set)/60000)}／${set.limitMinutes} 分鐘。</p><button class="btn secondary" data-r3="download-report">匯出週報</button>`;}
function r3Dialog(title,html){document.getElementById('r3-dialog')?.remove();const d=document.createElement('dialog');d.id='r3-dialog';d.className='r3-dialog';d.innerHTML=`<div class="r3-dialog-head"><h1>${esc(title)}</h1><button class="btn quiet" data-r3="close">關閉</button></div><div id="r3-dialog-body">${html}</div><p id="r3-status" role="status" aria-live="polite"></p>`;document.body.append(d);d.showModal();d.querySelector('button')?.focus();return d;}
function r3Panel(){r3Parent(wq20Marked());const s=r3Settings();r3Dialog('家庭備份與遊戲時間',`<div class="notice">備份包括全部孩子的英文、普通數學、奧數、遊戲、時間設定，以及自訂的圖片和音檔。不包含登入密碼。請把檔案當作私人資料，妥善保管。</div><div class="r3-grid"><section><h2>一次備份整個家庭</h2><button class="btn soft" data-r32="health">裝置與儲存檢查</button><button class="btn primary" data-r3="export-family">匯出家庭完整備份</button><button class="btn secondary" data-r3="choose-family">還原家庭備份</button><input id="r3-family-file" type="file" accept=".json,application/json" hidden><p>還原前先顯示所有孩子及紀錄數，確認後才取代目前家庭資料。</p><button class="btn soft" data-r3="recover">處理未完成的操作</button><button class="btn soft" data-r3="legacy-math">轉入舊數學紀錄</button></section><section><h2>遊戲時間</h2><label>每日玩遊戲的時間上限（分鐘）<input id="r3-limit" type="number" min="5" max="180" value="${s.limitMinutes}"></label><button class="btn primary" data-r3="save-plan">儲存</button><p>學習沒有時間限制。</p></section></div><section>${r3ReportHTML()}</section><section><h2>讀題聲音</h2><label>模式<select id="r3-voice-mode"><option value="device" ${s.voice.mode==='device'?'selected':''}>裝置的聲音</option><option value="server" ${s.voice.mode==='server'?'selected':''}>自設語音服務</option></select></label><label>語音服務的路徑（同一個網站內）<input id="r3-voice-endpoint" value="${esc(s.voice.endpoint||'/api/speech')}" maxlength="240"></label><label>聲音代號<input id="r3-voice-id" value="${esc(s.voice.voice)}" maxlength="32"></label><label><input id="r3-voice-consent" type="checkbox" ${s.voice.consent?'checked':''}>同意把讀題及英文教材文字傳到設定的語音服務（不傳孩子姓名）</label><button class="btn secondary" data-r3="save-voice">儲存聲音設定</button><p>還沒安裝語音服務，或沒有設定伺服器金鑰時，固定的聲音不能使用。請不要把 API 金鑰貼在這裏。</p></section>`);}
function r3Plan(){const s=r3Settings(),c=activeChild(),r=r3Weekly();r3Dialog('今天的跨科學習',`<p>${esc(c.name)}，照下面的次序，完成今天的小目標。每個入口的作答和獎勵規則都不變。</p><div class="r3-grid">${[['english','英文',s.englishMinutes,'溫習到期及較弱的英文項目'],['math','普通數學',s.mathMinutes,'先重溫弱項，再按學校單元練習'],['olympiad','奧數思維',s.olympiadMinutes,'自願加入，進度不與普通數學混合']].filter(x=>x[2]>0).map(([key,n,min,description])=>`<section><h2>${n}</h2><p>建議 ${min} 分鐘</p><p>${description}</p><button class="btn primary" data-r3="study-${key}">開始${n}</button></section>`).join('')}</div><p>今天一共用了 ${Math.ceil(F3.usageTotal(s,c.id)/60000)}／${s.limitMinutes} 分鐘。</p>`);}
function r3Decorate(){if(isLoggedIn()&&localStorage.getItem(r3Marker())&&!document.getElementById('r3-recovery-banner')){const b=document.createElement('aside');b.id='r3-recovery-banner';b.className='dangerbox';b.innerHTML='<strong>上次有一個操作沒有完成，所以暫時不能儲存。請到「家長 → 家庭管理」按「處理未完成的操作」。</strong> <button class=\"btn secondary\" data-r3=\"recover\">處理未完成的操作</button> <button class=\"btn soft\" data-r3=\"family\">家庭管理／還原備份</button>';document.getElementById('app')?.prepend(b);} const route=(location.hash||'#kid').slice(1).split('?')[0];if(false){const box=document.createElement('section');box.id='r3-daily';box.className='card pad';box.innerHTML='<h2>英文、數學與思維，一次安排</h2><p>每一科的進度分開，共用同一個每日時間安排。</p><button class="btn primary" data-r3="daily">今天的跨科任務</button>';document.getElementById('app')?.prepend(box);}if(['settings','parent','report'].includes(route)&&v23ParentAllowed()&&!document.getElementById('r3-family-entry')){const box=document.createElement('section');box.id='r3-family-entry';box.className='card pad';box.innerHTML='<h2>家庭完整備份</h2><p>一次備份英文、數學、奧數、遊戲和自訂的圖片音檔，也可轉入舊數學紀錄。</p><button class="btn primary" data-r3="family">打開家庭管理</button>';document.getElementById('app')?.prepend(box);}const badge=document.getElementById('v25-build-badge');if(badge)badge.textContent='學霸星球';}
const r3Render=render;render=function(){const out=r3Render.apply(this,arguments);r3Decorate();return out;};
let r3PendingRestore=null,r3PendingOwner='';
document.addEventListener('change',async e=>{if(e.target.id!=='r3-family-file')return;try{const wq20R=wq20Marked();r3Parent(wq20R);r3PauseWork({rescue:wq20R});if(wq20R)await wq20RescueCheck();const targetOwner=accountId();r3PendingRestore=await r3ValidatePack(e.target.files[0]);if(targetOwner!==accountId())throw Error('帳戶已改變，請重新選取備份');r3PendingOwner=targetOwner;const p=r3PendingRestore;r3Dialog('確認還原家庭',`<div class="dangerbox">${wq20RestoreNote()}會取代目前家庭的孩子、教材、進度、圖片和音檔，不是合併。登入密碼不變。還原同一個家庭時，會保留現在的金幣、遊戲進度和較長的使用時間，免得重複免費入場。建議先匯出目前家庭備份。</div><ul>${p.english.children.map(c=>`<li>${esc(c.name)}（小${'一二三四五六'[c.grade-1]||c.grade}） · 數學 ${(p.math.find(m=>m.childId===c.id)?.state?.attempts||[]).length} 次作答</li>`).join('')}</ul><p>英文 ${p.english.attempts.length} 筆紀錄；自訂媒體 ${p.media.length} 項。</p><label><input id="r3-restore-consent" type="checkbox">我已核對，確定取代目前家庭</label><button class="btn primary" data-r3="confirm-restore">確認還原</button>`);}catch(err){r3Status(err.message,true);}finally{e.target.value='';}});
function r3Status(text,bad=false){const x=document.getElementById('r3-status');if(x){x.textContent=text;x.className=bad?'dangerbox':'notice';}else toast(text,bad?'bad':undefined);}
document.addEventListener('click',async e=>{const b=e.target.closest?.('[data-r3]');if(!b)return;const act=b.dataset.r3;e.preventDefault();try{if(act==='close'){document.getElementById('r3-dialog')?.close();return;}if(act==='family'){r3Panel();return;}if(act==='daily'){r3Plan();return;}if(act.startsWith('study-')){window.WQR3.assertStudy();document.getElementById('r3-dialog')?.close();const sub=act.slice(6);if(sub==='english'){go('kid');render();startDaily();}else{window.WQMathApp.open(sub==='math'?'normal':'olympiad');window.WQMathApp.startDaily?.(sub==='math'?'normal':'olympiad');}return;}
 if(act==='recover'){const done=await r3Recover();r3Status(done?'還原完成。':'沒有未完成的操作。');return;}const wq20R=wq20Marked();r3Parent(wq20R);b.disabled=true;if(wq20R&&['save-plan','save-voice','legacy-math'].includes(act))throw Error('上次有一個操作沒有完成，這個功能暫時不能用。請先按「處理未完成的操作」，或用備份還原。');if(wq20R&&(act==='choose-family'||act==='confirm-restore'))await wq20RescueCheck();if(act==='export-family'){await r3Export();r3Status(wq20R?'已建立備份，但上次有一個操作沒有完成，內容可能不完整。請先核對孩子和紀錄的數量，再用它還原。':'完整家庭備份已建立，請保管好下載的檔案。');}else if(act==='choose-family')document.getElementById('r3-family-file').click();else if(act==='confirm-restore'){if(!document.getElementById('r3-restore-consent').checked)throw Error('請先核對並勾選取代確認');if(!r3PendingRestore||r3PendingOwner!==accountId())throw Error('帳戶已改變或未選擇備份，請重新選擇');await r3Restore(r3PendingRestore);r3PendingRestore=null;document.getElementById('r3-dialog')?.close();}else if(act==='recover'){const done=await r3Recover();r3Status(done?'還原完成。':'沒有未完成的操作。');}else if(act==='legacy-math'){document.getElementById('r3-dialog')?.close();window.WQMathApp.open('parent');toast('在數學家長頁按「轉入舊數學紀錄」，核對來源和目前的孩子。');}else if(act==='save-plan'){const n=r3Clone(r3Settings());n.limitMinutes=Number(document.getElementById('r3-limit').value);n.englishMinutes=0;n.mathMinutes=0;n.olympiadMinutes=0;r3SaveSettings(n);r3Status('遊戲時間已儲存。');}else if(act==='download-report'){r3Download('SmartQuest_Weekly_'+F3.day()+'.json',{profile:{name:activeChild().name,grade:activeChild().grade},report:r3Weekly()});}else if(act==='save-voice'){const n=r3Clone(r3Settings());n.voice={mode:document.getElementById('r3-voice-mode').value,endpoint:document.getElementById('r3-voice-endpoint').value,voice:document.getElementById('r3-voice-id').value,consent:document.getElementById('r3-voice-consent').checked};if(n.voice.mode==='server'&&!n.voice.consent)throw Error('未同意傳送題目文字；沒有開啟語音服務');r3SaveSettings(n);r3Status('設定已儲存。要另外安裝語音服務才能使用。');}}catch(err){r3Status(err.message,true);}finally{b.disabled=false;}});
function r3CurrentSubject(){if(document.getElementById('wqm-dialog')?.open){const v=window.WQMathApp?.getView();if(['parent','profiles','resume'].includes(v))return null;return window.WQMathApp?.getState()?.current?.track==='olympiad'||v==='olympiad'?'olympiad':'math';}const rt=(location.hash||'#kid').slice(1).split('?')[0];if(pgPlaying||arEngine&&!arEngine.paused||miniGame&&!miniGame.ended)return 'arcade';if(['learn','learning','assembly-learn','family-lesson','phonics-lesson','practice','quiz','test'].includes(rt))return 'english';return null;}
function r3ArcadeMs(s){const d=s.usage?.[activeChild()?.id]?.[F3.day()];return d?(d.arcade||0):0;}
function r3Tick(){const now=performance.now(),dt=Math.min(2500,Math.max(0,now-r3LastTick));r3LastTick=now;const sc=(accountId()||'guest')+':'+activeChild()?.id;if(r3LastScope!==sc){r3LastScope=sc;return;}if(document.hidden||!document.hasFocus()||r3Busy||document.getElementById('r3-dialog')?.open||!isLoggedIn()||!v24CanWrite())return;const subject=r3CurrentSubject();if(subject!=='arcade')return;try{const n=r3Clone(r3Settings());F3.addUsage(n,activeChild().id,subject,dt);r3SaveSettings(n);if(r3ArcadeMs(n)>=n.limitMinutes*60000)r3Block();}catch(e){persistenceIssue='時間紀錄儲存失敗，已暫停學習：'+e.message;showSaveIssue();r3Block(true);}}
function r3Block(storageFailure=false){pgPause();if(arEngine&&!arEngine.paused)arPause();stopSpeech();if(document.getElementById('r3-time-limit')?.open)return;const d=document.createElement('dialog');d.id='r3-time-limit';d.className='r3-dialog';d.innerHTML=`<h1>${storageFailure?'資料暫時儲存不到。':'今天玩夠了'}</h1><p>${storageFailure?'請不要關閉這個頁面。檢查儲存設定，或匯出備份。':'今天的遊戲時間用完了。去學習，明天再玩。家長可以調整遊戲時間。'}</p><button class="btn primary" id="r3-limit-home">返回首頁</button>`;document.body.append(d);d.showModal();d.addEventListener('cancel',e=>e.preventDefault());d.querySelector('button').onclick=()=>{d.close();d.remove();window.WQMathApp?.close();go('kid');render();};}
window.WQR3=Object.freeze({version:'R3.7.0',dataBusy:()=>r3Busy,assertStudy(){if(r3Busy||isLoggedIn()&&localStorage.getItem(r3Marker()))throw Error('有操作沒有完成。請先到家長頁按「處理未完成的操作」。');},assertPlay(){window.WQR3.assertStudy();if(isLoggedIn()){const s=r3Settings();if(r3ArcadeMs(s)>=s.limitMinutes*60000)throw Error('今天的遊戲時間用完了。明天再玩，或由家長調整。');}},canStudy:()=>{try{window.WQR3.assertStudy();return true;}catch(e){toast(e.message,'bad');return false;}},voice:()=>r3Clone(r3Settings().voice),canPlay:()=>{try{window.WQR3.assertPlay();return true;}catch(e){toast(e.message,'bad');return false;}},recordMigration(digest,target){const n=r3Clone(r3Settings());if(n.migrationReceipts.some(r=>r.digest===digest&&r.target===target))throw Error('這份舊備份已轉入目前的孩子，沒有重複轉入。');n.migrationReceipts.push({digest,target,at:Date.now()});n.migrationReceipts=n.migrationReceipts.slice(-300);r3SaveSettings(n);},hasMigration:(digest,target)=>r3Settings().migrationReceipts.some(r=>r.digest===digest&&r.target===target),remaining:()=>Math.max(0,r3Settings().limitMinutes*60000-r3ArcadeMs(r3Settings())),openFamily:()=>r3Panel()});
setInterval(r3Tick,1000);document.addEventListener('visibilitychange',()=>r3LastTick=performance.now());window.addEventListener('blur',()=>r3LastTick=performance.now());window.addEventListener('focus',()=>r3LastTick=performance.now());window.addEventListener('storage',e=>{if(e.key===r3FamilyKey()){r3SettingsOwner='';try{r3Settings();}catch(err){r3Status(err.message,true);}}});

document.addEventListener('click',e=>{if(r3Busy&&!e.target.closest?.('#r3-dialog')){e.preventDefault();e.stopImmediatePropagation();}},true);

