const r3PriorPgBuy=pgBuy;pgBuy=async function(){if(!WQR3.canPlay())return;return r3PriorPgBuy.apply(this,arguments);};
const r3PriorPgPlay=pgPlay;pgPlay=async function(){if(!WQR3.canPlay())return;return r3PriorPgPlay.apply(this,arguments);};
const r3PriorArPlay=arPlay;arPlay=async function(){if(!WQR3.canPlay())return;return r3PriorArPlay.apply(this,arguments);};
const r36PriorA28Buy=a28Buy;a28Buy=async function(){if(!WQR3.canPlay())return;return r36PriorA28Buy.apply(this,arguments);};
if(isLoggedIn()&&localStorage.getItem(r3Marker())){loadBlocked=true;persistenceIssue='上次有一個操作沒有完成，暫時不能儲存。請到「家長 → 家庭管理」按「處理未完成的操作」。如果備用紀錄不見了，請用家庭備份還原。';}

