const r3OfflinePanel=r3Panel;r3Panel=function(){r3OfflinePanel();const body=document.querySelector('#r3-dialog .r3-body')||document.getElementById('r3-dialog');const box=document.createElement('section');box.innerHTML='<h2>離線相片辨認</h2><p>程式包沒有附上完整的相片辨認資料。連上網絡時，可以下載到這個瀏覽器。之後就能在本機辨認印刷的英文字。不支援手寫。</p><button class="btn secondary" id="r3-prepare-offline">準備離線相片辨認</button><button class="btn soft" id="r3-check-offline">檢查離線資源</button>';body.append(box);box.querySelector('#r3-prepare-offline').onclick=async()=>{try{await r3PrepareOffline();}catch(e){r3Status(e.message,true);}};box.querySelector('#r3-check-offline').onclick=async()=>r3Status(await r3OcrStatus()?'相片辨認資料已齊全。請關掉網絡，實際試一次。':'相片辨認資料不齊全，或離線功能還沒啟用。');};

// Existing English material preparation keeps its verified WAV pipeline and playback flags.
