  html+='<section class="card pad p10-about" id="p10-about"><h2>關於這個程式</h2><p class="small muted">學霸星球 SmartQuest Planet'+(ver?' '+esc(ver):'')+'</p></section>';
  app.insertAdjacentHTML('beforeend',html);
