 try{for(const x of LIB30.words.values()){const k=r37ZhKey(x.meaning);if(!k)continue;(by[k]=by[k]||new Set()).add(x.form);if(R37_FORM_TAG.test(String(x.meaning)))tagged.add(x.form);}}catch(_){}
