 const worlds=r37G3Worlds(subj),t=r37G3Track(g,subj);
 let w=r37Mem._gw&&r37Mem._gw[t];if(!Number.isInteger(w)){w=0;for(let i=0;i<worlds.length;i++)if(r37G3WorldOpen(g,subj,i))w=i;}
