  const goUp=lvl<3?act(r.passed?'r37-go':'r37-sec','data-r37="dz-next"','▶',`第 ${lvl+1} 級`):g<n-1?act(r.passed?'r37-go':'r37-sec','data-r37="dz-next"','▶',`下一組 ${g+2}`):'';
