  let c=null;
  for(let k=0;k<8&&!c;k++){try{c=WQ37Math.make(track,m.w,m.s,6,diff,seed+k*7+1,[m.q,...(r37Get().recent[track]||[]).slice(-30)]).find(x=>x.skill===m.sk&&x.q!==m.q)||null;}catch(_){c=null;}}
