   let g='',bad=false;for(let k=r.from;k<r.to;k++){g+=one(chars[k],k);if(!flags[k])bad=true;}
   out+=(prevEnd===i?'<span class="r37-sd" aria-hidden="true">·</span>':'')+`<span class="r37-sy2${bad?' bad':''}">${g}</span>`;prevEnd=r.to;i=r.to;continue;
