 if(mode==='crop'){s50ReplaceAt=Date.now();v20Crop();return;}
 s50ReplaceAt=Date.now();
 const root=s50Root();
 const cb=document.createElement('input');cb.type='checkbox';cb.id='v20-enhance';cb.hidden=true;cb.checked=true;
