     const ks=['arch','log','gem'];for(let i=2;i>0;i--){const j=Math.floor(s.rng()*(i+1));[ks[i],ks[j]]=[ks[j],ks[i]];}
     o.kinds=ks;o.kind=6;pl.mix++;
